ty"},{"key":"D","text":"either"}]},{"n":2,"options":[{"key":"A","text":"need to be inspired"},{"key":"B","text":"are inspired"},{"key":"C","text":"inspired"},{"key":"D","text":"have inspired"}]},{"n":3,"options":[{"key":"A","text":"betray"},{"key":"B","text":"prosper"},{"key":"C","text":"provide"},{"key":"D","text":"benefit"}]},{"n":4,"options":[{"key":"A","text":"a thousand"},{"key":"B","text":"thousand’s"},{"key":"C","text":"thousands"},{"key":"D","text":"thousands’"}]},{"n":5,"options":[{"key":"A","text":"will"},{"key":"B","text":"need"},{"key":"C","text":"would"},{"key":"D","text":"ought"}]},{"n":6,"options":[{"key":"A","text":"conquer"},{"key":"B","text":"accomplish"},{"key":"C","text":"gather"},{"key":"D","text":"achieve"}]},{"n":7,"options":[{"key":"A","text":"pace"},{"key":"B","text":"piece"},{"key":"C","text":"peace"},{"key":"D","text":"peach"}]},{"n":8,"options":[{"key":"A","text":"must be"},{"key":"B","text":"needs being"},{"key":"C","text":"have to be"},{"key":"D","text":"would be"}]},{"n":9,"options":[{"key":"A","text":"lets"},{"key":"B","text":"allows"},{"key":"C","text":"enhances"},{"key":"D","text":"prevents"}]}]}$mtr$::jsonb, null)
