insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2006-maj-kozep-L2$mtr$, $mtr$2006-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 10, 6, $mtr${"id":"2006-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read a text about sharks. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (7-16) after the text.","Use only one word in each gap."],"title":"JAWS II","body":["It is fast and savage and likes to sneak up on its prey. Which means that the mako shark does {{0}} make the most relaxing of swimming companions.","So the news {{7}} two mako sharks have been seen off Cornwall in just two weeks could leave some bathers preferring to stay on the shore.","Yesterday beaches across the region were on red alert after {{8}} fisherman reported seeing a mako jumping from the water just a mile from a popular beach.","Alan Britton, 52, {{9}} terrified when he saw the shark – a cousin {{10}} the great white shark – jump from the water as he and three friends enjoyed a fishing trip.","‘I couldn’t {{11}} my eyes,’ he said. ‘{{12}} jumped clean out of the water just yards away from the boat.’","It was {{13}} second mako shark to be spotted off the Cornish coast in just two weeks. Last month, Gwithian beach near Hayle was evacuated {{14}} one was seen prowling close to the shore.","Shark expert Lindsay Holloway, from the Blue Reef Aquarium in Newquay, said bathers {{15}} not risk staying in the water when a mako was around. ‘The best thing to {{16}} is get out of the water as soon as you can,’ he said."],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["not"]},{"n":7},{"n":8},{"n":9},{"n":10},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2006-maj-kozep-L2$mtr$, $mtr${"id":"2006-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read a text about sharks. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (7-16) after the text.","Use only one word in each gap."],"title":"JAWS II","body":["It is fast and savage and likes to sneak up on its prey. Which means that the mako shark does {{0}} make the most relaxing of swimming companions.","So the news {{7}} two mako sharks have been seen off Cornwall in just two weeks could leave some bathers preferring to stay on the shore.","Yesterday beaches across the region were on red alert after {{8}} fisherman reported seeing a mako jumping from the water just a mile from a popular beach.","Alan Britton, 52, {{9}} terrified when he saw the shark – a cousin {{10}} the great white shark – jump from the water as he and three friends enjoyed a fishing trip.","‘I couldn’t {{11}} my eyes,’ he said. ‘{{12}} jumped clean out of the water just yards away from the boat.’","It was {{13}} second mako shark to be spotted off the Cornish coast in just two weeks. Last month, Gwithian beach near Hayle was evacuated {{14}} one was seen prowling close to the shore.","Shark expert Lindsay Holloway, from the Blue Reef Aquarium in Newquay, said bathers {{15}} not risk staying in the water when a mako was around. ‘The best thing to {{16}} is get out of the water as soon as you can,’ he said."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["not"]},{"n":7,"accept":["that"]},{"n":8,"accept":["a"]},{"n":9,"accept":["was","got","became","felt"]},{"n":10,"accept":["of"]},{"n":11,"accept":["believe"]},{"n":12,"accept":["it"]},{"n":13,"accept":["the"]},{"n":14,"accept":["after","when","as","because","since"]},{"n":15,"accept":["should","must"]},{"n":16,"accept":["d