insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2006-okt-kozep-H3$mtr$, $mtr$2006-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 6, 10, $mtr${"id":"2006-okt-kozep-H3","number":3,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":6,"instructions":["In this section you are going to hear a news item about a famous guitar.","Your task will be to circle the letter or letters of the correct answer or answers in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you might have to circle one or two letters.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_06okt_fl.mp3","start":1325.44,"end":1797.28,"clip":"hang/k_angol_06okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"This news item is from …","options":[{"key":"A","text":"England."},{"key":"B","text":"Germany."}],"answer":["A"]},{"n":20,"stem":"What is special about this guitar is that it is …","options":[{"key":"A","text":"John Lennon's first electric guitar."},{"key":"B","text":"signed by the members of the Beatles."}]},{"n":21,"stem":"The guitar has spent the last twenty years in …","options":[{"key":"A","text":"the safe of a bank."},{"key":"B","text":"Frank Dostal's house."}]},{"n":22,"stem":"The Star Club plays an important role in the history of the guitar, because …","options":[{"key":"A","text":"it is the place where Dostal's band won it in a talent contest."},{"key":"B","text":"the Beatles played there."}]},{"n":23,"stem":"Today, Frank Dostal is …","options":[{"key":"A","text":"the owner of the Star Club."},{"key":"B","text":"a record producer."}]},{"n":24,"stem":"The guitar was smuggled out of Germany, because they were afraid that …","options":[{"key":"A","text":"it might get stolen."},{"key":"B","text":"the German government would not let it out of the country."}]},{"n":25,"stem":"Dostal is not planning to sell the guitar because …","options":[{"key":"A","text":"he is not satisfied with the amount of money he's been offered for it."},{"key":"B","text":"it is too precious to him."}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_06okt_fl.mp3","start":1325.44,"end":1797.28,"clip":"hang/k_angol_06okt_fl_H3.mp3"}$mtr$::jsonb)
