insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2007-maj-kozep-H2$mtr$, $mtr$2007-maj-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 8, 9, $mtr${"id":"2007-maj-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section you are going to hear an interview with Laura, a sixteen-year-old Canadian girl who is in Hungary on a Rotary Club scholarship.","Your task is to write the letter of the correct answer into the boxes on the right.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work.","A= TRUE B= FALSE C= THE TEXT DOES NOT SAY"],"audio":{"file":"k_angol_07maj_fl.mp3","start":808.91,"end":1304.31,"clip":"hang/k_angol_07maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Laura is staying with a Hungarian family during her visit.","answer":"C"},{"n":10,"stem":"Rotary says that students should phone their parents as often as possible."},{"n":11,"stem":"Laura has spent 8 hours on the phone with Canada in the past six weeks."},{"n":12,"stem":"She says that frequent phone-calls make her feel terribly homesick."},{"n":13,"stem":"Laura's father is a university professor."},{"n":14,"stem":"Her grandparents live in Ontario."},{"n":15,"stem":"Laura hasn't talked to her mother for more than a week."},{"n":16,"stem":"She is not particularly fond of emails."},{"n":17,"stem":"She does not use phone cards because they are too expensive."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_07maj_fl.mp3","start":808.91,"end":1304.31,"clip":"hang/k_angol_07maj_fl_H2.mp3"}$mtr$::jsonb)
