insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2007-maj-kozep-H3$mtr$, $mtr$2007-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$feleletválasztás hallás után$mtr$, 7, 10, $mtr${"id":"2007-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"feleletválasztás hallás után","points":7,"instructions":["In this section you are going to hear a news report about a strange accident.","Your task is to write the letter of the correct answer into the boxes on the right.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_07maj_fl.mp3","start":1304.31,"end":1814.62,"clip":"hang/k_angol_07maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"This news report comes from ….","options":[{"key":"A","text":"Australia"},{"key":"B","text":"Austria"},{"key":"C","text":"Algeria"}],"answer":"A"},{"n":18,"stem":"The report is about a man who works …","options":[{"key":"A","text":"with kangaroos."},{"key":"B","text":"for a company which makes road signs."},{"key":"C","text":"as a traffic warden."}]},{"n":19,"stem":"The man was riding a … when the accident happened.","options":[{"key":"A","text":"kangaroo"},{"key":"B","text":"bicycle"},{"key":"C","text":"motorbike"}]},{"n":20,"stem":"He ran into a …","options":[{"key":"A","text":"warning sign."},{"key":"B","text":"kangaroo."},{"key":"C","text":"motorbike."}]},{"n":21,"stem":"His colleagues sent him a …","options":[{"key":"A","text":"card."},{"key":"B","text":"real road sign."},{"key":"C","text":"toy kangaroo."}]},{"n":22,"stem":"Skippy is the name of …","options":[{"key":"A","text":"a famous Australian actor."},{"key":"B","text":"a kangaroo."},{"key":"C","text":"a popular Australian film."}]},{"n":23,"stem":"There are about 57 million … in Australia.","options":[{"key":"A","text":"warning signs for kangaroos"},{"key":"B","text":"people"},{"key":"C","text":"kangaroos"}]},{"n":24,"stem":"More than 70% of … accidents were caused by kangaroos in Australia in 2004.","options":[{"key":"A","text":"animal-related"},{"key":"B","text":"car"},{"key":"C","text":"road"}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_07maj_fl.mp3","start":1304.31,"end":1814.62,"clip":"hang/k_angol_07maj_fl_H3.mp3"}$mtr$::jsonb)
