insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2007-okt-emelt-H3$mtr$, $mtr$2007-okt-emelt$mtr$, $mtr$listening$mtr$, 3, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 11, 11, $mtr${"id":"2007-okt-emelt-H3","number":3,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":11,"instructions":["In this section you are going to hear an interview with Dr. Wilson, a psychologist about the concept of genius.","Your task will be to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you might have to circle one or two letters.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"e_angol_07okt_fl.mp3","start":1041.49,"end":1796.47,"clip":"hang/e_angol_07okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Dr. Wilson is ...","options":[{"key":"A","text":"from the Institute of Psychology."},{"key":"B","text":"an expert on the concept of genius."}],"answer":["A","B"]},{"n":16,"stem":"In Dr. Wilson's view, ...","options":[{"key":"A","text":"the relationship between IQ scores and genius is not clear."},{"key":"B","text":"geniuses do not necessarily have very high IQ scores."}]},{"n":17,"stem":"According to Dr. Wilson, both Edison and Einstein ...","options":[{"key":"A","text":"were rather bad students."},{"key":"B","text":"would probably have achieved fairly average scores on an IQ test."}]},{"n":18,"stem":"W.J. Sidis ...","options":[{"key":"A","text":"had the highest IQ score in history."},{"key":"B","text":"was an American psychiatrist."}]},{"n":19,"stem":"As a young child, Sidis ...","options":[{"key":"A","text":"learned Latin and Greek."},{"key":"B","text":"wrote an article for the New York Times."}]},{"n":20,"stem":"By the age of eight, Sidis had completed ...","options":[{"key":"A","text":"primary school."},{"key":"B","text":"secondary school."}]},{"n":21,"stem":"Sidis ...","options":[{"key":"A","text":"became a Harvard student at the age of 9."},{"key":"B","text":"graduated from Harvard at the age of 19."}]},{"n":22,"stem":"Sidis ...","options":[{"key":"A","text":"became a professor of history."},{"key":"B","text":"could speak more than forty languages and dialects."}]},{"n":23,"stem":"At the age of 26, Sidis ...","options":[{"key":"A","text":"gave up his academic career."},{"key":"B","text":"bought a department store in New York."}]},{"n":24,"stem":"Sidis ...","options":[{"key":"A","text":"had a lot of different jobs."},{"key":"B","text":"died in a hotel."}]},{"n":25,"stem":"Dr. Wilson says that a child with an IQ score of around 115 ...","options":[{"key":"A","text":"is bright enough to succeed in anything in the future."},{"key":"B","text":"can be called a genius."}]},{"n":26,"stem":"Dr. Wilson suggests that ...","options":[{"key":"A","text":"ambition and desire are less important than intelligence."},{"key":"B","text":"hard work is more important than intelligence."}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_07okt_fl.mp3","start":1041.49,"end":1796.47,"clip":"hang/e_angol_07okt_fl_H3.mp3"}$mtr$::jsonb)
