insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2008-maj-kozep-L2$mtr$, $mtr$2008-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 9, 6, $mtr${"id":"2008-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read an article about the effect of human activity on geography. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-19) after the text.","Use only one word in each gap."],"title":"RUINING THE PLANET","body":["Man’s behaviour is changing the face of the Earth so rapidly {{0}} famous landmarks could soon disappear from the map – this {{11}} what some recent disturbing pictures of the Aral Sea {{12}} Central Asia show.","The damage caused by draining lakes and rivers has resulted in thousands of changes in {{13}} newly-published 10th edition of ‘The Times Concise Atlas {{14}} the World’.","The Dead Sea could disappear in 20 years and Lake Chad in Africa is 95 per cent smaller {{15}} it was in 1963. The Colorado River in America and the Aral Sea could {{16}} lost entirely. Global warming has caused massive changes to mountains that were once covered with snow. Even Mount Kilimanjaro in Africa will lose its famous snows {{17}} the planet continues to heat up at this rate.","Atlas spokesman Simon Judges said: “Our latest edition shows the fact {{18}} humans are creating and destroying both our geography {{19}} our weather system. The consequences could be catastrophic.”"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["that"]},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17},{"n":18},{"n":19}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2008-maj-kozep-L2$mtr$, $mtr${"id":"2008-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":9,"instructions":["You are going to read an article about the effect of human activity on geography. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-19) after the text.","Use only one word in each gap."],"title":"RUINING THE PLANET","body":["Man’s behaviour is changing the face of the Earth so rapidly {{0}} famous landmarks could soon disappear from the map – this {{11}} what some recent disturbing pictures of the Aral Sea {{12}} Central Asia show.","The damage caused by draining lakes and rivers has resulted in thousands of changes in {{13}} newly-published 10th edition of ‘The Times Concise Atlas {{14}} the World’.","The Dead Sea could disappear in 20 years and Lake Chad in Africa is 95 per cent smaller {{15}} it was in 1963. The Colorado River in America and the Aral Sea could {{16}} lost entirely. Global warming has caused massive changes to mountains that were once covered with snow. Even Mount Kilimanjaro in Africa will lose its famous snows {{17}} the planet continues to heat up at this rate.","Atlas spokesman Simon Judges said: “Our latest edition shows the fact {{18}} humans are creating and destroying both our geography {{19}} our weather system. The consequences could be catastrophic.”"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["that"]},{"n":11,"accept":["is"]},{"n":12,"accept":["in","of","from","and"]},{"n":13,"accept":["the"]},{"n":14,"accept":["of"]},{"n":15,"accept":["than"]},{"n":16,"accept":["be"]},{"n":17,"accept":["if"]},{"n":18,"accept":["that"]},{"n":19,"accept":["and"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2008-maj-kozep-L3$mtr$, $mtr$2008-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 7, 7, $mtr${"id":"2008-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":7,"instructions":["You are going to read an article about some ancient writing found in Mexico. Some words are missing from the text.","Use the words in brackets to form one word for each of the gaps (20-26).","Then write these words on the dotted lines after the text in the appropriate form.","You might find words that you do not have to change."],"title":"OLDEST WRITING IN THE NEW WORLD","body":["Items men, women, and children left behind when they died – everything from clothing to jewellery and tools – tell {{0}} a lot. And sometimes even their words survive.","Experts believe that a {{20}} in Mexico is the oldest example of writing ever found in the Americas. The people who created it {{21}} lived 3,000 years ago, long before Christopher Columbus arrived in the New World.","Digging in a stone mine, {{22}} noticed a stone block with marks carved onto its surface. They found the large piece of stone in Cascajal, Mexico, near the capital city of an ancient people called the Olmec. \"There are signs on the block that seem to show {{23}} objects they used. For example, there is a sign that looks like a throne,\" an expert says. \"It is {{24}} because it makes it clear that the Olmec could read and write.\" But experts don’t know {{25}} what the writing says. If you have ever tried to figure out a message {{26}} in code, you have a pretty good idea of the hard work ahead. Finding other examples of Olmec writing could help crack the code."],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"anthropology","example":true,"accept":["anthropologists"]},{"n":20,"prompt":"discover"},{"n":21,"prompt":"probable"},{"n":22,"prompt":"work"},{"n":23,"prompt":"religion"},{"n":24,"prompt":"excite"},{"n":25,"prompt":"exact"},{"n":26,"prompt":"write"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2008-maj-kozep-L3$mtr$, $mtr${"id":"2008-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":7,"instructions":["You are going to read an article about some ancient writing found in Mexico. Some words are missing from the text.","Use the words in brackets to form one word for each of the gaps (20-26).","Then write these words on the dotted lines after the text in the appropriate form.","You might find words that you do not have to change."],"title":"OLDEST WRITING IN THE NEW WORLD","body":["Items men, women, and children left behind when they died – everything from clothing to jewellery and tools – tell {{0}} a lot. And sometimes even their words survive.","Experts believe that a {{20}} in Mexico is the oldest example of writing ever found in the Americas. The people who created it {{21}} lived 3,000 years ago, long before Christopher Columbus arrived in the New World.","Digging in a stone mine, {{22}} noticed a stone block with marks carved onto its surface. They found the large piece of stone in Cascajal, Mexico, near the capital city of an ancient people called the Olmec. \"There are signs on the block that seem to show {{23}} objects they used. For example, there is a sign that looks like a throne,\" an expert says. \"It is {{24}} because it makes it clear that the Olmec could read and write.\" But experts don’t know {{25}} what the writing says. If you have ever tried to figure out a message {{26}} in code, you have a pretty good idea of the hard work ahead. Finding other examples of Olmec writing could help crack the code."],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"anthropology","example":true,"accept":["anthropologists"]},{"n":20,"prompt":"discover","accept":["discovery"]},{"n":21,"prompt":"probable","accept":["probably"]},{"n":22,"prompt":"work","accept":["workers","workmen"]},{"n":23,"prompt":"religion","accept":["religious"]},{"n":24,"prompt":"excite","accept":["exciting"]},{"n":25,"prompt":"exact","accept":["exactly"]},{"n":26,"prompt":"write","accept":["written"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
