insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2008-maj-kozep-H3$mtr$, $mtr$2008-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 8, 10, $mtr${"id":"2008-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section you are going to hear an interview with Laura, a sixteen-year-old Canadian girl, who is in Hungary on a scholarship, about the differences between Hungarian and Canadian prices.","Your task is to write the letter of the correct answer into the boxes on the right.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work.","A= TRUE B= FALSE C= THE TEXT DOES NOT SAY"],"audio":{"file":"k_angol_08maj_fl.mp3","start":1168.88,"end":1796.7,"clip":"hang/k_angol_08maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Hungarian prices are generally a lot lower than Canadian ones.","answer":"A"},{"n":16,"stem":"Quality makeup is surprisingly cheap in Hungary."},{"n":17,"stem":"The interviewer suggests that cultural things are fairly cheap in Hungary."},{"n":18,"stem":"Cinemas are a lot more expensive in Canada."},{"n":19,"stem":"Cinemas are rather dangerous places in Canada."},{"n":20,"stem":"Laura has never been to a Broadway musical."},{"n":21,"stem":"The interviewer suggests that theatre tickets are not cheap for Hungarians."},{"n":22,"stem":"Public transport is a lot better in Hungary than in Canada."},{"n":23,"stem":"Food is more expensive in Canada than in Hungary."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_08maj_fl.mp3","start":1168.88,"end":1796.7,"clip":"hang/k_angol_08maj_fl_H3.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2008-maj-kozep-H3$mtr$, $mtr${"id":"2008-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section you are going to hear an interview with Laura, a sixteen-year-old Canadian girl, who is in Hungary on a scholarship, about the differences between Hungarian and Canadian prices.","Your task is to write the letter of the correct answer into the boxes on the right.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work.","A= TRUE B= FALSE C= THE TEXT DOES NOT SAY"],"audio":{"file":"k_angol_08maj_fl.mp3","start":1168.88,"end":1796.7,"clip":"hang/k_angol_08maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Hungarian prices are generally a lot lower than Canadian ones.","answer":"A"},{"n":16,"stem":"Quality makeup is surprisingly cheap in Hungary.","answer":"B"},{"n":17,"stem":"The interviewer suggests that cultural things are fairly cheap in Hungary.","answer":"A"},{"n":18,"stem":"Cinemas are a lot more expensive in Canada.","answer":"A"},{"n":19,"stem":"Cinemas are rather dangerous places in Canada.","answer":"C"},{"n":20,"stem":"Laura has never been to a Broadway musical.","answer":"A"},{"n":21,"stem":"The interviewer suggests that theatre tickets are not cheap for Hungarians.","answer":"B"},{"n":22,"stem":"Public transport is a lot better in Hungary than in Canada.","answer":"C"},{"n":23,"stem":"Food is more expensive in Canada than in Hungary.","answer":"A"}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
