insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2008-okt-kozep-L2$mtr$, $mtr$2008-okt-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$bank$mtr$, $mtr$szóbank (szavak visszahelyezése)$mtr$, 9, 6, $mtr${"id":"2008-okt-kozep-L2","number":2,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":9,"instructions":["You are going to read a humorous story. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-L) for each gap (11-19) in the text. Write the letter of the appropriate word in the white box.","Each word can be used once.","There is one extra word that you do not need to use."],"title":"WORKING ON THE ROAD","body":["A fellow stopped at a rural gas station and, after filling his tank, he paid the {{0}} and bought a soft drink.","He stood by his car to drink his cola and {{11}} a couple of men working along the roadside. One dug a hole, two or three feet {{12}}, and then moved on. The other man came along behind and filled in the hole. While one was digging a new {{13}}, the other was about 25 feet behind filling in the old. \"I can't stand this,\" thought the man, {{14}} the can in a trash container and heading down the road toward the men.","\"Hold it, hold it,\" he said to the workers. \"{{15}} you tell me what's going on here with this digging?\"","\"Well, we work for the county government,\" one of the men said.","\"But one of you is digging a hole and the {{16}} is filling it up.","You're not accomplishing anything. Aren't you {{17}} the county's money?\"","\"You {{18}} understand, mister,\" one of the men said.","\"Normally, there are three of us, Rodney, Mike and me. I dig the hole, Rodney puts in the tree and Mike here puts the earth {{19}}. Now that Rodney's sick, it doesn't mean we can't work, does it?\""],"bank":[{"key":"A","text":"BACK"},{"key":"B","text":"BILL"},{"key":"C","text":"CAN"},{"key":"D","text":"DEEP"},{"key":"E","text":"DON’T"},{"key":"F","text":"HOLE"},{"key":"G","text":"OTHER"},{"key":"H","text":"OFFERED"},{"key":"I","text":"THROWING"},{"key":"K","text":"WASTING"},{"key":"L","text":"WATCHED"}],"items":[{"n":0,"example":true,"answer":"B"},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17},{"n":18},{"n":19}]}$mtr$::jsonb, null)
