insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-okt-kozep-H2$mtr$, $mtr$2009-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 7, 9, $mtr${"id":"2009-okt-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":7,"instructions":["In this section, you are going to hear some interesting information about the history of submarines.","Your task will be to give short answers to the questions below.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_09okt_fl.mp3","start":683.83,"end":1260.32,"clip":"hang/k_angol_09okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Who was William Bourne? A British {{gap}}","accept":["mathematician"]},{"n":10,"stem":"When did William Bourne draw plans for a submarine? In {{gap}}"},{"n":11,"stem":"What did Cornelius van Drebbel wrap his wooden rowboat in? In waterproof {{gap}}"},{"n":12,"stem":"How long did he stay underwater? For {{gap}}"},{"n":13,"stem":"When was David Bushnell's submarine built? In {{gap}}"},{"n":14,"stem":"When was David Bushnell's submarine used? During the {{gap}}"},{"n":15,"stem":"Which country were Simon Lake's submarines chosen by? By {{gap}}"},{"n":16,"stem":"What did the submarines use for underwater travel? Electric {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_09okt_fl.mp3","start":683.83,"end":1260.32,"clip":"hang/k_angol_09okt_fl_H2.mp3"}$mtr$::jsonb)
