insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2009-okt-kozep-H3$mtr$, $mtr$2009-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 10, $mtr${"id":"2009-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you are going to hear some interesting facts about Broadway.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter into the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_09okt_fl.mp3","start":1260.32,"end":1795.53,"clip":"hang/k_angol_09okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"A great many famous people live on Broadway.","answer":"C"},{"n":17,"stem":"Broadway starts at the end of Manhattan Island."},{"n":18,"stem":"Broadway is 240 kilometers long."},{"n":19,"stem":"The famous part of Broadway is just a few kilometers long."},{"n":20,"stem":"Tickets for theaters on The Great White Way are extremely expensive."},{"n":21,"stem":"At night Broadway around Times Square is very different from the rest of New York."},{"n":22,"stem":"There are lots of colorful electric signs on the buildings in this part of Broadway."},{"n":23,"stem":"The Great White Way got its name from the color of the buildings in the old days."},{"n":24,"stem":"The word 'Broadway' means top quality American theater art today."},{"n":25,"stem":"Broadway is also famous for its movies."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_09okt_fl.mp3","start":1260.32,"end":1795.53,"clip":"hang/k_angol_09okt_fl_H3.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2009-okt-kozep-H3$mtr$, $mtr${"id":"2009-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you are going to hear some interesting facts about Broadway.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter into the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers.","At the end, you will have some more time to check your work."],"audio":{"file":"k_angol_09okt_fl.mp3","start":1260.32,"end":1795.53,"clip":"hang/k_angol_09okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"A great many famous people live on Broadway.","answer":"C"},{"n":17,"stem":"Broadway starts at the end of Manhattan Island.","answer":"A"},{"n":18,"stem":"Broadway is 240 kilometers long.","answer":"A"},{"n":19,"stem":"The famous part of Broadway is just a few kilometers long.","answer":"B"},{"n":20,"stem":"Tickets for theaters on The Great White Way are extremely expensive.","answer":"C"},{"n":21,"stem":"At night Broadway around Times Square is very different from the rest of New York.","answer":"A"},{"n":22,"stem":"There are lots of colorful electric signs on the buildings in this part of Broadway.","answer":"A"},{"n":23,"stem":"The Great White Way got its name from the color of the buildings in the old days.","answer":"B"},{"n":24,"stem":"The word 'Broadway' means top quality American theater art today.","answer":"A"},{"n":25,"stem":"Broadway is also famous for its movies.","an