insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2010-maj-kozep-H2$mtr$, $mtr$2010-maj-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$feleletválasztás hallás után$mtr$, 7, 9, $mtr${"id":"2010-maj-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"feleletválasztás hallás után","points":7,"instructions":["In this section you will hear a report about a very unusual project.","Your task is to write the letter of the correct answer in the boxes on the right.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_10maj_fl.mp3","start":603.39,"end":1167.4,"clip":"hang/k_angol_10maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Trans Time is a company which is located in …","options":[{"key":"A","text":"Florida."},{"key":"B","text":"California."},{"key":"C","text":"Nevada."}],"answer":"B"},{"n":10,"stem":"The idea is that doctors will have the necessary … to cure all diseases in the future.","options":[{"key":"A","text":"money"},{"key":"B","text":"knowledge"},{"key":"C","text":"medicine"}]},{"n":11,"stem":"In certain cases Trans Time also freezes people who …","options":[{"key":"A","text":"die of old age."},{"key":"B","text":"die at a young age."},{"key":"C","text":"are very old."}]},{"n":12,"stem":"Scientists have already brought a frozen dead … back to life.","options":[{"key":"A","text":"dog"},{"key":"B","text":"man"},{"key":"C","text":"dog and also a man"}]},{"n":13,"stem":"By \"some day\", scientists mean … of years.","options":[{"key":"A","text":"thousands"},{"key":"B","text":"dozens"},{"key":"C","text":"hundreds"}]},{"n":14,"stem":"The capsules Trans Time uses are filled with …","options":[{"key":"A","text":"ice."},{"key":"B","text":"nitrogen."},{"key":"C","text":"oxygen."}]},{"n":15,"stem":"The temperature in the capsules is minus … degrees centigrade.","options":[{"key":"A","text":"196"},{"key":"B","text":"120"},{"key":"C","text":"250"}]},{"n":16,"stem":"The full prize of the service is … at the moment.","options":[{"key":"A","text":"$42,000"},{"key":"B","text":"$120,000"},{"key":"C","text":"$162,000"}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_10maj_fl.mp3","start":603.39,"end":1167.4,"clip":"hang/k_angol_10maj_fl_H2.mp3"}$mtr$::jsonb)
