insert into public.task_keys (task_id, task) values ($mtr$2010-okt-kozep-H1$mtr$, $mtr${"id":"2010-okt-kozep-H1","number":1,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":8,"instructions":["In this section, you are going to hear some information about Mr Charles Baker, who forged railway tickets.","Your task will be to give short answers to the questions below.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_10okt_fl.mp3","start":0,"end":532.89,"clip":"hang/k_angol_10okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"How old is Mr Baker? He is {{gap}}","accept":["27"]},{"n":1,"stem":"What does Mr Baker do? He is a(n) {{gap}}","key":"computer programmer","keywords":[["computer","programmer"]]},{"n":2,"stem":"How much money did he save? He saved £ {{gap}}","key":"12,500","keywords":[["12500"]]},{"n":3,"stem":"Where does he live? On England's {{gap}}","key":"south coast","keywords":[["south","coast"]]},{"n":4,"stem":"Who caught Mr Baker? A(n) {{gap}}","key":"(eagle-eyed) ticket inspector (and two policemen)","keywords":[["ticket","inspector"]]},{"n":5,"stem":"Where did they find eleven tickets? In a(n) {{gap}}","key":"(plastic) wallet","keywords":[["wallet"]]},{"n":6,"stem":"Where did the police find Mr Baker's laptop? At {{gap}}","key":"his home / (Mr) Baker’s home","keywords":[["his","home"],["baker’s","home"]]},{"n":7,"stem":"What was Mr Baker sentenced to? To {{gap}}","key":"nine months (in prison) / a nine-month prison term / nine months’ imprisonment","keywords":[["nine","months"],["nine-month","prison","term"],["nine","months’","imprisonment"]]},{"n":8,"stem":"What was he ordered to do? To {{gap}}","key":"repay / pay back the damage (he had caused)","keywords":[["repay"],