insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2010-okt-kozep-H2$mtr$, $mtr$2010-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 10, 9, $mtr${"id":"2010-okt-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":10,"instructions":["In this section you will hear the strange story of a woman called Mary.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_10okt_fl.mp3","start":532.89,"end":1130.59,"clip":"hang/k_angol_10okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Mary has had only one paranormal experience in her life.","answer":"B"},{"n":9,"stem":"She remembers the exact date of the incident."},{"n":10,"stem":"The toothache started at the office where she worked."},{"n":11,"stem":"It wasn't easy to find a dentist those days."},{"n":12,"stem":"A man came through the wall."},{"n":13,"stem":"Mary was alone in her room."},{"n":14,"stem":"The man had been a dentist before he died."},{"n":15,"stem":"Mary felt something hot around her head, which she liked."},{"n":16,"stem":"The next morning Mary noticed that her toothache had gone."},{"n":17,"stem":"The dentist said that her tooth was in good condition."},{"n":18,"stem":"Mary told the dentist her strange story."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_10okt_fl.mp3","start":532.89,"end":1130.59,"clip":"hang/k_angol_10okt_fl_H2.mp3"}$mtr$::jsonb)
