insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2011-okt-emelt-H3$mtr$, $mtr$2011-okt-emelt$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 10, 11, $mtr${"id":"2011-okt-emelt-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":10,"instructions":["In this section you will hear some information about the first appearance of a now famous singer, Susan Boyle.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_11okt_fl.mp3","start":1160.01,"end":1795.61,"clip":"hang/e_angol_11okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Susan had a steady job.","answer":"B"},{"n":17,"stem":"The show’s host helped Susan with encouraging questions before her performance."},{"n":18,"stem":"At first, it was only the judges who were amazed by Susan’s performance."},{"n":19,"stem":"The speaker says that it was her appearance that deceived the audience."},{"n":20,"stem":"According to the speaker, the feelings we experienced were all positive."},{"n":21,"stem":"The speaker herself has watched the YouTube video many times."},{"n":22,"stem":"According to the speaker, we all secretly believe that we could become stars."},{"n":23,"stem":"Susan started singing 35 years ago."},{"n":24,"stem":"Fred O’Neil has coached a lot of famous stars."},{"n":25,"stem":"It was Susan’s mother who encouraged her to enter the contest."},{"n":26,"stem":"Susan’s mother was very proud to see her daughter win."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_11okt_fl.mp3","start":1160.01,"end":1795.61,"clip":"hang/e_angol_11okt_fl_H3.mp3"}$mtr$::jsonb)
