insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2011-okt-kozep-H3$mtr$, $mtr$2011-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 7, 10, $mtr${"id":"2011-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":7,"instructions":["In this section you will hear a true story about a lost wallet.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_11okt_fl.mp3","start":1258.63,"end":1793.71,"clip":"hang/k_angol_11okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Mr Beck and Mr Merill collect old motorbikes.","answer":"B"},{"n":19,"stem":"They answered an advertisement for a classic car."},{"n":20,"stem":"Mr Beck was driving the car on the way to the restaurant."},{"n":21,"stem":"The wallet had fallen out from below the front seat of the car."},{"n":22,"stem":"There was a lot of money in the wallet."},{"n":23,"stem":"Mr Putman and Mr Goodlove are the same person."},{"n":24,"stem":"The girl Mr Goodlove kissed in the car is now his wife."},{"n":25,"stem":"Mr Goodlove's grandfather used to live in the State of Idaho."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_11okt_fl.mp3","start":1258.63,"end":1793.71,"clip":"hang/k_angol_11okt_fl_H3.mp3"}$mtr$::jsonb)
