insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-maj-kozep-H1$mtr$, $mtr$2012-maj-kozep$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 10, 8, $mtr${"id":"2012-maj-kozep-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":10,"instructions":["In this section you will hear the story of the famous Siamese twins.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_12maj_fl.mp3","start":0,"end":722.61,"clip":"hang/k_angol_12maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The mother in the story gave birth to twin girls.","answer":"B"},{"n":1,"stem":"The two babies were joined at their arms."},{"n":2,"stem":"The young twins were famous in their home country before they went to the USA."},{"n":3,"stem":"They were taken to the USA against their will."},{"n":4,"stem":"They visited their family back in Siam when they had collected enough money."},{"n":5,"stem":"They traveled across the USA for more than ten years before they settled down."},{"n":6,"stem":"Adelaide was much older than Sarah."},{"n":7,"stem":"The sisters took turns to stay in the brothers' house for four days at a time."},{"n":8,"stem":"Both couples had a lot of children."},{"n":9,"stem":"The brothers didn’t always get on very well with each other."},{"n":10,"stem":"The Siamese twins died of cancer."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_12maj_fl.mp3","start":0,"end":722.61,"clip":"hang/k_angol_12maj_fl_H1.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2012-maj-kozep-H1$mtr$, $mtr${"id":"2012-maj-kozep-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":10,"instructions":["In this section you will hear the story of the famous Siamese twins.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_12maj_fl.mp3","start":0,"end":722.61,"clip":"hang/k_angol_12maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"The mother in the story gave birth to twin girls.","answer":"B"},{"n":1,"stem":"The two babies were joined at their arms.","answer":"B"},{"n":2,"stem":"The young twins were famous in their home country before they went to the USA.","answer":"A"},{"n":3,"stem":"They were taken to the USA against their will.","answer":"B"},{"n":4,"stem":"They visited their family back in Siam when they had collected enough money.","answer":"B"},{"n":5,"stem":"They traveled across the USA for more than ten years before they settled down.","answer":"A"},{"n":6,"stem":"Adelaide was much older than Sarah.","answer":"C"},{"n":7,"stem":"The sisters took turns to stay in the brothers' house for four days at a time.","answer":"B"},{"n":8,"stem":"Both couples had a lot of children.","answer":"A"},{"n":9,"stem":"The brothers didn’t always get on very well with each other.","answer":"A"},{"n":10,"stem":"The Siamese twins died of cancer.","answer":"C"}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2012-maj-kozep-H2$mtr$, $mtr$2012-maj-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 7, 9, $mtr${"id":"2012-maj-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":7,"instructions":["In this section, you are going to hear an interview about an interesting new invention.","Your task will be to give short answers to the questions below.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_12maj_fl.mp3","start":722.61,"end":1362.12,"clip":"hang/k_angol_12maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"What's Peter O'Brian by profession? {{gap}}","accept":["a technician"]},{"n":11,"stem":"What is the bed connected to? {{gap}}"},{"n":12,"stem":"Whose voice does Hiroyuki hear if he is still in bed after the first warning? {{gap}}"},{"n":13,"stem":"Whose voice does Hiroyuki hear if the first recording didn't work? {{gap}}"},{"n":14,"stem":"What does the mechanical device in the bed do to you if you are still not awake? {{gap}}"},{"n":15,"stem":"Where do the laziest people end up? {{gap}}"},{"n":16,"stem":"How many beds has Hiroyuki made so far? {{gap}}"},{"n":17,"stem":"What does Hiroyuki believe he will become one day? {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_12maj_fl.mp3","start":722.61,"end":1362.12,"clip":"hang/k_angol_12maj_fl_H2.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2012-maj-kozep-H2$mtr$, $mtr${"id":"2012-maj-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":7,"instructions":["In this section, you are going to hear an interview about an interesting new invention.","Your task will be to give short answers to the questions below.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_12maj_fl.mp3","start":722.61,"end":1362.12,"clip":"hang/k_angol_12maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"What's Peter O'Brian by profession? {{gap}}","accept":["a technician"]},{"n":11,"stem":"What is the bed connected to? {{gap}}","key":"(It is connected to an) alarm clock (and a tape recorder). (Mindkét vastagon szedett szó kell!)","keywords":[["alarm","clock"]]},{"n":12,"stem":"Whose voice does Hiroyuki hear if he is still in bed after the first warning? {{gap}}","key":"His girlfriend's (recording/voice).","keywords":[["girlfriend's"]]},{"n":13,"stem":"Whose voice does Hiroyuki hear if the first recording didn't work? {{gap}}","key":"His boss(' recording/voice).","keywords":[["boss"]]},{"n":14,"stem":"What does the mechanical device in the bed do to you if you are still not awake? {{gap}}","key":"Kicks (you in the leg).","keywords":[["kicks"]]},{"n":15,"stem":"Where do the laziest people end up? {{gap}}","key":"(On the) floor. // Out of bed. (A kettő közül az egyik.)","keywords":[["floor"],["out","bed"]]},{"n":16,"stem":"How many beds has Hiroyuki made so far? {{gap}}","key":"(Only) one. // (Only) the prototype. (A kettő közül az egyik.)","keywords":[["one"],["prototype"]]},{"n":17,"stem":"What does Hiroyuki believe he will become one day? {{gap}}","key":"(A very) rich (man).","keywords":[["rich"]]}],"grading":{"spelling":"keywords","caseSensitive":false,"note":"(A helyes válaszoknak tartalmazniuk kell a vastagon szedett szavakat.)"}}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
