insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2013-maj-kozep-L2$mtr$, $mtr$2013-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 10, 6, $mtr${"id":"2013-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read about how the purpose of houses has changed in England. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-20) after the text.","Use only one word in each gap."],"title":"HOUSES THROUGH HISTORY","body":["The purpose of a house {{0}} changed over the centuries, especially the rooms inside. What rooms would you include {{11}} you could design a house? I bet you would have several rooms including different ones {{12}} cook in, sleep in, play in, wash in etc. You would expect your house to have running water, electricity and gas. You would want it to be warm in winter, cool in summer and keep you dry when {{13}} rains. You would also want it to be reasonably secure - large windows to let the sunlight in {{14}} keep the burglars out.","Your needs today {{15}} very different to those of people who lived in houses long {{16}}. Take for example the Celtic family. They all lived in one room. In fact their house only consisted {{17}} one room and they sometimes brought in their animals too to keep {{18}} safe from predators.","I wonder {{19}} a Victorian gentleman would think of your list of rooms. Did you include rooms for your servants? A Victorian worker would {{20}} amazed at the number of toilets or bathrooms in your house. He would have had to share an outside toilet with everyone else in his street!","(www.woodlands-junior.kent.sch.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["has"]},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17},{"n":18},{"n":19},{"n":20}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2013-maj-kozep-L2$mtr$, $mtr${"id":"2013-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read about how the purpose of houses has changed in England. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-20) after the text.","Use only one word in each gap."],"title":"HOUSES THROUGH HISTORY","body":["The purpose of a house {{0}} changed over the centuries, especially the rooms inside. What rooms would you include {{11}} you could design a house? I bet you would have several rooms including different ones {{12}} cook in, sleep in, play in, wash in etc. You would expect your house to have running water, electricity and gas. You would want it to be warm in winter, cool in summer and keep you dry when {{13}} rains. You would also want it to be reasonably secure - large windows to let the sunlight in {{14}} keep the burglars out.","Your needs today {{15}} very different to those of people who lived in houses long {{16}}. Take for example the Celtic family. They all lived in one room. In fact their house only consisted {{17}} one room and they sometimes brought in their animals too to keep {{18}} safe from predators.","I wonder {{19}} a Victorian gentleman would think of your list of rooms. Did you include rooms for your servants? A Victorian worker would {{20}} amazed at the number of toilets or bathrooms in your house. He would have had to share an outside toilet with everyone else in his street!","(www.woodlands-junior.kent.sch.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["has"]},{"n":11,"accept":["if","supposing","assuming"]},{"n":12,"accept":["to"]},{"n":13,"accept":["it"]},{"n":14,"accept":["but","and","yet"]},{"n":15,"accept":["are","look","seem"]},{"n":16,"accept":["ago"]},{"n":17,"accept":["of"]},{"n":18,"accept":["them"]},{"n":19,"accept":["what","if","whether"]},{"n":20,"accept":["be"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2013-maj-kozep-L3$mtr$, $mtr$2013-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 8, 7, $mtr${"id":"2013-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":8,"instructions":["You are going to read an article about a newly discovered language. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (21-28).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THEKOROLANGUAGE","body":["{{0}} have identified a language new to science in north-eastern India. Known as Koro, it appears to be distinct from other languages in the family to which it belongs; but it is also under threat.","A team of {{21}} were searching for two other little-known languages {{22}} only in one small area. As they heard and recorded these, they found a third which was {{23}} new to them and had never before been listed. \"We didn't have to get far on our word list to realise it was extremely {{24}} in every possible way,\" said Dr David Harrison, one of the expedition {{25}}.","Koro belongs to the Tibeto-Burman family, which includes around 150 languages. But linguists were {{26}} to find any others closely related to Koro within this group. It is thought that around half of the world's 6,909 known languages are endangered and Koro itself is at {{27}}. It has never been written down and there are only about 1,000 speakers of it.","The question is where it came from and how it remained {{28}} until now. The team will be returning to India next month to continue their research on Koro.","(www.nationalgeographic.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"research","example":true,"accept":["Researchers"]},{"n":21,"prompt":"science"},{"n":22,"prompt":"speak"},{"n":23,"prompt":"complete"},{"n":24,"prompt":"differ"},{"n":25,"prompt":"lead"},{"n":26,"prompt":"able"},{"n":27,"prompt":"risk"},{"n":28,"prompt":"hide"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2013-maj-kozep-L3$mtr$, $mtr${"id":"2013-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":8,"instructions":["You are going to read an article about a newly discovered language. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (21-28).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THEKOROLANGUAGE","body":["{{0}} have identified a language new to science in north-eastern India. Known as Koro, it appears to be distinct from other languages in the family to which it belongs; but it is also under threat.","A team of {{21}} were searching for two other little-known languages {{22}} only in one small area. As they heard and recorded these, they found a third which was {{23}} new to them and had never before been listed. \"We didn't have to get far on our word list to realise it was extremely {{24}} in every possible way,\" said Dr David Harrison, one of the expedition {{25}}.","Koro belongs to the Tibeto-Burman family, which includes around 150 languages. But linguists were {{26}} to find any others closely related to Koro within this group. It is thought that around half of the world's 6,909 known languages are endangered and Koro itself is at {{27}}. It has never been written down and there are only about 1,000 speakers of it.","The question is where it came from and how it remained {{28}} until now. The team will be returning to India next month to continue their research on Koro.","(www.nationalgeographic.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"research","example":true,"accept":["Researchers"]},{"n":21,"prompt":"science","accept":["scientists"]},{"n":22,"prompt":"speak","accept":["spoken"]},{"n":23,"prompt":"complete","accept":["completely"]},{"n":24,"prompt":"differ","accept":["different"]}