insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2014-maj-kozep-L2$mtr$, $mtr$2014-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 10, 6, $mtr${"id":"2014-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read about the guards at the Tower of London. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-20) after the text.","Use only one word in each gap."],"title":"THE HISTORY OF THE YEOMAN WARDERS","body":["The guards at the Tower of London {{0}} called Yeoman Warders. In principle they are responsible {{11}} looking after any prisoners at the Tower and safeguarding the British crown jewels, but in practice they act as tour guides and are {{12}} tourist attraction in their own right. Nobody knows more about the history of the Tower {{13}} them and no visit is complete without joining one of their tours. Having guarded this royal palace and fortress for centuries they will fascinate you with amazing stories, passed on {{14}} generation to generation.","The Yeoman Warders {{15}} originally Henry VIII’s bodyguard. In 1509, he decided to leave twelve of his old and sick Yeoman behind in the Tower {{16}} protect it. He took the rest of the bodyguard away with him. The twelve he left are the “ancestors” of the twelve Yeoman Warders {{17}} guard the Tower still today.","Their nickname is Beefeater, which people often think comes {{18}} the French word – 'buffetier'. Buffetiers were guards in the palace of French kings. They protected the king’s food. {{19}}, it is more probable that the name Beefeater dates from the time {{20}} the Yeoman Warders were given chunks of beef as part of their salary.","(www.woodlands-junior.kent.sch.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["are"]},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17},{"n":18},{"n":19},{"n":20}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2014-maj-kozep-L2$mtr$, $mtr${"id":"2014-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":10,"instructions":["You are going to read about the guards at the Tower of London. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (11-20) after the text.","Use only one word in each gap."],"title":"THE HISTORY OF THE YEOMAN WARDERS","body":["The guards at the Tower of London {{0}} called Yeoman Warders. In principle they are responsible {{11}} looking after any prisoners at the Tower and safeguarding the British crown jewels, but in practice they act as tour guides and are {{12}} tourist attraction in their own right. Nobody knows more about the history of the Tower {{13}} them and no visit is complete without joining one of their tours. Having guarded this royal palace and fortress for centuries they will fascinate you with amazing stories, passed on {{14}} generation to generation.","The Yeoman Warders {{15}} originally Henry VIII’s bodyguard. In 1509, he decided to leave twelve of his old and sick Yeoman behind in the Tower {{16}} protect it. He took the rest of the bodyguard away with him. The twelve he left are the “ancestors” of the twelve Yeoman Warders {{17}} guard the Tower still today.","Their nickname is Beefeater, which people often think comes {{18}} the French word – 'buffetier'. Buffetiers were guards in the palace of French kings. They protected the king’s food. {{19}}, it is more probable that the name Beefeater dates from the time {{20}} the Yeoman Warders were given chunks of beef as part of their salary.","(www.woodlands-junior.kent.sch.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["are"]},{"n":11,"accept":["for"]},{"n":12,"accept":["a"]},{"n":13,"accept":["than"]},{"n":14,"accept":["from"]},{"n":15,"accept":["were"]},{"n":16,"accept":["to"]},{"n":17,"accept":["who","that"]},{"n":18,"accept":["from"]},{"n":19,"accept":["actually","anyway","however","nevertheless","nonetheless","yet"]},{"n":20,"accept":["when"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2014-maj-kozep-L3$mtr$, $mtr$2014-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 8, 7, $mtr${"id":"2014-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":8,"instructions":["You are going to read an article about the history of the Statue of Liberty. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (21-28).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THE LIGHT OF LIBERTY","body":["On July 4, 1884 France presented the United States with an {{0}} birthday gift: the Statue of Liberty! The statue standing in New York Harbor has welcomed {{21}}, immigrants, and returning Americans traveling by ship for more than a century. It’s a {{22}} symbol of freedom and democracy.","It started one night near Paris in 1865. A group of Frenchmen were discussing their dictator-like emperor and the democratic {{23}} of the U.S. They decided to build a monument to American freedom – and strengthen French demands for democracy in their own country. Frédéric-Auguste Bartholdi, the {{24}} sculptor, was there. He imagined a statue of a woman holding a torch burning with the light of freedom.","Turning Bartholdi’s idea into {{25}} took 21 years. Americans paid for the pedestal and French {{26}} raised money to build the statue. It was built in France, presented to the U.S., taken apart, shipped across the Atlantic Ocean and rebuilt in the U.S. It was {{27}} dedicated on October 28, 1886.","At that time the statue was the tallest structure in the U.S. {{28}} climb 354 steps to look out from 25 windows in the crown. The seven rays in the crown represent the Earth’s seven seas.","(www.nationalgeographic/kids.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"credible","example":true,"accept":["incredible"]},{"n":21,"prompt":"visit"},{"n":22,"prompt":"universe"},{"n":23,"prompt":"govern"},{"n":24,"prompt":"fame"},{"n":25,"prompt":"real"},{"n":26,"prompt":"support"},{"n":27,"prompt":"final"},{"n":28,"prompt":"tour"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2014-maj-kozep-L3$mtr$, $mtr${"id":"2014-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":8,"instructions":["You are going to read an article about the history of the Statue of Liberty. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (21-28).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THE LIGHT OF LIBERTY","body":["On July 4, 1884 France presented the United States with an {{0}} birthday gift: the Statue of Liberty! The statue standing in New York Harbor has welcomed {{21}}, immigrants, and returning Americans traveling by ship for more than a century. It’s a {{22}} symbol of freedom and democracy.","It started one night near Paris in 1865. A group of Frenchmen were discussing their dictator-like emperor and the democratic {{23}} of the U.S. They decided to build a monument to American freedom – and strengthen French demands for democracy in their own country. Frédéric-Auguste Bartholdi, the {{24}} sculptor, was there. He imagined a statue of a woman holding a torch burning with the light of freedom.","Turning Bartholdi’s idea into {{25}} took 21 years. Americans paid for the pedestal and French {{26}} raised money to build the statue. It was built in France, presented to the U.S., taken apart, shipped across the Atlantic Ocean and rebuilt in the U.S. It was {{27}} dedicated on October 28, 1886.","At that time the statue was the tallest structure in the U.S. {{28}} climb 354 steps to look out from 25 windows in the crown. The seven rays in the crown represent the Earth’s seven seas.","(www.nationalgeographic/kids.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"credible","example":true,"accept":["incredible"]},{"n":21,"prompt":"visit","accept":["visitors"]},{"n":22,"prompt":"universe","accept"