insert into public.task_keys (task_id, task) values ($mtr$2015-okt-kozep-L3$mtr$, $mtr${"id":"2015-okt-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read a joke about a smart flight attendant. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (22-29) after the text.","Use only one word in each gap."],"title":"DEAD OR ALIVE?","body":["Joe was a flight attendant for Fly High airlines. He watched {{0}} an elderly lady boarded the plane holding a dog in a cage. \"Excuse me,\" said Joe, \"dogs {{22}} not allowed on board; you have to check your dog {{23}} with the baggage.\" The lady wasn’t happy, but Joe was an experienced flight attendant and managed {{24}} convince the lady without a scene. Upon arrival, Joe took a peek in the cage, and to his great surprise, saw that the dog {{25}} dead! Horrified that they might get sued, Joe quickly sent {{26}} of his colleagues out to town to buy a dog {{27}} looked exactly the same. Luckily, in an hour’s time, Joe’s colleague came back with the perfect dog. They quickly switched dogs {{28}} felt very proud of themselves. \"This isn’t my dog!\" said the lady as {{29}} as she saw it. \"I’m sure it is,\" insisted Joe, \"I was very careful about where I put it.\" \"It’s not my dog,\" argued the lady, \"you see, I was bringing my dog to my home town to have him buried, and this dog is alive!\"","(http://www.greatcleanjokes.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["as"]},{"n":22,"accept":["are"]},{"n":23,"accept":["in"]},{"n":24,"accept":["to"]},{"n":25,"accept":["was"]},{"n":26,"accept":["one"]},{"n":27,"accept":["that","which"]},{"n":28,"accept":["and"]},{"n":29,"accept":["soon"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2015-okt-kozep-H1$mtr$, $mtr$2015-okt-kozep$mtr$, $mtr$listening$mtr$, 1, $mtr$text$mtr$, $mtr$mondatkiegészítés hallás után$mtr$, 9, 8, $mtr${"id":"2015-okt-kozep-H1","number":1,"kind":"text","layout":"stems","examType":"mondatkiegészítés hallás után","points":9,"instructions":["In this section, you will hear an interview with Leona Lewis, who won the third series of the X Factor in the UK in 2006.","Your task is to complete the sentences with the exact word you hear in the text. Write one word in each gap.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_15okt_fl.mp3","start":0,"end":617.29,"clip":"hang/k_angol_15okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Leona grew up in {{gap}} London.","accept":["East"]},{"n":1,"stem":"Leona went to a(n) {{gap}} arts school."},{"n":2,"stem":"Besides being a shop-assistant and a waitress, she also worked as a(n) {{gap}}."},{"n":3,"stem":"Her style now is a bit more feminine and {{gap}}."},{"n":4,"stem":"She was quite {{gap}} and she still is."},{"n":5,"stem":"Besides horseback riding, she likes {{gap}}."},{"n":6,"stem":"Leona and her boyfriend started dating when they were {{gap}}."},{"n":7,"stem":"Besides going to her friends’ houses, Leona likes going to a(n) {{gap}} with her friends."},{"n":8,"stem":"Leona {{gap}} her music idol when she was seventeen."},{"n":9,"stem":"Leona’s parent told her not to {{gap}} herself to one thing."}],"grading":{"spelling":"lenient"}}$mtr$::jsonb, $mtr${"file":"k_angol_15okt_fl.mp3","start":0,"end":617.29,"clip":"hang/k_angol_15okt_fl_H1.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2015-okt-kozep-H1$mtr$, $mtr${"id":"2015-okt-kozep-H1","number":1,"kind":"text","layout":"stems","examType":"mondatkiegészítés hallás után","points":9,"instructions":["In this section, you will hear an interview with Leona Lewis, who won the third series of the X Factor in the UK in 2006.","Your task is to complete the sentences with the exact word you hear in the text. Write one word in each gap.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_15okt_fl.mp3","start":0,"end":617.29,"clip":"hang/k_angol_15okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Leona grew up in {{gap}} London.","accept":["East"]},{"n":1,"stem":"Leona went to a(n) {{gap}} arts school.","accept":["performing"]},{"n":2,"stem":"Besides being a shop-assistant and a waitress, she also worked as a(n) {{gap}}.","accept":["receptionist"]},{"n":3,"stem":"Her style now is a bit more feminine and {{gap}}.","accept":["girly"]},{"n":4,"stem":"She was quite {{gap}} and she still is.","accept":["shy"]},{"n":5,"stem":"Besides horseback riding, she likes {{gap}}.","accept":["swimming"]},{"n":6,"stem":"Leona and her boyfriend started dating when they were {{gap}}.","accept":["17","seventeen"]},{"n":7,"stem":"Besides going to her friends’ houses, Leona likes going to a(n) {{gap}} with her friends.","accept":["club"]},{"n":8,"stem":"Leona {{gap}} her music idol when she was seventeen.","accept":["discovered"]},{"n":9,"stem":"Leona’s parent told her not to {{gap}} herself to one thing.","accept":["limit"]}],"grading":{"spelling":"lenient","caseSensitive":false}}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2015-okt-kozep-H2$mtr$, $mtr$2015-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$fix$mtr$, $mtr$hibás szó javítása hallás után$mtr$, 8, 9, $mtr${"id":"2015-okt-kozep-H2","number":2,"kind":"fix","layout":"stems","examType":"hibás szó javítása hallás után","points":8,"instructions":["In this section, you will hear a report about dishonest on-line companies in the United States.","Your task is to find one word in each of the following sentences which doesn’t make sense in the context of the recording. First, cross it out, and then write the correct one on the line after the sentence.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_15okt_fl.mp3","start":617.29,"end":1202.96,"clip":"hang/k_angol_15okt_fl_H2.mp3"},"items":[{"n":0,"text":"Mr. Brody received an email from a friend in New York.","example":true,"fixes":[{"wrong":"friend","accept":["company"]}]},{"n":10,"text":"The letter congratulated Mr. Brody on being the buyer of an electronic piano."},{"n":11,"text":"When Mr. Brody received the box, at first he saw nothing but pieces of plastic."},{"n":12,"text":"The piano had thirty buttons which made a beeping sound when he pushed them."},{"n":13,"text":"Dishonest companies often surprise people with their advertising."},{"n":14,"text":"The “solar-powered clothes dryer” turned out to be nothing but a wire and a clothes pin."},{"n":15,"text":"People ordered the “faux pearls” because they were surprisingly expensive."},{"n":16,"text":"People should not have been surprised to see that the pearls were made of glass."},{"n":17,"text":"The Postal Service employs 500 people whose only task is to stop the cheating customers."}],"grading":{"spelling":"lenient"}}$mtr$::jsonb, $mtr${"file":"k_angol_15okt_fl.mp3","start":617.29,"end":1202.96,"clip":"hang/k_angol_15okt_fl_H2.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2015-okt-kozep-H2$mtr$, $mtr${"id":"2015-okt-kozep-H2","number":2,"kind":"fix","layout":"stems","examType":"hibás szó javítása hallás után","points":8,"instructions":["In this section, you will hear a report about dishonest on-line companies in the United States.","Your task is to find one word in each of the following sentences which doesn’t make sense in the context of the recording. First, cross it out, and then write the correct one on the line after the sentence.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_15okt_fl.mp3","start":617.29,"end":1202.96,"clip":"hang/k_angol_15okt_fl_H2.mp3"},"items":[{"n":0,"text":"Mr. Brody received an email from a friend in New York.","example":true,"fixes":[{"wrong":"friend","accept":["company"]}]},{"n":10,"text":"The letter congratulated Mr. Brody on being the buyer of an electronic piano.","fixes":[{"wrong":"buyer","accept":["winner"]}]},{"n":11,"text":"When Mr. Brody received the box, at first he saw nothing but pieces of plastic.","fixes":[{"wrong":"plastic","accept":["newspaper","paper"]}]},{"n":12,"text":"The piano had thirty buttons which made a beeping sound when he pushed them.","fixes":[{"wrong":"thirty","accept":["13","thirteen"]}]},{"n":13,"text":"Dishonest companies often surprise people with their advertising.","fixes":[{"wrong":"surprise","accept":["trick"]}]},{"n":14,"text":"The “solar-powered clothes dryer” turned out to be nothing but a wire and a clothes pin.","fixes":[{"wrong":"wire","accept":["string"]}]},{"n":15,"text":"People ordered the “faux pearls” because they were surprisingly expensive.","fixes":[{"wrong":"expensive","accept":["cheap"]}]},{"n":16,"text":"People should not have been surprised to see that the pearls were made of glass.","fixes":[{"wrong":"glass","accept":["plastic"]}]},{"n":17,"text":"The Postal Service employs 500 people whose only task is to stop the cheating customers.","fixes":[{"wrong":"customers","accept":["companies"]}]}],"grading":{"spelling":"lenient","caseSensitive":false,"note":"(A hibás szó egyértelmű megjelölését kérjük, de akkor is elfogadhatjuk a vonalra írt helyes választ, ha a vizsgázó nem húzta ki a hibás szót.)"}}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2015-okt-kozep-H3$mtr$, $mtr$2015-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 8, 10, $mtr${"id":"2015-okt-kozep-H3","number":3,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":8,"instructions":["In this section, you are going to hear some information about how Americans celebrate the New Year.","Your task is to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you will have to circle one or two letters.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_15okt_fl.mp3","start":1202.96,"end":1795.82,"clip":"hang/k_angol_15okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"The beginning of the new year has been welcomed ...","options":[{"key":"A","text":"on different dates throughout history."},{"key":"B","text":"in different ways in the various parts of the world."}],"answer":["A","B"]},{"n":18,"stem":"People celebrate the new year by ...","options":[{"key":"A","text":"wearing new clothes in Muslim societies."},{"key":"B","text":"giving each other birds and turtles as a present in Southern Asia."}]},{"n":19,"stem":"Others, such as …","options":[{"key":"A","text":"Jews have a religious ceremony to celebrate it."},{"key":"B","text":"Japanese people prepare a rice cake on New Year’s Eve."}]},{"n":20,"stem":"In the United States, the official holiday is ...","options":[{"key":"A","text":"December 31st."},{"key":"B","text":"January 1st."}]},{"n":21,"stem":"At traditional masquerade balls …","options":[{"key":"A","text":"people wear a mask before midnight."},{"key":"B","text":"take off their costumes at midnight."}]},{"n":22,"stem":"On 31st December, …","options":[{"key":"A","text":"a lot of people watch TV at New Year’s Eve parties."},{"key":"B","text":"most TV channels give a live broadcast from New York City."}]},{"n":23,"stem":"At one minute before midnight on Times Square in N.Y.C., ...","options":[{"key":"A","text":"a lighted ball is lifted to the top of one of the tall buildings."},{"key":"B","text":"people start counting down together."}]},{"n":24,"stem":"On January 1st, it is customary in the U.S. to ...","options":[{"key":"A","text":"visit friends, relatives and neighbors."},{"key":"B","text":"give a small present to your friends and loved ones."}]},{"n":25,"stem":"In the U.S., New Year’s resolutions are often ...","options":[{"key":"A","text":"made in writing."},{"key":"B","text":"broken within a month."}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_15okt_fl.mp3","start":1202.96,"end":1795.82,"clip":"hang/k_angol_15okt_fl_H3.mp3"}$mtr$::jsonb)
