insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-maj-emelt-H1$mtr$, $mtr$2016-maj-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 12, 9, $mtr${"id":"2016-maj-emelt-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":12,"instructions":["In this section you will hear the life story of an extraordinary scientist called Caroline Herschel.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_16maj_fl.mp3","start":0,"end":669.66,"clip":"hang/e_angol_16maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Caroline Herschel had a lot of brothers but no sisters.","answer":"B"},{"n":1,"stem":"Caroline’s illness seriously limited her growth."},{"n":2,"stem":"Both her parents wanted Caroline to receive an excellent education."},{"n":3,"stem":"Caroline wanted to be near William because he badly needed her help."},{"n":4,"stem":"In England Caroline’s only task was to learn to sing."},{"n":5,"stem":"Caroline delivered a brilliant performance in the Birmingham Festival."},{"n":6,"stem":"Thanks to her success in music, Caroline enjoyed a busy social life."},{"n":7,"stem":"William’s interest in astronomy started with a strange observation."},{"n":8,"stem":"According to Caroline’s Memoir, she only did what her brother told her to do."},{"n":9,"stem":"Caroline was the first woman to discover a comet."},{"n":10,"stem":"William and his patron became lifelong friends."},{"n":11,"stem":"The planet Uranus was discovered by Caroline."},{"n":12,"stem":"After William’s death, Caroline went on doing her scientific work."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_16maj_fl.mp3","start":0,"end":669.66,"clip":"hang/e_angol_16maj_fl_H1.mp3"}$mtr$::jsonb)
