insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-maj-kozep-L2$mtr$, $mtr$2016-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 10, 6, $mtr${"id":"2016-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":10,"instructions":["You are going to read an article about Florence Nightingale (1820–1910), who is famous for her nursing work during the Crimean War (1854–56). Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (11-20).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"FLORENCE NIGHTINGALE","body":["Florence Nightingale changed nursing from a {{0}} untrained job to a highly skilled medical profession with very important {{11}}.","Florence Nightingale was born in 1820. Her father was a {{12}} landowner. At that time, rich English girls were expected to do - almost nothing. However, Florence's father believed that all women should receive an {{13}}. He taught Florence science, mathematics, history and philosophy.","As Florence grew up she developed an interest in {{14}} others. At first her parents refused to allow her to become a nurse because it wasn't a {{15}} profession for a well educated woman. But Florence didn't give up. Finally, in 1851 her father gave his {{16}} and Florence went to Germany to train to become a nurse.","In 1854 Florence went to Turkey to manage the nursing of {{17}} soldiers wounded in the Crimean War. She found the hospital conditions very poor. Many of the wounded were unwashed and were sleeping in {{18}}, dirty rooms without blankets or decent food. Diseases such as typhus spread {{19}}. As a result, the {{20}} rate among wounded soldiers was very high. Florence and her nurses set up a kitchen, fed the wounded from their own supplies and asked the wives of the wounded for help. They were then able to properly care for the ill and wounded.","(www.woodlands-junior.kent.sch.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"most","example":true,"accept":["mostly"]},{"n":11,"prompt":"responsible"},{"n":12,"prompt":"wealth"},{"n":13,"prompt":"educate"},{"n":14,"prompt":"help"},{"n":15,"prompt":"suit"},{"n":16,"prompt":"permit"},{"n":17,"prompt":"Britain"},{"n":18,"prompt":"crowd"},{"n":19,"prompt":"fast"},{"n":20,"prompt":"die"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2016-maj-kozep-L2$mtr$, $mtr${"id":"2016-maj-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":10,"instructions":["You are going to read an article about Florence Nightingale (1820–1910), who is famous for her nursing work during the Crimean War (1854–56). Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (11-20).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"FLORENCE NIGHTINGALE","body":["Florence Nightingale changed nursing from a {{0}} untrained job to a highly skilled medical profession with very important {{11}}.","Florence Nightingale was born in 1820. Her father was a {{12}} landowner. At that time, rich English girls were expected to do - almost nothing. However, Florence's father believed that all women should receive an {{13}}. He taught Florence science, mathematics, history and philosophy.","As Florence grew up she developed an interest in {{14}} others. At first her parents refused to allow her to become a nurse because it wasn't a {{15}} profession for a well educated woman. But Florence didn't give up. Finally, in 1851 her father gave his {{16}} and Florence went to Germany to train to become a nurse.","In 1854 Florence went to Turkey to manage the nursing of {{17}} soldiers wounded in the Crimean War. She found the hospital conditions very poor. Many of the wounded were unwashed and were sleeping in {{18}}, dirty rooms without blankets or decent food. Diseases such as typhus spread {{19}}. As a result, the {{20}} rate among wounded soldiers was very high. Florence and her nurses set up a kitchen, fed the wounded from their own supplies and asked the wives of the wounded for help. They were then able to properly care for the ill and wounded.","(www.woodlands-junior.kent.sch.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"most","example":true,"accept":["mostly"]},{"n":11,"prompt":"responsible","accept":["responsibilities"]},{"n":12,"prompt":"wealth","accept":["wealthy"]},{"n":13,"prompt":"educate","accept":["education"]},{"n":14,"prompt":"help","accept":["helping"]},{"n":15,"prompt":"suit","accept":["suitable"]},{"n":16,"prompt":"permit","accept":["permission"]},{"n":17,"prompt":"Britain","accept":["British","Britain’s"]},{"n":18,"prompt":"crowd","accept":["crowded"]},{"n":19,"prompt":"fast","accept":["fast"]},{"n":20,"prompt":"die","accept":["death"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-maj-kozep-L3$mtr$, $mtr$2016-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$bank$mtr$, $mtr$szóbank (szavak visszahelyezése)$mtr$, 10, 7, $mtr${"id":"2016-maj-kozep-L3","number":3,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":10,"instructions":["You are going to read an anecdote about a philosophy exam. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-M) for each gap (21-30) in the text. Write the letter of the appropriate word in the white box.","You can use each word only once.","There is one extra word that you do not need to use."],"title":"THERE IS NO CHAIR","body":["An eccentric philosophy professor {{0}} his students a one-question final exam after a semester {{21}} with a wide range of topics. The class was already seated and ready to start the exam when the professor picked {{22}} his chair, put it on top of his desk and wrote on the board: \"Prove that this chair does not exist {{23}} everything we have learned this semester.\"","Fingers flew, erasers erased, notebooks {{24}} filled in furious fashion. Some students wrote over 30 pages in one hour {{25}} to disprove the existence of the chair. One member of the class, {{26}}, was up and finished in less than a minute. Everybody {{27}} astonished when he stood up, handed in his exam paper and left the room.","A week later, {{28}} the grades were posted on the notice board, the rest of the group wondered {{29}} he could have gotten an \"A\" when he had hardly written anything at all. His answer consisted {{30}} two words: \"What chair?\"","(www.stephen-knapp.com)"],"bank":[{"key":"A","text":"DEALING"},{"key":"B","text":"HOW"},{"key":"C","text":"GAVE"},{"key":"D","text":"HOWEVER"},{"key":"E","text":"OF"},{"key":"F","text":"OFF"},{"key":"G","text":"TRYING"},{"key":"H","text":"UP"},{"key":"I","text":"USING"},{"key":"K","text":"WAS"},{"key":"L","text":"WERE"},{"key":"M","text":"WHEN"}],"items":[{"n":0,"example":true,"answer":"C"},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26},{"n":27},{"n":28},{"n":29},{"n":30}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2016-maj-kozep-L3$mtr$, $mtr${"id":"2016-maj-kozep-L3","number":3,"kind":"bank","layout":"inline","examType":"szóbank (szavak visszahelyezése)","points":10,"instructions":["You are going to read an anecdote about a philosophy exam. Some words are missing from the text.","Your task is to choose the most appropriate word from the list (A-M) for each gap (21-30) in the text. Write the letter of the appropriate word in the white box.","You can use each word only once.","There is one extra word that you do not need to use."],"title":"THERE IS NO CHAIR","body":["An eccentric philosophy professor {{0}} his students a one-question final exam after a semester {{21}} with a wide range of topics. The class was already seated and ready to start the exam when the professor picked {{22}} his chair, put it on top of his desk and wrote on the board: \"Prove that this chair does not exist {{23}} everything we have learned this semester.\"","Fingers flew, erasers erased, notebooks {{24}} filled in furious fashion. Some students wrote over 30 pages in one hour {{25}} to disprove the existence of the chair. One member of the class, {{26}}, was up and finished in less than a minute. Everybody {{27}} astonished when he stood up, handed in his exam paper and left the room.","A week later, {{28}} the grades were posted on the notice board, the rest of the group wondered {{29}} he could have gotten an \"A\" when he had hardly written anything at all. His answer consisted {{30}} two words: \"What chair?\"","(www.stephen-knapp.com)"],"bank":[{"key":"A","text":"DEALING"},{"key":"B","text":"HOW"},{"key":"C","text":"GAVE"},{"key":"D","text":"HOWEVER"},{"key":"E","text":"OF"},{"key":"F","text":"OFF"},{"key":"G","text":"TRYING"},{"key":"H","text":"UP"},{"key":"I","text":"USING"},{"key":"K","text":"WAS"},{"key":"L","text":"WERE"},{"key":"M","text":"WHEN"}],"items":[{"n":0,"example":true,"answer":"C"},{"n":21,"answer":"A"},{"n":22,"answer":"H"},{"n":23,"answer":"I"},{"n":24,"answer":"L"},{"n":25,"answer":"G"},{"n":26,"answer":"D"},{"n":27,"answer":"K"},{"n":28,"answer":"M"},{"n":29,"answer":"B"},{"n":30,"answer":"E"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-maj-kozep-H1$mtr$, $mtr$2016-maj-kozep$mtr$, $mtr$listening$mtr$, 1, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 8, 8, $mtr${"id":"2016-maj-kozep-H1","number":1,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section you will hear a true story about a rescue dog called Duke.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_16maj_fl.mp3","start":0,"end":474.09,"clip":"hang/k_angol_16maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Jenna and Tom are a married couple.","answer":"A"},{"n":1,"stem":"Jenna and Tom found the dog on the street."},{"n":2,"stem":"It was Jenna’s idea to call the dog Duke."},{"n":3,"stem":"When they adopted Duke, Jenna and Tom felt that this would be the best decision of their life."},{"n":4,"stem":"The couple woke up because Duke was barking loudly."},{"n":5,"stem":"They knew something was wrong because Duke had never behaved like that before."},{"n":6,"stem":"Their daughter had fallen out of her bed."},{"n":7,"stem":"The paramedics arrived within ten minutes."},{"n":8,"stem":"The baby was revived in the hospital."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_16maj_fl.mp3","start":0,"end":474.09,"clip":"hang/k_angol_16maj_fl_H1.mp3"}$mtr$::jsonb)
