insert into public.task_keys (task_id, task) values ($mtr$2016-maj-kozep-H2$mtr$, $mtr${"id":"2016-maj-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":9,"instructions":["In this section, you are going to hear a true story about Muhammad Ali, the famous boxer.","Your task is to give short answers to the questions below using the exact words you hear.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_16maj_fl.mp3","start":474.09,"end":1023.66,"clip":"hang/k_angol_16maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"When did Ali change his name? In {{gap}}","accept":["1964"]},{"n":9,"stem":"What was the religious movement that Ali joined called? It was called the {{gap}}","key":"Nation of Islam","keywords":[["nation","islam"]]},{"n":10,"stem":"What two animals did Ali mention in his statement? He mentioned a(n) {{gap}} and a(n) {{gap}}","key":"butterfly, bee // bee, butterfly (both, one is not enough, but the order is not important!)","gaps":[["butterfly"],["bee"]],"unordered":true},{"n":11,"stem":"What did Ali and his friend decide to visit? They decided to visit a(n) {{gap}}","key":"(charity) sale","keywords":[["sale"]]},{"n":12,"stem":"Where did they leave their bikes? They left their bikes {{gap}}","key":"in front of the building / (Columbia) Auditorium","keywords":[["front","building"],["front","auditorium"]]},{"n":13,"stem":"What did they eat? They ate hot dogs and {{gap}}","key":"popcorn","keywords":[["popcorn"]]},{"n":14,"stem":"Where in the basement did Ali find Joe Martin? He found him in the {{gap}}","key":"(local) gym","keywords":[["gym"]]},{"n":15,"stem":"After they filled out a police report, what did Joe Martin hand Ali? He handed him a(n) {{gap}}","key":"application form (to join the boxing club)","keywords":[["application","form"]]},{"n":16,"stem":"What did Joe Martin teach Ali? He taught him the {{gap}}","key":"basics (of the game/boxing)","keywords":[["basics"]]},{"n":17,"stem":"What did Ali win in 1960? He won {{gap}}","key":"(an Olympic) gold medal / (the Rome) Olympics","keywords":[["gold","medal"],["olympics"]]}],"grading":{"spelling":"keywords","caseSensitive":false}}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-maj-kozep-H3$mtr$, $mtr$2016-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$feleletválasztás hallás után$mtr$, 8, 10, $mtr${"id":"2016-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"feleletválasztás hallás után","points":8,"instructions":["In this section you are going to hear an Australian tourist guide from Melbourne promoting an interesting programme to some tourists.","Your task is to write the letter of the correct answer into the boxes on the right.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_16maj_fl.mp3","start":1023.66,"end":1795.71,"clip":"hang/k_angol_16maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"The tourist guide says they … have visitors from Hungary.","options":[{"key":"A","text":"often"},{"key":"B","text":"don’t often"},{"key":"C","text":"never"}],"answer":"B"},{"n":18,"stem":"The tourists are going to spend … in Melbourne.","options":[{"key":"A","text":"one day"},{"key":"B","text":"three days"},{"key":"C","text":"seven days"}]},{"n":19,"stem":"On Philip Island, the majority of the land is devoted to …","options":[{"key":"A","text":"agriculture."},{"key":"B","text":"wildlife."},{"key":"C","text":"tourist attractions."}]},{"n":20,"stem":"In Maru Wildlife Park, tourists …","options":[{"key":"A","text":"watch the animals from a special bus."},{"key":"B","text":"can actually touch some of the animals."},{"key":"C","text":"are not allowed to give the animals food."}]},{"n":21,"stem":"The tourists will get to Philip Island from the mainland …","options":[{"key":"A","text":"by boat."},{"key":"B","text":"through a tunnel."},{"key":"C","text":"over a bridge."}]},{"n":22,"stem":"At Woolamai Beach, …","options":[{"key":"A","text":"the waves are enormous."},{"key":"B","text":"swimming is dangerous."},{"key":"C","text":"there is a colony of fur seals."}]},{"n":23,"stem":"The best time to watch the penguins is when the sun is …","options":[{"key":"A","text":"shining brightly."},{"key":"B","text":"going down."},{"key":"C","text":"behind clouds."}]},{"n":24,"stem":"The guide recommends that tourists should take …","options":[{"key":"A","text":"their young children with them."},{"key":"B","text":"some sunscreen with them."},{"key":"C","text":"photos of the marching penguins."}]},{"n":25,"stem":"The guide says that the $90.00 price includes …","options":[{"key":"A","text":"two entry fees."},{"key":"B","text":"lunch and dinner."},{"key":"C","text":"travel insurance."}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_16maj_fl.mp3","start":1023.66,"end":1795.71,"clip":"hang/k_angol_16maj_fl_H3.mp3"}$mtr$::jsonb)
