insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2016-okt-kozep-H2$mtr$, $mtr$2016-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 9, $mtr${"id":"2016-okt-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear a true story about a Costa Rican fisherman who survived a 5-month drift in a boat on the ocean.","Your task is to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_16okt_fl.mp3","start":618.62,"end":1220.09,"clip":"hang/k_angol_16okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Joel Gonzales kissed his wife goodbye on December 24, 1988.","answer":"B"},{"n":9,"stem":"He was going on a weekend fishing trip with his friends."},{"n":10,"stem":"There were four men on the fishing boat."},{"n":11,"stem":"The storm lasted for more than two weeks."},{"n":12,"stem":"They used their fishing nets to catch big turtles."},{"n":13,"stem":"They burnt up parts of the their boat to make fire to cook the meat."},{"n":14,"stem":"They collected rainwater on a roof they built themselves."},{"n":15,"stem":"It was extremely hot at the beginning of June."},{"n":16,"stem":"The men never really believed they would die."},{"n":17,"stem":"When the Japanese boat found them, they were all unconscious."}],"options":[{"key":"A","text":"TRUE