insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-kozep-L1$mtr$, $mtr$2017-okt-kozep$mtr$, $mtr$language$mtr$, 1, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 9, 5, $mtr${"id":"2017-okt-kozep-L1","number":1,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about an interesting board game. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (1-9).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"BEYOND MONOPOLY","body":["Christmas is here! This is the time when families across the nation take out their one {{0}} copy of Monopoly, play it for half an hour before realising Monopoly is terribly {{1}}, and then go on playing for another three hours before a drunk uncle starts shouting furiously after {{2}} his final property to a five-year-old.","Don’t play Monopoly. Just make sure that you have a much {{3}} game on the shelf in time for your family’s Christmas and you’ll have a lot more fun and {{4}}. Ticket to Ride is your game.","In the game the {{5}} need to connect up cities in 19th-century America, building out a railroad network while trying to block {{6}} from doing the same. You’ll be trying really {{7}} to draw the cards needed to connect Seattle to New York, while also trying not to give away that those are the cities you’re trying to link. If you are not {{8}}, an opponent (who you’re pretty certain is joining Detroit to Los Angeles) will change {{9}} own route in order to block you, ruining your chance to finish the route for good. It sounds like fun, doesn’t it?","(http://www.theguardian.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"dust","example":true,"accept":["dusty"]},{"n":1,"prompt":"bore"},{"n":2,"prompt":"lose"},{"n":3,"prompt":"good"},{"n":4,"prompt":"act"},{"n":5,"prompt":"play"},{"n":6,"prompt":"compete"},{"n":7,"prompt":"hard"},{"n":8,"prompt":"care"},{"n":9,"prompt":"they"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-okt-kozep-L1$mtr$, $mtr${"id":"2017-okt-kozep-L1","number":1,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about an interesting board game. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (1-9).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"BEYOND MONOPOLY","body":["Christmas is here! This is the time when families across the nation take out their one {{0}} copy of Monopoly, play it for half an hour before realising Monopoly is terribly {{1}}, and then go on playing for another three hours before a drunk uncle starts shouting furiously after {{2}} his final property to a five-year-old.","Don’t play Monopoly. Just make sure that you have a much {{3}} game on the shelf in time for your family’s Christmas and you’ll have a lot more fun and {{4}}. Ticket to Ride is your game.","In the game the {{5}} need to connect up cities in 19th-century America, building out a railroad network while trying to block {{6}} from doing the same. You’ll be trying really {{7}} to draw the cards needed to connect Seattle to New York, while also trying not to give away that those are the cities you’re trying to link. If you are not {{8}}, an opponent (who you’re pretty certain is joining Detroit to Los Angeles) will change {{9}} own route in order to block you, ruining your chance to finish the route for good. It sounds like fun, doesn’t it?","(http://www.theguardian.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"dust","example":true,"accept":["dusty"]},{"n":1,"prompt":"bore","accept":["boring"]},{"n":2,"prompt":"lose","accept":["losing"]},{"n":3,"prompt":"good","accept":["better"]},{"n":4,"prompt":"act","accept":["action","activity"]},{"n":5,"prompt":"play","accept":["players"]},{"n":6,"prompt":"compete","accept":["competitors"]},{"n":7,"prompt":"hard","accept":["hard"]},{"n":8,"prompt":"care","accept":["careful"]},{"n":9,"prompt":"they","accept":["their"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2017-okt-kozep-L2$mtr$, $mtr$2017-okt-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 8, 6, $mtr${"id":"2017-okt-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an anecdote about the Scottish poet, Robert Burns. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (10-17) after the text.","Use only one word in each gap."],"title":"POETIC WISDOM","body":["Robert Burns, the great Scottish poet, loved common people and wrote for {{0}}. Though he had little formal education, he was well read and talented. He began to be recognized {{10}} a poet when his first poems were published in 1786.","One day when Burns was walking near the docks, he heard a man crying {{11}} help. He ran towards the water and saw a young sailor jump off the dock. The sailor started to swim towards the man, who was already drowning. Although it was {{12}} easy, the sailor saved the man. It turned {{13}} that the man who survived the incident was a very rich merchant. He thanked the brave sailor and gave him a shilling.","A large crowd of people gathered around them. All the people considered the sailor to be a hero, so they {{14}} displeased when the rich man offered only a shilling. Many people were protesting, but the merchant did not {{15}} any attention to them. At that moment Burns approached the crowd and wondered {{16}} the matter was. He was told the whole story. Burns was not surprised {{17}} the behaviour of the rich merchant. He said: “Leave him alone. The gentleman is the best judge of what his life is worth.”","(http://www.england-history.org)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["them"]},{"n":10},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16},{"n":17}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2017-okt-kozep-L2$mtr$, $mtr${"id":"2017-okt-kozep-L2","number":2,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an anecdote about the Scottish poet, Robert Burns. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (10-17) after the text.","Use only one word in each gap."],"title":"POETIC WISDOM","body":["Robert Burns, the great Scottish poet, loved common people and wrote for {{0}}. Though he had little formal education, he was well read and talented. He began to be recognized {{10}} a poet when his first poems were published in 1786.","One day when Burns was walking near the docks, he heard a man crying {{11}} help. He ran towards the water and saw a young sailor jump off the dock. The sailor started to swim towards the man, who was already drowning. Although it was {{12}} easy, the sailor saved the man. It turned {{13}} that the man who survived the incident was a very rich merchant. He thanked the brave sailor and gave him a shilling.","A large crowd of people gathered around them. All the people considered the sailor to be a hero, so they {{14}} displeased when the rich man offered only a shilling. Many people were protesting, but the merchant did not {{15}} any attention to them. At that moment Burns approached the crowd and wondered {{16}} the matter was. He was told the whole story. Burns was not surprised {{17}} the behaviour of the rich merchant. He said: “Leave him alone. The gentleman is the best judge of what his life is worth.”","(http://www.england-history.org)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["them"]},{"n":10,"accept":["as"]},{"n":11,"accept":["for"]},{"n":12,"accept":["not","hardly"]},{"n":13,"accept":["out"]},{"n":14,"accept":["were","got","became","felt"]},{"n":15,"accept":["pay","give"]},{"n":16,"accept":["what"]},{"n"