insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-maj-kozep-L2$mtr$, $mtr$2018-maj-kozep$mtr$, $mtr$language$mtr$, 2, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 9, 6, $mtr${"id":"2018-maj-kozep-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":9,"instructions":["You are going to read an article about a strange sport called ‘wife carrying’. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (8-16) in the text."],"title":"WIFE CARRYING","body":["Wife carrying is a sport in {{0}} male competitors race while each carrying a female teammate. The aim is for the male {{8}} the female through a special track in the fastest time. The winning team takes home the wife's weight {{9}} beer.","Wife Carrying started in Finland, and its history is based on the 19th century legend of “Ronkainen the Robber”. Ronkainen and his thieves {{10}} food and women from villages in the area where they lived, {{11}} they carried the women on their backs as they ran away.","The first wife carrying event was held in Finland in 1992. It now {{12}} place there as the World Championship every year. Here are some of the rules:"," Teammates are not {{13}} to be legally married.  The minimum weight for the female competitor is 49 kilograms, and she {{14}} be at least 18.  The only equipment allowed is a belt {{15}} by the carrier. A helmet is necessary for the woman.  There is no restriction on how the female teammate is carried.  If a competitor {{16}} his teammate, their team will be punished with five seconds added to their time.","(http://www.wife-carrying.org)"],"items":[{"n":0,"options":[{"key":"A","text":"that"},{"key":"B","text":"what"},{"key":"C","text":"which"},{"key":"D","text":"-"}],"example":true,"answer":"C"},{"n":8,"options":[{"key":"A","text":"carrying"},{"key":"B","text":"who carries"},{"key":"C","text":"is carrying"},{"key":"D","text":"to carry"}]},{"n":9,"options":[{"key":"A","text":"by"},{"key":"B","text":"in"},{"key":"C","text":"with"},{"key":"D","text":"from"}]},{"n":10,"options":[{"key":"A","text":"were stolen"},{"key":"B","text":"stole"},{"key":"C","text":"have stolen"},{"key":"D","text":"was stealing"}]},{"n":11,"options":[{"key":"A","text":"then"},{"key":"B","text":"after"},{"key":"C","text":"than"},{"key":"D","text":"when"}]},{"n":12,"options":[{"key":"A","text":"holds"},{"key":"B","text":"makes"},{"key":"C","text":"takes"},{"key":"D","text":"gets"}]},{"n":13,"options":[{"key":"A","text":"required"},{"key":"B","text":"respected"},{"key":"C","text":"refused"},{"key":"D","text":"reminded"}]},{"n":14,"options":[{"key":"A","text":"can"},{"key":"B","text":"may"},{"key":"C","text":"might"},{"key":"D","text":"must"}]},{"n":15,"options":[{"key":"A","text":"what is worn"},{"key":"B","text":"is worn"},{"key":"C","text":"worn"},{"key":"D","text":"wearing"}]},{"n":16,"options":[{"key":"A","text":"is dropped"},{"key":"B","text":"drops"},{"key":"C","text":"will drop"},{"key":"D","text":"have dropped"}]}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2018-maj-kozep-L2$mtr$, $mtr${"id":"2018-maj-kozep-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":9,"instructions":["You are going to read an article about a strange sport called ‘wife carrying’. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (8-16) in the text."],"title":"WIFE CARRYING","body":["Wife carrying is a sport in {{0}} male competitors race while each carrying a female teammate. The aim is for the male {{8}} the female through a special track in the fastest time. The winning team takes home the wife's weight {{9}} beer.","Wife Carrying started in Finland, and its history is based on the 19th century legend of “Ronkainen the Robber”. Ronkainen and his thieves {{10}} food and women from villages in the area where they lived, {{11}} they carried the women on their backs as they ran away.","The first wife carrying event was held in Finland in 1992. It now {{12}} place there as the World Championship every year. Here are some of the rules:"," Teammates are not {{13}} to be legally married.  The minimum weight for the female competitor is 49 kilograms, and she {{14}} be at least 18.  The only equipment allowed is a belt {{15}} by the carrier. A helmet is necessary for the woman.  There is no restriction on how the female teammate is carried.  If a competitor {{16}} his teammate, their team will be punished with five seconds added to their time.","(http://www.wife-carrying.org)"],"items":[{"n":0,"options":[{"key":"A","text":"that"},{"key":"B","text":"what"},{"key":"C","text":"which"},{"key":"D","text":"-"}],"example":true,"answer":"C"},{"n":8,"options":[{"key":"A","text":"carrying"},{"key":"B","text":"who carries"},{"key":"C","text":"is carrying"},{"key":"D","text":"to carry"}],"answer":"D"},{"n":9,"options":[{"key":"A","text":"by"},{"key":"B","text":"in"},{"key":"C","text"