insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-maj-kozep-H3$mtr$, $mtr$2018-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 8, 10, $mtr${"id":"2018-maj-kozep-H3","number":3,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":8,"instructions":["In this section, you are going to hear a radio interview with Zlatan Ibrahimović, the Swedish football superstar, talking about his childhood.","Your task is to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you will have to circle one or two letters.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to make your decision about your answers."],"audio":{"file":"k_angol_18maj_fl.mp3","start":1112.09,"end":1794.25,"clip":"hang/k_angol_18maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Zlatan’s parents are from …","options":[{"key":"A","text":"Croatia."},{"key":"B","text":"Bosnia."}],"answer":["A","B"]},{"n":18,"stem":"Rosengard …","options":[{"key":"A","text":"was considered a bad area."},{"key":"B","text":"has changed for the better."}]},{"n":19,"stem":"Zlatan thinks that the area he came from made him …","options":[{"key":"A","text":"tough."},{"key":"B","text":"self-confident."}]},{"n":20,"stem":"Zlatan …","options":[{"key":"A","text":"feels bad about the place where he came from."},{"key":"B","text":"thinks that his example can be followed."}]},{"n":21,"stem":"After Zlatan’s parents got divorced, he …","options":[{"key":"A","text":"accepted his stepfather quite easily."},{"key":"B","text":"lost a lot of weight."}]},{"n":22,"stem":"Zlatan ...","options":[{"key":"A","text":"stole bikes to get to football trainings."},{"key":"B","text":"used the postman’s bike for a long time."}]},{"n":23,"stem":"Zlatan …","options":[{"key":"A","text":"bought a shop for his old friends."},{"key":"B","text":"understands why his friends still steal."}]},{"n":24,"stem":"Zlatan’s headmistress …","options":[{"key":"A","text":"said Zlatan was among the worst pupils she had ever had."},{"key":"B","text":"thought Zlatan would get into serious trouble one day."}]},{"n":25,"stem":"Zlatan admits that he …","options":[{"key":"A","text":"was a noisy and violent pupil."},{"key":"B","text":"sometimes only went to school to eat."}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_18maj_fl.mp3","start":1112.09,"end":1794.25,"clip":"hang/k_angol_18maj_fl_H3.mp3"}$mtr$::jsonb)
