insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-okt-emelt-L2$mtr$, $mtr$2018-okt-emelt$mtr$, $mtr$language$mtr$, 2, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 9, 6, $mtr${"id":"2018-okt-emelt-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about Michelangelo, the great Renaissance artist.","Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (10-18).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THE ART OF FORGERY","body":["In his new book The Art of Forgery, art {{0}} Noah Charney explores how the best {{10}} in the world managed to fool many experts. Here, he reveals that Michelangelo was one of them.","Before anyone had heard of Michelangelo Buonarotti, the most {{11}} sculptures on the Renaissance Italian art market were ancient Roman marble statues. Several {{12}} records demonstrate that even an artist as great as Michelangelo could be involved in {{13}} forgery, setting out to create an “ancient Roman statue” of his own. It did nothing to ruin his {{14}}. Indeed, having successfully passed off his work as a Roman statue helped the beginning of a(n) {{15}} career, by showing that Michelangelo had the technical skill and {{16}} genius to match his ancestors.","Michelangelo carved the marble statue Sleeping Eros in 1496, when he was only 21 and, according to renowned historian Paolo Giovio, doctored it in order to make it appear to be ancient. The statue was sold to Cardinal Raffaele Riario, a great {{17}} of early Roman antiquities.","When Riario later found out that he had bought a forgery, he returned the statue to the dealer from whom he had bought it. However, in the meantime, Michelangelo had gone from being an unknown 21-year-old to Rome’s hottest celebrity, thanks largely to the {{18}} of his Pietà, which proudly stood in the Basilica of Saint Peter in Rome. The dealer was thus happy to take it back, and had no trouble selling it on, now under the authorship of the suddenly famous Michelangelo.","(http://www.bbc.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"prompt":"history","example":true,"accept":["historian"]},{"n":10,"prompt":"forge"},{"n":11,"prompt":"value"},{"n":12,"prompt":"biography"},{"n":13,"prompt":"intention"},{"n":14,"prompt":"repute"},{"n":15,"prompt":"believe"},{"n":16,"prompt":"create"},{"n":17,"prompt":"collect"},{"n":18,"prompt":"fame"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2018-okt-emelt-L2$mtr$, $mtr${"id":"2018-okt-emelt-L2","number":2,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"instructions":["You are going to read an article about Michelangelo, the great Renaissance artist.","Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (10-18).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"THE ART OF FORGERY","body":["In his new book The Art of Forgery, art {{0}} Noah Charney explores how the best {{10}} in the world managed to fool many experts. Here, he reveals that Michelangelo was one of them.","Before anyone had heard of Michelangelo Buonarotti, the most {{11}} sculptures on the Renaissance Italian art market were ancient Roman marble statues. Several {{12}} records demonstrate that even an artist as great as Michelangelo could be involved in {{13}} forgery, setting out to create an “ancient Roman statue” of his own. It did nothing to ruin his {{14}}. Indeed, having successfully passed off his work as a Roman statue helped the beginning of a(n) {{15}} career, by showing that Michelangelo had the technical skill and {{16}} genius to match his ancestors.","Michelangelo carved the marble statue Sleeping Eros in 1496, when he was only 21 and, according to renowned historian Paolo Giovio, doctored it in order to make it appear to be ancient. The statue was sold to Cardinal Raffaele Riario, a great {{17}} of early Roman antiquities.","When Riario later found out that he had bought a forgery, he returned the statue to the dealer from whom he had bought it. However, in the meantime, Michelangelo had gone from being an unknown 21-year-old to Rome’s hottest celebrity, thanks largely to the {{18}} of his Pietà, which proudly stood in the Basilica of Saint Peter in Rome. The dealer was thus happy to take it back, and had no trouble selling it on, now under the authorship of the suddenly famous Michelangelo.","(http://www.bbc.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"prompt":"history","example":true,"accept":["historian"]},{"n":10,"prompt":"forge","accept":["forgers"]},{"n":11,"prompt":"value","accept":["valuable","valued"]},{"n":12,"prompt":"biography","accept":["biographical","biographic"]},{"n":13,"prompt":"intention","accept":["intentional"]},{"n":14,"prompt":"repute","accept":["reputation"]},{"n":15,"prompt":"believe","accept":["unbelievable"]},{"n":16,"prompt":"create","accept":["creative"]},{"n":17,"prompt":"collect","accept":["collector"]},{"n":18,"prompt":"fame","accept":["fame"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-okt-emelt-L3$mtr$, $mtr$2018-okt-emelt$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 8, 7, $mtr${"id":"2018-okt-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about a controversial advertising campaign. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (19-26) after the text.","Use only one word in each gap."],"title":"FAT & UGLY? JUST BE UGLY","body":["People aren’t amused by gym’s ‘light-hearted’ ad A gym chain based in Derbyshire {{0}} divided opinion with its latest ‘light-hearted’ membership ad. The new Fit4Less gym advertising billboard, spotted in Sawley, Derbyshire, reads: ‘Tired of being…Fat & Ugly? Just be ugly at Fit4Less’.","The gym chain has used similar posters before, {{19}} the Sawley billboard has caused public outrage. And this billboard replaces one they were asked to remove in April, {{20}} depicted a UFO picking someone up, with the words ‘they’ll take the fat ones first.’","What happened {{21}} the time was that local anti-bullying charity Combat Bullying condemned the poster for encouraging bullying. And they’re {{22}} impressed with the replacement.","‘I don’t understand why they are using these kinds of advertising. It’s almost like shaming people,’ the charity’s founder Natalie Harvey {{23}} the BBC.","Others, however, defended the ad, saying people were just ‘too sensitive’. In a statement, the gym said: ‘Fit4less is a brand that doesn’t take itself too {{24}}; the campaign is intended to be seen as light-hearted fun and we certainly don’t mean {{25}} cause offence.’","The gym also claims that {{26}} adopting a light-hearted approach they can reach a wider audience and gain the attention of people who wouldn’t usually respond to traditional gym advertising.","(http://metro.co.uk)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["has"]},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25},{"n":26}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2018-okt-emelt-L3$mtr$, $mtr${"id":"2018-okt-emelt-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about a controversial advertising campaign. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (19-26) after the text.","Use only one word in each gap."],"title":"FAT & UGLY? JUST BE UGLY","body":["People aren’t amused by gym’s ‘light-hearted’ ad A gym chain based in Derbyshire {{0}} divided opinion with its latest ‘light-hearted’ membership ad. The new Fit4Less gym advertising billboard, spotted in Sawley, Derbyshire, reads: ‘Tired of being…Fat & Ugly? Just be ugly at Fit4Less’.","The gym chain has used similar posters before, {{19}} the Sawley billboard has caused public outrage. And this billboard replaces one they were asked to remove in April, {{20}} depicted a UFO picking someone up, with the words ‘they’ll take the fat ones first.’","What happened {{21}} the time was that local anti-bullying charity Combat Bullying condemned the poster for encouraging bullying. And they’re {{22}} impressed with the replacement.","‘I don’t understand why they are using these kinds of advertising. It’s almost like shaming people,’ the charity’s founder Natalie Harvey {{23}} the BBC.","Others, however, defended the ad, saying people were just ‘too sensitive’. In a statement, the gym said: ‘Fit4less is a brand that doesn’t take itself too {{24}}; the campaign is intended to be seen as light-hearted fun and we certainly don’t mean {{25}} cause offence.’","The gym also claims that {{26}} adopting a light-hearted approach they can reach a wider audience and gain the attention of people who wouldn’t usually respond to traditional gym advertising.","(http://metro.co.uk)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["has"]},{"n":19,"accept":["but","and"]},{"n":20,"accept":["which"]},{"n":21,"accept":["at"]},{"n":22,"accept":["not","hardly","less","barely","scarcely"]},{"n":23,"accept":["told","informed"]},{"n":24,"accept":["seriously"]},{"n":25,"accept":["to"]},{"n":26,"accept":["by","through","when"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2018-okt-emelt-L4$mtr$, $mtr$2018-okt-emelt$mtr$, $mtr$language$mtr$, 4, $mtr$lines$mtr$, $mtr$soronkénti hibakeresés (felesleges szó vagy helyes sor)$mtr$, 9, 8, $mtr${"id":"2018-okt-emelt-L4","number":4,"kind":"lines","layout":"lines","examType":"soronkénti hibakeresés (felesleges szó vagy helyes sor)","points":9,"instructions":["You are going to read an article about a small town in Alaska. In most lines there is one word that should not be there. It is either grammatically incorrect or does not fit in with the sense of the text.","Read the text and then copy the extra word in the space provided after each line.","Some lines are correct. Indicate these lines with a tick ().","The task begins with two examples (0)."],"title":"LET'S HOPE THEY LIKE THEIR NEIGHBOURS!","intro":"","items":[{"n":"0a","example":true,"text":"The small Alaskan town of Whittier sees up to 250 inches of the","answer":"the"},{"n":"0b","example":true,"text":"snow annually. Surrounded only by mountains and the sea, the","answer":null},{"n":27,"text":"remote town is so isolated that it’s only accessible by the North"},{"n":28,"text":"America’s longest one-way tunnel, which one stretches for two and"},{"n":29,"text":"a half miles. In Whittier all 218 residents live in one single multi-"},{"n":30,"text":"story building. The building several houses the town’s entire"},{"n":31,"text":"neighbourhood, including in the local police department, a school,"},{"n":32,"text":"two convenience stores, a laundromat and the post office. The local"},{"n":33,"text":"church performs baptisms in an inflatable pool in the same"},{"n":34,"text":"basement and children can enough easily knock on their teacher's"},{"n":35,"text":"door for homework help in the evenings. Most of residents work for"}],"outro":"the port as boat mechanics, but a few drive out to work outside the community. (http://www.dailymail.co.uk)"}$mtr$::jsonb, null)
