excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2019-maj-emelt-H1$mtr$, $mtr$2019-maj-emelt$mtr$, $mtr$listening$mtr$, 1, $mtr$bank$mtr$, $mtr$párosítás hallás után$mtr$, 6, 9, $mtr${"id":"2019-maj-emelt-H1","number":1,"kind":"bank","layout":"stems","examType":"párosítás hallás után","points":6,"instructions":["In this section you will hear some jokes.","Your task will be to match the titles of the jokes on the left with the names of the people who tell the jokes on the right. Put the letters in the grid.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_19maj_fl.mp3","start":0,"end":649.84,"clip":"hang/e_angol_19maj_fl_H1.mp3"},"bank":[{"key":"A","text":"AGING PROCESS"},{"key":"B","text":"THE RICH AND THE POOR"},{"key":"C","text":"A BAD HABIT"},{"key":"D","text":"ELEMENTARY ARITHMETIC"},{"key":"E","text":"KNOWLEDGE IS POWER"},{"key":"F","text":"CLOSE RELATIVES"},{"key":"G","text":"EFFECTIVE ADVERTISING"}],"items":[{"n":0,"example":true,"stem":"John’s joke","answer":"C"},{"n":1,"stem":"Peter’s joke"},{"n":2,"stem":"Judith’s joke"},{"n":3,"stem":"Charles’s first joke"},{"n":4,"stem":"Ann’s first joke"},{"n":5,"stem":"Ann’s second joke"},{"n":6,"stem":"Charles’s second joke"}]}$mtr$::jsonb, $mtr${"file":"e_angol_19maj_fl.mp3","start":0,"end":649.84,"clip":"hang/e_angol_19maj_fl_H1.mp3"}$mtr$::jsonb)
