insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2019-maj-kozep-L3$mtr$, $mtr$2019-maj-kozep$mtr$, $mtr$language$mtr$, 3, $mtr$text$mtr$, $mtr$nyílt cloze (egy szó)$mtr$, 8, 7, $mtr${"id":"2019-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about fairy tales. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-25) after the text.","Use only one word in each gap."],"title":"FAIRY TALES – SCARY TALES","body":["Many generations are familiar with the characters from Cinderella or Beauty and the Beast thanks {{0}} Disney’s hit adaptations of the original fairy tales.","Pictures of big-eyed beautiful females and charming males are among the first details a lot {{18}} viewers mention when asked about the movies. But {{19}} truth is that the Disneyfied tales are often very different from the original story.","While we often associate fairy tales with children’s bedtime stories, their original purpose was {{20}} else. The original tales suggested the idea that people {{21}} do morally wrong things will {{22}} punished. Some fairy tales started out as oral stories, passed down from generation to generation, as a warning to little children (and adults) {{23}} be good. The most famous versions of these tales {{24}} written down by the Grimm brothers and Hans Christian Andersen.","While some level of morality still exists in the Disney tales and stories, most of their original, darker details and endings {{25}} been removed. Did you know that in the Grimm brothers’ version of Cinderella there is enough blood for a modern thriller?","(https://reelrundown.com)"],"grading":{"spelling":"strict"},"items":[{"n":0,"example":true,"accept":["to"]},{"n":18},{"n":19},{"n":20},{"n":21},{"n":22},{"n":23},{"n":24},{"n":25}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2019-maj-kozep-L3$mtr$, $mtr${"id":"2019-maj-kozep-L3","number":3,"kind":"text","layout":"inline","examType":"nyílt cloze (egy szó)","points":8,"instructions":["You are going to read an article about fairy tales. Some words are missing from the text.","Your task is to write the missing words on the dotted lines (18-25) after the text.","Use only one word in each gap."],"title":"FAIRY TALES – SCARY TALES","body":["Many generations are familiar with the characters from Cinderella or Beauty and the Beast thanks {{0}} Disney’s hit adaptations of the original fairy tales.","Pictures of big-eyed beautiful females and charming males are among the first details a lot {{18}} viewers mention when asked about the movies. But {{19}} truth is that the Disneyfied tales are often very different from the original story.","While we often associate fairy tales with children’s bedtime stories, their original purpose was {{20}} else. The original tales suggested the idea that people {{21}} do morally wrong things will {{22}} punished. Some fairy tales started out as oral stories, passed down from generation to generation, as a warning to little children (and adults) {{23}} be good. The most famous versions of these tales {{24}} written down by the Grimm brothers and Hans Christian Andersen.","While some level of morality still exists in the Disney tales and stories, most of their original, darker details and endings {{25}} been removed. Did you know that in the Grimm brothers’ version of Cinderella there is enough blood for a modern thriller?","(https://reelrundown.com)"],"grading":{"spelling":"strict","maxWords":1},"items":[{"n":0,"example":true,"accept":["to"]},{"n":18,"accept":["of"]},{"n":19,"accept":["the"]},{"n":20,"accept":["something"]},{"n":21,"accept":["who","that"]},{"n":22,"accept":["be","get"]},{"n":23,"accept":["to"]},{"n":24,"accept":["were","got"]},{"n":25,"accept":["have"]}]}$mtr$::jsonb) on conflict (task_id) d