insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2019-maj-kozep-H2$mtr$, $mtr$2019-maj-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 9, 8, $mtr${"id":"2019-maj-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":9,"instructions":["In this section you will hear an anecdote about a college professor and life in general.","Your task will be to give short answers to the questions below by continuing the sentences we have begun for you.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_19maj_fl.mp3","start":620.55,"end":1228.32,"clip":"hang/k_angol_19maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"What did the college professor fill the jar with first? He filled it with {{gap}}","accept":["golf balls"]},{"n":8,"stem":"What did he put into the jar next? He put in a box of {{gap}}"},{"n":9,"stem":"What did he pour into the jar after that? He poured in a box of {{gap}}"},{"n":10,"stem":"What liquid did he use to fill the empty spaces left in the jar? He used {{gap}}"},{"n":11,"stem":"Name two things that the professor considered “important” in life. Your {{gap}} {{gap}}"},{"n":12,"stem":"Name two things that the professor listed as “other things that matter in life”. Your {{gap}} {{gap}}"},{"n":13,"stem":"What did the professor mean by the “small stuff”? He meant {{gap}}"},{"n":14,"stem":"What happens if you spend all your energy on the “small stuff”? You will never have time for the {{gap}}"},{"n":15,"stem":"Name two pieces of advice that he gave to illustrate the things that are essential to happiness. You should {{gap}} {{gap}}"},{"n":16,"stem":"What does the last thing he poured into the jar represent in his analogy? That we should always have time for a(n) {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_19maj_fl.mp3","start":620.55,"end":1228.32,"clip":"hang/k_angol_19maj_fl_H2.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2019-maj-kozep-H2$mtr$, $mtr${"id":"2019-maj-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":9,"instructions":["In this section you will hear an anecdote about a college professor and life in general.","Your task will be to give short answers to the questions below by continuing the sentences we have begun for you.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_19maj_fl.mp3","start":620.55,"end":1228.32,"clip":"hang/k_angol_19maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"What did the college professor fill the jar with first? He filled it with {{gap}}","accept":["golf balls"]},{"n":8,"stem":"What did he put into the jar next? He put in a box of {{gap}}","key":"small stones.","keywords":[["small","stones"]]},{"n":9,"stem":"What did he pour into the jar after that? He poured in a box of {{gap}}","key":"sand.","keywords":[["sand"]]},{"n":10,"stem":"What liquid did he use to fill the empty spaces left in the jar? He used {{gap}}","key":"beer.","keywords":[["beer"]]},{"n":11,"stem":"Name two things that the professor considered “important” in life. Your {{gap}} {{gap}}","key":"family, health, friends, your feeling of well- being. (Bármely két megoldás elfogadható.)","keywords":[["family","health"],["family","friends"],["family","well-being"],["family","well","being"],["health","friends"],["health","well-being"],["health","well","being"],["friends","well-being"],["friends","well","being"]]},{"n":12,"stem":"Name two things that the professor listed as “other things that matter in life”. Your {{gap}} {{gap}}","key":"job/work, house, achievements. (Bármely két megoldás elfogadható.)","keywords":[["job","house"],["job","achievements"],["work","house"],["work","achievements"],["house","achievements"]]},{"n":13,"stem":"What did the professor mean by the “small stuff”? He meant {{gap}}","key":"everything else // all other things // everything that’s left.","keywords":[["everything","else"],["all","other","things"],["everything","that’s","left"]]},{"n":14,"stem":"What happens if you spend all your energy on the “small stuff”? You will never have time for the {{gap}}","key":"things that are (really) important to you. // important things/stuff // things that matter.","keywords":[["important","things"],["important","stuff"],["things","matter"]]},{"n":15,"stem":"Name two pieces of advice that he gave to illustrate the things that are essential to happiness. You should {{gap}} {{gap}}","key":"spend time with your parents, play with your children/kids, enjoy the beauty of existence. (Bármely két megoldás elfogadható.)","keywords":[["time","parents","play","children"],["time","parents","play","kids"],["time","parents","beauty","existence"],["play","children","beauty","existence"],["play","kids","beauty","existence"]]},{"n":16,"stem":"What does the last thing he poured into the jar represent in his analogy? That we should always have time for a(n) {{gap}}","key":"drink with a friend // drink with your friend/friends. (also acceptable: beer with a friend // beer with your friend/friends.)","keywords":[["drink","friend"],["drink","friends"],["beer","friend"],["beer","friends"]]}],"grading":{"spelling":"keywords","caseSensitive":false}}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2019-maj-kozep-H3$mtr$, $mtr$2019-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$fix$mtr$, $mtr$hibás szó javítása hallás után$mtr$, 9, 9, $mtr${"id":"2019-maj-kozep-H3","number":3,"kind":"fix","layout":"stems","examType":"hibás szó javítása hallás után","points":9,"instructions":["In this section, you will hear a bizarre telephone conversation between a customer and a pizza restaurant operator.","Your task will be to find one word in each of the following sentences that is not correct in the context of the recording. First, cross it out, and then write the correct one on the line after the sentence. First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_19maj_fl.mp3","start":1228.32,"end":1795.82,"clip":"hang/k_angol_19maj_fl_H3.mp3"},"items":[{"n":0,"text":"The operator wants to know the man’s phone number.","example":true,"fixes":[{"wrong":"phone","accept":["card"]}]},{"n":17,"text":"Mr. Brandon is calling from his mobile phone number."},{"n":18,"text":"The operator knows all his phone numbers, because they are connected to the Internet."},{"n":19,"text":"According to his medical records, Mr. Brandon’s blood pressure is too low."},{"n":20,"text":"Last week, Mr. Brandon borrowed a certain book from the local Library."},{"n":21,"text":"Mr. Brandon ordered family-size pizzas, because there are five people in his family."},{"n":22,"text":"The amount he owes doesn’t include the late payment charges on his bank card."},{"n":23,"text":"Mr. Brandon owns a car whose registration number is 7786."},{"n":24,"text":"The restaurant advertised that they would give three cans of soft drink with each order."},{"n":25,"text":"In July, Mr. Brandon had to pay a fine of ₤150 for using dirty language against a postman."}],"grading":{"spelling":"lenient"}}$mtr$::jsonb, $mtr${"file":"k_angol_19maj_fl.mp3","start":1228.32,"end":1795.82,"clip":"hang/k_angol_19maj_fl_H3.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2019-maj-kozep-H3$mtr$, $mtr${"id":"2019-maj-kozep-H3","number":3,"kind":"fix","layout":"stems","examType":"hibás szó javítása hallás után","points":9,"instructions":["In this section, you will hear a bizarre telephone conversation between a customer and a pizza restaurant operator.","Your task will be to find one word in each of the following sentences that is not correct in the context of the recording. First, cross it out, and then write the correct one on the line after the sentence. First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, after a short pause, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_19maj_fl.mp3","start":1228.32,"end":1795.82,"clip":"hang/k_angol_19maj_fl_H3.mp3"},"items":[{"n":0,"text":"The operator wants to know the man’s phone number.","example":true,"fixes":[{"wrong":"phone","accept":["card"]}]},{"n":17,"text":"Mr. Brandon is calling from his mobile phone number.","fixes":[{"wrong":"mobile","accept":["home"]}]},{"n":18,"text":"The operator knows all his phone numbers, because they are connected to the Internet.","fixes":[{"wrong":"internet","accept":["system"]}]},{"n":19,"text":"According to his medical records, Mr. Brandon’s blood pressure is too low.","fixes":[{"wrong":"low","accept":["high"]}]},{"n":20,"text":"Last week, Mr. Brandon borrowed a certain book from the local Library.","fixes":[{"wrong":"local","accept":["National"]}]},{"n":21,"text":"Mr. Brandon ordered family-size pizzas, because there are five people in his family.","fixes":[{"wrong":"five","accept":["seven"]}]},{"n":22,"text":"The amount he owes doesn’t include the late payment charges on his bank card.","fixes":[{"wrong":"card","accept":["loan"]}]},{"n":23,"text":"Mr. Brandon owns a car whose registration number is 7786.","fixes":[{"wrong":"car","accept":["motorcycle","motorbike"]}]},{"n":24,"text":"The restaurant advertised that they would give three cans of soft drink with each order.","fixes":[{"wrong":"cans","accept":["bottles"]}]},{"n":25,"text":"In July, Mr. Brandon had to pay a fine of ₤150 for using dirty language against a postman.","fixes":[{"wrong":"postman","accept":["policeman"]}]}],"grading":{"spelling":"lenient","caseSensitive":false,"note":"(Ha a beírt szó helyes, akkor áthúzás nélkül is elfogadjuk a választ!)"}}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
