insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2020-okt-kozep-H1$mtr$, $mtr$2020-okt-kozep$mtr$, $mtr$listening$mtr$, 1, $mtr$text$mtr$, $mtr$rövid válasz hallás után$mtr$, 8, 8, $mtr${"id":"2020-okt-kozep-H1","number":1,"kind":"text","layout":"stems","examType":"rövid válasz hallás után","points":8,"instructions":["In this section, you will hear about the lucky escape of Mr Christopher McCabe.","Your task will be to give short answers to the questions below using the exact words you hear to continue the sentences we have begun for you.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_20okt_fl.mp3","start":0,"end":677.95,"clip":"hang/k_angol_20okt_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"What does Mr McCabe do for a living? He is a(n) {{gap}}","accept":["butcher"]},{"n":1,"stem":"Where did Mr McCabe go to get some meat? He went into the walk-in {{gap}}"},{"n":2,"stem":"How cold was it inside the place? It was {{gap}}"},{"n":3,"stem":"What was the problem with the safety button? It was {{gap}}"},{"n":4,"stem":"What did he first try doing with the safety button? He tried {{gap}}"},{"n":5,"stem":"What did he not have on him? He didn’t have a(n) {{gap}}"},{"n":6,"stem":"Why couldn’t he use burgers, frankfurters and chickens? Because they didn’t have any {{gap}}"},{"n":7,"stem":"What did the black pudding look like? It looked like a heavy {{gap}}"},{"n":8,"stem":"What did he manage to break around the safety button? He managed to break the {{gap}}"}],"grading":{"spelling":"keywords"}}$mtr$::jsonb, $mtr${"file":"k_angol_20okt_fl.mp3","start":0,"end":677.95,"clip":"hang/k_angol_20okt_fl_H1.mp3"}$mtr$::jsonb)
