insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2020-okt-kozep-H2$mtr$, $mtr$2020-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 9, $mtr${"id":"2020-okt-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear the story of a photograph of Albert Einstein taken by Art Sasse.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to look at the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to make your decision about the answers."],"audio":{"file":"k_angol_20okt_fl.mp3","start":677.95,"end":1193.32,"clip":"hang/k_angol_20okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Einstein preferred doing research work to teaching.","answer":"C"},{"n":9,"stem":"Some university professors criticized Einstein’s strange appearance."},{"n":10,"stem":"On March 14, friends and colleagues celebrated Einstein’s birthday."},{"n":11,"stem":"After the party, Einstein and some of his friends got into a taxi."},{"n":12,"stem":"Sasse wasn’t the first photographer to take a photo of Einstein in the car."},{"n":13,"stem":"Sasse had a great idea and asked Einstein to stick out his tongue."},{"n":14,"stem":"The other photographers also took pictures of Einstein sticking his tongue out."},{"n":15,"stem":"Some people thought that this photograph should not be printed."},{"n":16,"stem":"The chief editor of the newspaper convinced the staff to print the photo."},{"n":17,"stem":"Einstein didn’t want people to see this photograph."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_20okt_fl.mp3","start":677.95,"end":1193.32,"clip":"hang/k_angol_20okt_fl_H2.mp3"}$mtr$::jsonb)
