t":"AS"},{"key":"C","text":"FOR"},{"key":"D","text":"AT"},{"key":"E","text":"BELIEVE"},{"key":"F","text":"COULD"},{"key":"G","text":"CHARMING"},{"key":"H","text":"HAPPENS"},{"key":"I","text":"HOW"},{"key":"K","text":"MUST"},{"key":"L","text":"OWNED"},{"key":"M","text":"TAKES"}],"items":[{"n":0,"example":true,"answer":"C"},{"n":9},{"n":10},{"n":11},{"n":12},{"n":13},{"n":14},{"n":15},{"n":16}],"source":"https://upjoke.com/fluently-jokes"}$mtr$::jsonb, null)
