insert into public.task_keys (task_id, task) values ($mtr$2023-maj-kozep-H1$mtr$, $mtr${"id":"2023-maj-kozep-H1","number":1,"kind":"text","layout":"stems","examType":"mondatkiegészítés hallás után","points":9,"instructions":["In this section, you will hear some interesting information about sugar.","Your task is to complete the sentences with one word or number in each gap, using the exact words you hear.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_23maj_fl.mp3","start":0,"end":581.86,"clip":"hang/k_angol_23maj_fl_H1.mp3"},"items":[{"n":0,"example":true,"stem":"Mary Poppins sings that a(n) {{gap}} of sugar makes the medicine go down.","accept":["spoonful"]},{"n":1,"stem":"It wasn’t Mary Poppins who invented the {{gap}} of taking medicines with sugar.","accept":["trick"]},{"n":2,"stem":"In the past, sugar used to be the main {{gap}} of some medicines.","accept":["ingredient"]},{"n":3,"stem":"Besides kidney problems, Middle Eastern doctors recommended sugar for poor {{gap}}.","accept":["eyesight","eye sight"]},{"n":4,"stem":"In the 11th century, English monks noticed sugar could cure {{gap}} problems.","accept":["stomach"]},{"n":5,"stem":"Besides sugar, {{gap}} was recommended for asthma attacks in the 1700s.","accept":["lemon"]},{"n":6,"stem":"People thought sugar was a powerful medicine because it was {{gap}}.","accept":["rare","expensive"]},{"n":7,"stem":"In India, people started getting sugar from sugar cane about {{gap}} years ago.","accept":["2,500"]},{"n":8,"stem":"A German {{gap}} discovered how to produce sugar from sugar beet.","accept":["chemist"]},{"n":9,"stem":"After Marggraf’s discovery, lots of sugar {{gap}} appeared in Europe.","accept":["factories"]}],"grading":{"spelling":"lenient","caseSensitive":false,"note":"(Csak az alábbi, a szövegben elhangzó szavak fogadhatók el.)"}}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2023-maj-kozep-H2$mtr$, $mtr$2023-maj-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 9, $mtr${"id":"2023-maj-kozep-H2","number":2,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section, you will hear an interview with an archaeologist about a famous archaeological site called Sutton Hoo.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_23maj_fl.mp3","start":581.86,"end":1190.21,"clip":"hang/k_angol_23maj_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Morgan Grant is from the UK.","answer":"A"},{"n":10,"stem":"A mound is a large hole in the ground."},{"n":11,"stem":"Only Edith Pretty saw shadowy figures and a man sitting on a horse."},{"n":12,"stem":"Basil Brown was delighted that Edith Pretty had asked him to start excavating."},{"n":13,"stem":"Basil Brown found a ship which was buried in the 7th century."},{"n":14,"stem":"The wooden parts of the ship were in surprisingly good condition."},{"n":15,"stem":"The custom of burying ships was very common all over Europe at the time."},{"n":16,"stem":"Basil found a small building, a coffin and a lot of treasures in the ship."},{"n":17,"stem":"King Raedwald was a very powerful and highly effective ruler."},{"n":18,"stem":"The importance of Sutton Hoo is that it shows how brave Anglo-Saxons were."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_23maj_fl.mp3","start":581.86,"end":1190.21,"clip":"hang/k_angol_23maj_fl_H2.mp3"}$mtr$::jsonb)
