insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2023-okt-kozep-H2$mtr$, $mtr$2023-okt-kozep$mtr$, $mtr$listening$mtr$, 2, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 9, 9, $mtr${"id":"2023-okt-kozep-H2","number":2,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":9,"instructions":["In this section you will listen to a news report about an outstandingly intelligent young lady.","Your task will be to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you might have to circle one or two letters.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_23okt_fl.mp3","start":590.84,"end":1115.06,"clip":"hang/k_angol_23okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Adhara Pérez Sánchez …","options":[{"key":"A","text":"is eight years old."},{"key":"B","text":"wants to be an astronaut."}],"answer":["A","B"]},{"n":10,"stem":"Adhara …","options":[{"key":"A","text":"hopes to go on to university once she’s older."},{"key":"B","text":"is studying mathematics."}]},{"n":11,"stem":"Adhara has an IQ …","options":[{"key":"A","text":"of 162."},{"key":"B","text":"that is exactly as high as Albert Einstein’s was."}]},{"n":12,"stem":"In Tijuana, Mexico, she gave a presentation …","options":[{"key":"A","text":"on black holes."},{"key":"B","text":"to other children."}]},{"n":13,"stem":"Karen Alonso was …","options":[{"key":"A","text":"surprised at Adhara’s great knowledge."},{"key":"B","text":"one of Adhara’s teachers."}]},{"n":14,"stem":"Adhara …","options":[{"key":"A","text":"was invited to study astronomy at the University of Arizona."},{"key":"B","text":"speaks absolutely perfect English."}]},{"n":15,"stem":"Adhara …","options":[{"key":"A","text":"was diagnosed with autism when she was younger."},{"key":"B","text":"is working on a special gadget to help autistic children."}]},{"n":16,"stem":"The wrist-band Adhara is making …","options":[{"key":"A","text":"can read the kids’ emotional state."},{"key":"B","text":"will be worn by both the kids and their parents."}]},{"n":17,"stem":"Adhara …","options":[{"key":"A","text":"is going to publish a book."},{"key":"B","text":"hopes to get a job with NASA."}]},{"n":18,"stem":"Adhara’s advice to other people is that they should …","options":[{"key":"A","text":"never give up their dreams."},{"key":"B","text":"study as hard as possible."}]}]}$mtr$::jsonb, $mtr${"file":"k_angol_23okt_fl.mp3","start":590.84,"end":1115.06,"clip":"hang/k_angol_23okt_fl_H2.mp3"}$mtr$::jsonb)
