insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2023-okt-kozep-H3$mtr$, $mtr$2023-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 7, 10, $mtr${"id":"2023-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":7,"instructions":["In this section you will hear some interesting background information about Olympic medals.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right."],"audio":{"file":"k_angol_23okt_fl.mp3","start":1115.06,"end":1795.82,"clip":"hang/k_angol_23okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Even if Olympic gold medals were made from solid gold, they would not be very valuable.","answer":"B"},{"n":19,"stem":"At the 1912 Olympics, winners were given a medal made from pure gold."},{"n":20,"stem":"The gold medal is the thickest of the three medals."},{"n":21,"stem":"The silver medal is the only one that is made from one single metal."},{"n":22,"stem":"The value of the metal the bronze medal is made from is around $5 at the moment."},{"n":23,"stem":"Olympic medals often come up for sale at auctions."},{"n":24,"stem":"One of Jesse Owens’ gold medals is the most valuable medal in Olympic history."},{"n":25,"stem":"No gold medals were awarded at the first modern Olympic Games in 1896."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_23okt_fl.mp3","start":1115.06,"end":1795.82,"clip":"hang/k_angol_23okt_fl_H3.mp3"}$mtr$::jsonb)
