insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2024-maj-emelt-L1$mtr$, $mtr$2024-maj-emelt$mtr$, $mtr$language$mtr$, 1, $mtr$text$mtr$, $mtr$szóképzés (zárójeles szó)$mtr$, 9, 5, $mtr${"id":"2024-maj-emelt-L1","number":1,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"grading":{"spelling":"strict"},"instructions":["You are going to read an article about the world’s smallest fine-dining restaurant. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (1-9).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"JUST FOR TWO","body":["Solo Per Due – “Just for Two” in Italian – is no {{0}} restaurant, and not just because of its tiny size. It’s an extravagant place where an {{1}} meal for two costs over $500.","Champagne, top wines and floral decorations cost extra. The {{2}} is amazing. The restaurant is {{3}} by an exotic garden with different species of palm trees from across the world. The {{4}} have a view of an ancient Roman villa.","The tiny dining room is part of a rural 20th-century stone mansion near a village north of Rome. The {{5}} claim it is the smallest fine-dining establishment not only in Italy but in the world, too. Ideal for romantic meals, it’s open year-round for lunch and dinner but has no menu. The food served is tailor-made for the tastes and wishes of clients. Discreetness, {{6}} and secrecy rule. It is the perfect hiding place – except for the fact that it’s {{7}} advertised and reviewed.","There are strict rules. Bookings must be made by phone and confirmed 10 days in advance. Details of the customized meal are defined at the time of {{8}}. Visitors can’t pop in as they please to take a look inside before making a {{9}}. A meal can’t be canceled last-minute and guests are required to arrive at a specific time."],"items":[{"n":0,"example":true,"prompt":"order","accept":["ordinary"]},{"n":1,"prompt":"exclude"},{"n":2,"prompt":"local"},{"n":3,"prompt":"surround"},{"n":4,"prompt":"dine"},{"n":5,"prompt":"own"},{"n":6,"prompt":"private"},{"n":7,"prompt":"wide"},{"n":8,"prompt":"confirm"},{"n":9,"prompt":"reserve"}]}$mtr$::jsonb, null)
insert into public.task_keys (task_id, task) values ($mtr$2024-maj-emelt-L1$mtr$, $mtr${"id":"2024-maj-emelt-L1","number":1,"kind":"text","layout":"inline","examType":"szóképzés (zárójeles szó)","points":9,"grading":{"spelling":"strict","maxWords":1},"instructions":["You are going to read an article about the world’s smallest fine-dining restaurant. Some words are missing from the text.","Use the words in brackets to form the words that fit in the gaps (1-9).","There might be cases when you do not have to change the word in brackets.","Use only one word for each gap."],"title":"JUST FOR TWO","body":["Solo Per Due – “Just for Two” in Italian – is no {{0}} restaurant, and not just because of its tiny size. It’s an extravagant place where an {{1}} meal for two costs over $500.","Champagne, top wines and floral decorations cost extra. The {{2}} is amazing. The restaurant is {{3}} by an exotic garden with different species of palm trees from across the world. The {{4}} have a view of an ancient Roman villa.","The tiny dining room is part of a rural 20th-century stone mansion near a village north of Rome. The {{5}} claim it is the smallest fine-dining establishment not only in Italy but in the world, too. Ideal for romantic meals, it’s open year-round for lunch and dinner but has no menu. The food served is tailor-made for the tastes and wishes of clients. Discreetness, {{6}} and secrecy rule. It is the perfect hiding place – except for the fact that it’s {{7}} advertised and reviewed.","There are strict rules. Bookings must be made by phone and confirmed 10 days in advance. Details of the customized meal are defined at the time of {{8}}. Visitors can’t pop in as they please to take a look inside before making a {{9}}. A meal can’t be canceled last-minute and guests are required to arrive at a specific time."],"items":[{"n":0,"example":true,"prompt":"order","accept":["ordinary"]},{"n":1,"prompt":"exclude","accept":["exclusive"]},{"n":2,"prompt":"local","accept":["location","locality","locale"]},{"n":3,"prompt":"surround","accept":["surrounded"]},{"n":4,"prompt":"dine","accept":["diners"]},{"n":5,"prompt":"own","accept":["owners"]},{"n":6,"prompt":"private","accept":["privacy","privateness"]},{"n":7,"prompt":"wide","accept":["widely"]},{"n":8,"prompt":"confirm","accept":["confirmation","confirming"]},{"n":9,"prompt":"reserve","accept":["reservation"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2024-maj-emelt-L2$mtr$, $mtr$2024-maj-emelt$mtr$, $mtr$language$mtr$, 2, $mtr$choice$mtr$, $mtr$feleletválasztós szövegkiegészítés (A-D)$mtr$, 8, 6, $mtr${"id":"2024-maj-emelt-L2","number":2,"kind":"choice","layout":"inline","examType":"feleletválasztós szövegkiegészítés (A-D)","points":8,"instructions":["You are going to read an article about a joyful summer job. Some words are missing from the text.","Choose the most appropriate answer from the options (A-D) for each gap (10-17) in the text."],"title":"PET-SITTING AROUND EUROPE","body":["An American student has revealed {{0}} she managed to enjoy a long summer holiday in various destinations across Europe – by looking after other people's pets. Soriah Abraham, 19, saved £3,000 living rent-free by volunteering to pet sit for people going on holiday – and says she {{10}} spending just £400 in two months.","The student, {{11}} originally from Salem, Oregon but moved to London in October 2022 {{12}} study fashion design, got the idea for pet-sitting travel after seeing others doing it. {{13}} joining a specialized website, she started doing home sits around London to build up her reviews – meaning she would be able to easily secure pet-sitting jobs abroad over her summer break.","When she finished in June, she celebrated ending her first year of university with a two-month adventure in Germany, Switzerland and Amsterdam. Not only {{14}} three countries in one trip, she also only spent just £400 during the trip – on food, travel and the occasional hotel, estimating it {{15}} her around £3,400 without her pet-sitting jobs.","From June 2023 she started using the app to hop around Europe – without spending very much. She said: 'I went to Stuttgart, Germany, first and got to bike around the city.' She looked after two cats there, Tequila and Vodka, before coming back to London to take {{16}} of a dog, Mimi, and then heading to Bern, Switzerland, to look after another feline, Claire. Soriah said: 'I could eat {{17}} I found in the fridge and use their bikes. It was gorgeous, and the cat was super independent.'"],"items":[{"n":0,"example":true,"answer":"C","options":[{"key":"A","text":"as"},{"key":"B","text":"though"},{"key":"C","text":"how"},{"key":"D","text":"most"}]},{"n":10,"options":[{"key":"A","text":"managed"},{"key":"B","text":"could afford"},{"key":"C","text":"ended up"},{"key":"D","text":"continued"}]},{"n":11,"options":[{"key":"A","text":"came"},{"key":"B","text":"that's"},{"key":"C","text":"whose"},{"key":"D","text":"who's"}]},{"n":12,"options":[{"key":"A","text":"in order that"},{"key":"B","text":"to"},{"key":"C","text":"so that"},{"key":"D","text":"for"}]},{"n":13,"options":[{"key":"A","text":"After"},{"key":"B","text":"While"},{"key":"C","text":"Despite"},{"key":"D","text":"As for"}]},{"n":14,"options":[{"key":"A","text":"she did experience"},{"key":"B","text":"experienced she"},{"key":"C","text":"she experienced"},{"key":"D","text":"did she experience"}]},{"n":15,"options":[{"key":"A","text":"would cost"},{"key":"B","text":"would have cost"},{"key":"C","text":"would not cost"},{"key":"D","text":"had cost"}]},{"n":16,"options":[{"key":"A","text":"on"},{"key":"B","text":"advantage"},{"key":"C","text":"care"},{"key":"D","text":"account"}]},{"n":17,"options":[{"key":"A","text":"which"},{"key":"B","text":"what"},{"key":"C","text":"that"},{"key":"D","text":"if"}]}]}$mtr$::jsonb, null)
