insert into public.task_keys (task_id, task) values ($mtr$2024-maj-kozep-H2$mtr$, $mtr${"id":"2024-maj-kozep-H2","number":2,"kind":"text","layout":"stems","examType":"mondatkiegészítés hallás után (egy szó)","points":9,"grading":{"spelling":"lenient","maxWords":1,"caseSensitive":false},"audio":{"file":"k_angol_24maj_fl.mp3","start":721.1,"end":1182.3,"clip":"hang/k_angol_24maj_fl_H2.mp3"},"instructions":["In this section, you will hear an interesting story about an anthropologist.","Your task is to complete the sentences with one word in each gap, using the exact words you hear.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"items":[{"n":0,"example":true,"stem":"Margaret Mead was popular because she made her work {{gap}} for most people.","accept":["understandable"]},{"n":8,"stem":"She had a strong influence on anthropology with her non-traditional {{gap}} methods.","accept":["research"]},{"n":9,"stem":"Margaret Mead frequently appeared in the mass media as a(n) {{gap}} and speaker during the 1960s and the 1970s.","accept":["author"]},{"n":10,"stem":"She was a professor of {{gap}} and Anthropology at Columbia University.","accept":["sociology"]},{"n":11,"stem":"A university student asked her what she considered to be the first sign of civilization in a(n) {{gap}}.","accept":["culture"]},{"n":12,"stem":"The student thought that Mead would talk about some kind of object or {{gap}}.","accept":["tool"]},{"n":13,"stem":"What Margaret Mead considered to be the first sign of civilization, was actually a(n) {{gap}} bone that had been broken and then healed.","accept":["human"]},{"n":14,"stem":"She said that if an animal broke a leg, it meant that it didn’t have any {{gap}} to survive.","accept":["chance"]},{"n":15,"stem":"In her opinion, a broken leg that has healed proves that there was someone who took care of the injured person until they {{gap}}.","accept":["recovered","healed"]},{"n":16,"stem":"According to Mead, we are at our best when we {{gap}} others.","accept":["serve","help"]}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2024-maj-kozep-H3$mtr$, $mtr$2024-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 10, $mtr${"id":"2024-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"audio":{"file":"k_angol_24maj_fl.mp3","start":1182.3,"end":1795.6,"clip":"hang/k_angol_24maj_fl_H3.mp3"},"instructions":["In this section, you will hear an interview with a Guinness World Record holder.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to mark your answers."],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}],"items":[{"n":0,"example":true,"stem":"Donald Gorske has been a Guinness World Record holder for years.","answer":"B"},{"n":17,"stem":"Donald has always wanted to be a Guinness World Record holder."},{"n":18,"stem":"There was a time when he ate up to thirty Big Macs a day."},{"n":19,"stem":"Donald ate his first Big Mac on the day he got his first car."},{"n":20,"stem":"He still has the receipts for all the Big Macs he has ever eaten."},{"n":21,"stem":"When Donald was still active, he used to work near a fast-food restaurant."},{"n":22,"stem":"Now that he is retired, he only eats two Big Macs a week."},{"n":23,"stem":"He drives to the restaurant just once a week to buy his weekly supply of Big Macs."},{"n":24,"stem":"Donald’s cholesterol level is high."},{"n":25,"stem":"He says that he will continue having Big Macs until the end of his life."}]}$mtr$::jsonb, $mtr${"file":"k_angol_24maj_fl.mp3","start":1182.3,"end":1795.6,"clip":"hang/k_angol_24maj_fl_H3.mp3"}$mtr$::jsonb)
insert into public.task_keys (task_id, task) values ($mtr$2024-maj-kozep-H3$mtr$, $mtr${"id":"2024-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"audio":{"file":"k_angol_24maj_fl.mp3","start":1182.3,"end":1795.6,"clip":"hang/k_angol_24maj_fl_H3.mp3"},"instructions":["In this section, you will hear an interview with a Guinness World Record holder.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to mark your answers."],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}],"items":[{"n":0,"example":true,"stem":"Donald Gorske has been a Guinness World Record holder for years.","answer":"B"},{"n":17,"stem":"Donald has always wanted to be a Guinness World Record holder.","answer":"C"},{"n":18,"stem":"There was a time when he ate up to thirty Big Macs a day.","answer":"B"},{"n":19,"stem":"Donald ate his first Big Mac on the day he got his first car.","answer":"A"},{"n":20,"stem":"He still has the receipts for all the Big Macs he has ever eaten.","answer":"A"},{"n":21,"stem":"When Donald was still active, he used to work near a fast-food restaurant.","answer":"C"},{"n":22,"stem":"Now that he is retired, he only eats two Big Macs a week.","answer":"B"},{"n":23,"stem":"He drives to the restaurant just once a week to buy his weekly supply of Big Macs.","answer":"A"},{"n":24,"stem":"Donald’s cholesterol level is high.","answer":"B"},{"n":25,"stem":"He says that he will continue having Big Macs until the end of his life.","answer":"A"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
