insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2024-okt-emelt-H2$mtr$, $mtr$2024-okt-emelt$mtr$, $mtr$listening$mtr$, 2, $mtr$multi$mtr$, $mtr$kettős választás (A, B vagy mindkettő)$mtr$, 7, 10, $mtr${"id":"2024-okt-emelt-H2","number":2,"kind":"multi","layout":"stems","examType":"kettős választás (A, B vagy mindkettő)","points":7,"instructions":["In this section you will listen to an interview with one of the teachers of Brazilian footballer, Roberto Firmino.","Your task will be to circle the letter(s) of the correct answer(s) in the boxes on the right. Please note that in this task both answers may be correct. However, there is always at least one correct answer. This means you might have to circle one or two letters.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_24okt_fl.mp3","start":585.86,"end":1192.41,"clip":"hang/e_angol_24okt_fl_H2.mp3"},"items":[{"n":0,"example":true,"stem":"Firmino played for …","options":[{"key":"A","text":"Hoffenheim for four years."},{"key":"B","text":"Liverpool for eight years."}],"answer":["A","B"]},{"n":10,"stem":"Firmino’s home …","options":[{"key":"A","text":"was in a wealthy neighbourhood."},{"key":"B","text":"is now a hotdog place."}]},{"n":11,"stem":"The function of the metal spikes was to keep …","options":[{"key":"A","text":"away criminals."},{"key":"B","text":"Firmino inside."}]},{"n":12,"stem":"Firmino’s father …","options":[{"key":"A","text":"had a small shop."},{"key":"B","text":"got some help from his son in his business."}]},{"n":13,"stem":"Firmino’s mother …","options":[{"key":"A","text":"was afraid that her son might become a criminal."},{"key":"B","text":"encouraged her son to play football as often as possible."}]},{"n":14,"stem":"Firmino told his teacher that …","options":[{"key":"A","text":"his family hadn’t had electricity at the weekend."},{"key":"B","text":"he was heartbroken that the family hadn’t had any food in the fridge."}]},{"n":15,"stem":"At school …","options":[{"key":"A","text":"Firmino suddenly became very talkative when he wanted to play with a ball."},{"key":"B","text":"Pedro sometimes refused to give Firmino a ball."}]},{"n":16,"stem":"As a well-paid star footballer, Firmino …","options":[{"key":"A","text":"settled the medical bills of a family."},{"key":"B","text":"regularly donates some money to a hospital"}]}]}$mtr$::jsonb, $mtr${"file":"e_angol_24okt_fl.mp3","start":585.86,"end":1192.41,"clip":"hang/e_angol_24okt_fl_H2.mp3"}$mtr$::jsonb)
