insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2024-okt-kozep-H3$mtr$, $mtr$2024-okt-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 10, $mtr${"id":"2024-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear about two Canadian lottery winners who have given most of their winnings away.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_24okt_fl.mp3","start":1223.01,"end":1795.74,"clip":"hang/k_angol_24okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"The couple have given away all of the 11 million dollars they won.","answer":"B"},{"n":17,"stem":"The Larges have been living in Lower Truro, Nova Scotia all their lives."},{"n":18,"stem":"They gave the money away because they didn’t need more than what they already had."},{"n":19,"stem":"By a \"rainy day\" Mr. Large means an extremely unfortunate event in their life."},{"n":20,"stem":"Their children fully supported them in their decision about the money."},{"n":21,"stem":"They asked the members of their family to deliver the money to the chosen charities."},{"n":22,"stem":"Mrs. Large believes that money can actually bring happiness."},{"n":23,"stem":"Mrs. Large considers herself lucky because she doesn't feel unwell."},{"n":24,"stem":"The couple became national celebrities immediately after they’d won the jackpot."},{"n":25,"stem":"The Larges consider themselves very ordinary people."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"k_angol_24okt_fl.mp3","start":1223.01,"end":1795.74,"clip":"hang/k_angol_24okt_fl_H3.mp3"}$mtr$::jsonb)
