insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2026-maj-kozep-H3$mtr$, $mtr$2026-maj-kozep$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 9, 10, $mtr${"id":"2026-maj-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":9,"instructions":["In this section you will hear about Fatou, the world’s oldest gorilla in captivity.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_26maj_fl.mp3","start":1138.7,"end":1795.17,"clip":"hang/k_angol_26maj_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"In the wild, gorillas typically live for 40-50 years.","answer":"A"},{"n":17,"stem":"When she died, Colo was older than Fatou is now."},{"n":18,"stem":"The French sailor got more money for Fatou than he owed to the pub."},{"n":19,"stem":"A French animal trader sold Fatou to the Berlin Zoo."},{"n":20,"stem":"Fatou was definitely born in 1959."},{"n":21,"stem":"Only very few people can attend Fatou’s birthday celebrations."},{"n":22,"stem":"Normally, Fatou does not get a lot of fruit to eat."},{"n":23,"stem":"Despite her age, Fatou still has a few teeth."},{"n":24,"stem":"Fatou usually plays with her neighbours in the morning."},{"n":25,"stem":"Fatou has many children."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SA