insert into public.tasks (id, exam_id, section, number, kind, exam_type, points, position, content, audio) values ($mtr$2026-okt-emelt-H3$mtr$, $mtr$2026-okt-emelt$mtr$, $mtr$listening$mtr$, 3, $mtr$choice$mtr$, $mtr$igaz / hamis / a szöveg nem mondja (A/B/C)$mtr$, 10, 11, $mtr${"id":"2026-okt-emelt-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":10,"instructions":["In this section you will hear an interview with Steven Spielberg, the director of Jurassic Park and other big movie blockbusters.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"e_angol_26okt_fl.mp3","start":1192.01,"end":1809.12,"clip":"hang/e_angol_26okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Steven Spielberg is a very private man and rarely does interviews.","answer":"C"},{"n":16,"stem":"Steven Spielberg was sometimes physically bullied at school."},{"n":17,"stem":"Spielberg discovered that in movies imagination is extremely important."},{"n":18,"stem":"Spielberg shot his first film when he was 17 years old."},{"n":19,"stem":"During the shooting of Jurassic Park, people thought that the theme was too childish."},{"n":20,"stem":"The producer of the film was worried because of the new technology Spielberg used."},{"n":21,"stem":"According to Steven, the great thing about the film is that it made the impossible feel real."},{"n":22,"stem":"Spielberg's mother died just before the shooting of the film started."},{"n":23,"stem":"The loud noises in the movie were generated by a computer."},{"n":24,"stem":"Spielberg has long since forgotten that he stuttered when he was young."},{"n":25,"stem":"The main message of his life is that we should never let our weaknesses limit us."}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb, $mtr${"file":"e_angol_26okt_fl.mp3","start":1192.01,"end":1809.12,"clip":"hang/e_angol_26okt_fl_H3.mp3"}$mtr$::jsonb)
