insert into public.task_keys (task_id, task) values ($mtr$2026-okt-kozep-H3$mtr$, $mtr${"id":"2026-okt-kozep-H3","number":3,"kind":"choice","layout":"stems","examType":"igaz / hamis / a szöveg nem mondja (A/B/C)","points":8,"instructions":["In this section you will hear some information about a famous photograph called Cotton Mill Girl by Lewis Hine.","Your task will be to decide whether the following statements are true, false or we do not know because the text does not say, and write the appropriate letter in the boxes on the right. Write A if the statement is true, write B if the statement is false, and write C if the text does not say.","First, you will have some time to study the task, and then we will play the whole recording in one piece.","Then, you will hear the recording again, but this time we will play the text in shorter sections to give you enough time to write down your answers."],"audio":{"file":"k_angol_26okt_fl.mp3","start":1115.08,"end":1795.22,"clip":"hang/k_angol_26okt_fl_H3.mp3"},"items":[{"n":0,"example":true,"stem":"Very few children had dangerous jobs in the US in the early 1900s.","answer":"B"},{"n":18,"stem":"Working in a mine was the worst job for children.","answer":"C"},{"n":19,"stem":"All the parents protested against child labor.","answer":"B"},{"n":20,"stem":"The National Child Labor Committee was formed in the middle of the 19th century.","answer":"B"},{"n":21,"stem":"Lewis Hine worked for the National Child Labor Committee for twenty years.","answer":"A"},{"n":22,"stem":"Besides taking photos, Hine was also a Bible salesman.","answer":"B"},{"n":23,"stem":"Sadie Pfeifer’s job was extremely dangerous.","answer":"C"},{"n":24,"stem":"In the picture, Sadie Pfeifer has just started her night shift.","answer":"B"},{"n":25,"stem":"Since 1938, you have been allowed to work in the US if you are 16 or older.","answer":"A"}],"options":[{"key":"A","text":"TRUE"},{"key":"B","text":"FALSE"},{"key":"C","text":"THE TEXT DOES NOT SAY"}]}$mtr$::jsonb) on conflict (task_id) do update set task = excluded.task;
