insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2005-nov-emelt-R2$mtr$, $mtr$[{"forms":["alternative medicine","alternative medicines"],"lemma":"alternative medicine","pos":"noun","en":"ways of treating illness that are not part of normal science-based medicine","hu":"alternatív gyógyászat"},{"forms":["alternative"],"lemma":"alternative","pos":"adjective","en":"different from the usual, accepted kind","hu":"alternatív, nem hagyományos"},{"forms":["physicist"],"lemma":"physicist","pos":"noun","en":"a scientist who studies physics","hu":"fizikus","tip":"Hamis barát: a physicist fizikus, nem orvos (orvos: physician)."},{"forms":["perspective"],"lemma":"perspective","pos":"noun","en":"a way of looking at something","hu":"nézőpont"},{"forms":["suffering from","suffered from"],"lemma":"suffer from","pos":"phrasal verb","en":"to have an illness or a problem","hu":"szenved valamiben (betegségben)"},{"forms":["shingles"],"lemma":"shingles","pos":"noun","en":"a painful illness that causes red spots on the skin","hu":"övsömör"},{"forms":["gp"],"lemma":"GP","pos":"noun","en":"a family doctor (general practitioner)","hu":"háziorvos"},{"forms":["painkillers"],"lemma":"painkiller","pos":"noun","en":"a medicine that stops pain","hu":"fájdalomcsillapító"},{"forms":["acupuncture"],"lemma":"acupuncture","pos":"noun","en":"a Chinese treatment with thin needles put into the skin","hu":"akupunktúra"},{"forms":["condition"],"lemma":"condition","pos":"noun","en":"the state of your health","hu":"állapot"},{"forms":["treatments"],"lemma":"treatment","pos":"noun","en":"something done to make an ill person well","hu":"kezelés"},{"forms":["cure"],"lemma":"cure","pos":"noun","en":"becoming healthy again after an illness","hu":"gyógyulás, gyógymód"},{"forms":["chronic"],"lemma":"chronic","pos":"adjective","en":"lasting for a long time","hu":"krónikus, idült"},{"forms":["catarrh"],"lemma":"catarrh","pos":"noun","en":"too much thick liquid in the nose and throat","hu"