insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2006-febr-kozep-R3$mtr$, $mtr$[{"forms":["fooled"],"lemma":"fool","pos":"verb","en":"to make someone believe something that is not true","hu":"becsap, rászed"},{"forms":["fair"],"lemma":"fair","pos":"noun","en":"a large event where people buy and sell things","hu":"vásár, kiállítás","tip":"Melléknévként (fair) azt jelenti: igazságos."},{"forms":["amazing"],"lemma":"amazing","pos":"adjective","en":"very surprising and exciting","hu":"elképesztő, csodálatos"},{"forms":["fossil"],"lemma":"fossil","pos":"noun","en":"the remains of a very old animal or plant that have become hard like rock","hu":"kövület, ősmaradvány"},{"forms":["came on to the market"],"lemma":"come on to the market","pos":"phrase","en":"to become available for people to buy","hu":"piacra került, eladásra kínálták"},{"forms":["priced at"],"lemma":"be priced at","pos":"phrase","en":"to have a certain price","hu":"az ára ... volt"},{"forms":["invited"],"lemma":"invite","pos":"verb","en":"to ask someone to come somewhere","hu":"meghív"},{"forms":["tail"],"lemma":"tail","pos":"noun","en":"the long part at the back of an animal's body","hu":"farok"},{"forms":["sought-after"],"lemma":"sought-after","pos":"adjective","en":"wanted by many people","hu":"keresett, áhított"},{"forms":["palaeontology"],"lemma":"palaeontology","pos":"noun","en":"the science of studying fossils and very old forms of life","hu":"őslénytan, paleontológia"},{"forms":["missing link"],"lemma":"missing link","pos":"noun","en":"an animal that shows how one kind of animal changed into another","hu":"hiányzó láncszem"},{"forms":["proved"],"lemma":"prove","pos":"verb","en":"to show that something is true","hu":"bebizonyít"},{"forms":["evolved into"],"lemma":"evolve into","pos":"phrasal verb","en":"to slowly change over a very long time and become something else","hu":"kifejlődik valamivé"},{"forms":["became involved"],"lemma":"become involved","pos":"phrase","en":"t