insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2006-maj-emelt-R1$mtr$, $mtr$[{"forms":["stress-busters"],"lemma":"stress-buster","pos":"noun","en":"something that helps you feel less worried and tense","hu":"stresszoldó, stresszűző"},{"forms":["dust off"],"lemma":"dust off","pos":"phrasal verb","en":"to start using something again that you have not used for a long time","hu":"leporol, újra elővesz"},{"forms":["records"],"lemma":"record","pos":"noun","en":"a round flat disc with music on it","hu":"hanglemez, bakelitlemez"},{"forms":["study"],"lemma":"study","pos":"noun","en":"a piece of scientific research","hu":"tanulmány, kutatás"},{"forms":["revealed"],"lemma":"reveal","pos":"verb","en":"to show or make known a fact","hu":"kimutat, felfed"},{"forms":["classical"],"lemma":"classical","pos":"adjective","en":"connected with serious, traditional music, e.g. by Mozart or Bach","hu":"komolyzenei, klasszikus"},{"forms":["collection"],"lemma":"collection","pos":"noun","en":"a group of things that someone has kept together","hu":"gyűjtemény"},{"forms":["beneficial"],"lemma":"beneficial","pos":"adjective","en":"good or helpful","hu":"hasznos, jótékony hatású"},{"forms":["apparently"],"lemma":"apparently","pos":"adverb","en":"according to what people say or what research shows","hu":"úgy tűnik, állítólag"},{"forms":["sedate"],"lemma":"sedate","pos":"adjective","en":"slow, quiet and calm","hu":"nyugodt, lassú tempójú"},{"forms":["induce"],"lemma":"induce","pos":"verb","en":"to cause a feeling or a state","hu":"előidéz, kivált"},{"forms":["a state of calm"],"lemma":"a state of calm","pos":"phrase","en":"a situation in which you feel peaceful and relaxed","hu":"nyugalmi állapot, nyugalom"},{"forms":["breathing"],"lemma":"breathing","pos":"noun","en":"taking air into your body and letting it out","hu":"légzés"},{"forms":["heart rate","heart rates"],"lemma":"heart rate","pos":"noun","en":"the number of times your heart beats in a minute","hu":"pulzus, szívverés"},{"forms":["a phone call away"],"lemma":"a phone call away","pos":"phrase","en":"very easy to reach; you only need to call them","hu":"csak egy telefonnyira (vannak)"},{"forms":["stress relief"],"lemma":"stress relief","pos":"noun","en":"something that makes you feel less stressed","hu":"stresszoldás, stresszoldó"},{"forms":["as the old saying goes"],"lemma":"as the saying goes","pos":"phrase","en":"as people often say in a well-known sentence","hu":"ahogy a régi mondás tartja"},{"forms":["positive"],"lemma":"positive","pos":"adjective","en":"hopeful and thinking about the good side of things","hu":"pozitív (gondolkodású), derűlátó"},{"forms":["rather than"],"lemma":"rather than","pos":"phrase","en":"and not; instead of","hu":"nem pedig, inkább mint"},{"forms":["lift your mood"],"lemma":"lift someone's mood","pos":"phrase","en":"to make you feel happier","hu":"jobb kedvre derít, feldob"},{"forms":["laughter"],"lemma":"laughter","pos":"noun","en":"the act or sound of laughing","hu":"nevetés"},{"forms":["endorphins"],"lemma":"endorphin","pos":"noun","en":"a chemical in the brain that makes you feel good","hu":"endorfin (boldogsághormon)"},{"forms":["chemicals"],"lemma":"chemical","pos":"noun","en":"a substance made by a chemical process or in the body","hu":"vegyi anyag, vegyület"},{"forms":["ease"],"lemma":"ease","pos":"verb","en":"to make pain or a problem less serious","hu":"enyhít, csillapít"},{"forms":["euphoria"],"lemma":"euphoria","pos":"noun","en":"a feeling of very great happiness","hu":"eufória, mámoros boldogság"},{"forms":["cope with"],"lemma":"cope with","pos":"phrasal verb","en":"to deal with a difficult situation successfully","hu":"megbirkózik valamivel"},{"forms":["physical"],"lemma":"physical","pos":"adjective","en":"connected with your body, not your mind","hu":"testi, fizikai"},{"forms":["chronic"],"lemma":"chronic","pos":"adjective","en":"lasting for a long time and difficult to cure","hu":"krónikus, tartós"},{"forms":["puppy love"],"lemma":"puppy love","pos":"idiom","en":"the first romantic love of a young person; here a joke, because puppy = a young dog","hu":"kamaszszerelem (itt szójáték: puppy = kiskutya)"},{"forms":["researchers"],"lemma":"researcher","pos":"noun","en":"a person who studies a subject to discover new facts","hu":"kutató"},{"forms":["effective at"],"lemma":"effective at","pos":"phrase","en":"working well and giving the result you want","hu":"hatékony valamiben"},{"forms":["reducing"],"lemma":"reduce","pos":"verb","en":"to make something smaller or less","hu":"csökkent"},{"forms":["married couples"],"lemma":"married couple","pos":"noun","en":"a husband and wife","hu":"házaspár"},{"forms":["half of whom"],"lemma":"half of whom","pos":"phrase","en":"and half of these people","hu":"akiknek a fele"},{"forms":["resting heart rates"],"lemma":"resting heart rate","pos":"noun","en":"how fast your heart beats when you are sitting still","hu":"nyugalmi pulzus"},{"forms":["blood pressure"],"lemma":"blood pressure","pos":"noun","en":"the force with which blood moves through your body","hu":"vérnyomás"},{"forms":["reacted"],"lemma":"react","pos":"verb","en":"to behave or change because of something that happens","hu":"reagál"},{"forms":["were set"],"lemma":"set (a task)","pos":"verb","en":"to give someone a piece of work to do","hu":"(feladatot) kaptak","tip":"set someone a task = feladatot ad valakinek; rendhagyó: set – set – set."},{"forms":["returned to normal"],"lemma":"return to normal","pos":"phrase","en":"to become as it usually is again","hu":"visszaállt a rendes (szintre)"},{"forms":["levels"],"lemma":"level","pos":"noun","en":"the amount or size of something that can be measured","hu":"szint"},{"forms":["bathtime"],"lemma":"bathtime","pos":"noun","en":"the time when you have a bath","hu":"fürdés (ideje)"},{"forms":["relaxes"],"lemma":"relax","pos":"verb","en":"to make your body less tight and tense","hu":"ellazít"},{"forms":["muscles"],"lemma":"muscle","pos":"noun","en":"a part of the body that helps you move","hu":"izom"},{"forms":["aches and pains"],"lemma":"aches and pains","pos":"phrase","en":"small pains in different parts of the body","hu":"fájdalmak, sajgás"},{"forms":["raising"],"lemma":"raise","pos":"verb","en":"to make something higher","hu":"emel, növel"},{"forms":["temperature"],"lemma":"temperature","pos":"noun","en":"how hot or cold something is","hu":"hőmérséklet"},{"forms":["production"],"lemma":"production","pos":"noun","en":"the process of making something","hu":"termelés, termelődés"},{"forms":["white blood cells"],"lemma":"white blood cell","pos":"noun","en":"a cell in the blood that fights illness","hu":"fehérvérsejt"},{"forms":["strengthens"],"lemma":"strengthen","pos":"verb","en":"to make something stronger","hu":"erősít"},{"forms":["immune system"],"lemma":"immune system","pos":"noun","en":"the system in your body that protects you from illness","hu":"immunrendszer"},{"forms":["suffer"],"lemma":"suffer","pos":"verb","en":"to become worse or weaker","hu":"károsodik, megsínyli"},{"forms":["encourages"],"lemma":"encourage","pos":"verb","en":"to make something more likely to happen","hu":"elősegít, serkent"},{"forms":["sweating"],"lemma":"sweat","pos":"verb","en":"when water comes out of your skin because you are hot","hu":"izzadás"},{"forms":["remove"],"lemma":"remove","pos":"verb","en":"to take something away","hu":"eltávolít"},{"forms":["toxins"],"lemma":"toxin","pos":"noun","en":"a poisonous substance","hu":"méreganyag"},{"forms":["mood lighting"],"lemma":"mood lighting","pos":"noun","en":"soft light that creates a nice, relaxing feeling","hu":"hangulatvilágítás"},{"forms":["lit"],"lemma":"light","pos":"verb","en":"to give light to a place","hu":"megvilágít","tip":"Rendhagyó ige: light – lit – lit."},{"forms":["comfort"],"lemma":"comfort","pos":"noun","en":"a pleasant feeling of being relaxed","hu":"kényelem, otthonosság"},{"forms":["intimacy"],"lemma":"intimacy","pos":"noun","en":"a warm, close and private feeling","hu":"meghittség, bensőségesség"},{"forms":["dimmers"],"lemma":"dimmer","pos":"noun","en":"a switch that makes a light brighter or less bright","hu":"fényerő-szabályzó"},{"forms":["environment"],"lemma":"environment","pos":"noun","en":"the place and conditions around you","hu":"környezet, légkör"},{"forms":["harsh"],"lemma":"harsh","pos":"adjective","en":"too strong and unpleasant","hu":"bántó, éles (fény)"},{"forms":["overhead lighting"],"lemma":"overhead lighting","pos":"noun","en":"lights on the ceiling","hu":"mennyezeti világítás"},{"forms":["indulge yourself"],"lemma":"indulge yourself","pos":"phrase","en":"to let yourself have something nice","hu":"kényezteti magát, megengedi magának"},{"forms":["candlelight"],"lemma":"candlelight","pos":"noun","en":"the light from a candle","hu":"gyertyafény"},{"forms":["tranquil"],"lemma":"tranquil","pos":"adjective","en":"calm, quiet and peaceful","hu":"nyugodt, békés"},{"forms":["essential"],"lemma":"essential","pos":"adjective","en":"completely necessary","hu":"elengedhetetlen, nélkülözhetetlen"},{"forms":["nourishing"],"lemma":"nourish","pos":"verb","en":"to give something what it needs to be healthy and grow","hu":"táplál, erősít"},{"forms":["spring into"],"lemma":"spring into","pos":"phrasal verb","en":"to start something quickly and with energy","hu":"belevág, lendülettel nekivág"},{"forms":["anew"],"lemma":"anew","pos":"adverb","en":"again, in a new and fresh way","hu":"újra, frissen"},{"forms":["a good night's sleep"],"lemma":"a good night's sleep","pos":"phrase","en":"a long, deep sleep at night","hu":"egy jó (kiadós) alvás"},{"forms":["actually"],"lemma":"actually","pos":"adverb","en":"really; in fact","hu":"valójában, tényleg"},{"forms":["disappeared"],"lemma":"disappear","pos":"verb","en":"to go away; to not exist any more","hu":"eltűnik"},{"forms":["took part in"],"lemma":"take part in","pos":"phrase","en":"to be one of the people doing something","hu":"részt vesz valamiben"},{"forms":["research project"],"le