insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2006-maj-emelt-R2$mtr$, $mtr$[{"forms":["card scheme"],"lemma":"card scheme","pos":"noun","en":"an official plan or system that uses cards","hu":"kártyás rendszer, kártyaprogram"},{"forms":["battle"],"lemma":"battle","pos":"verb","en":"to fight against something","hu":"harcol valami ellen"},{"forms":["fare dodging"],"lemma":"fare dodging","pos":"noun","en":"travelling on public transport without paying","hu":"bliccelés, jegy nélküli utazás"},{"forms":["updating"],"lemma":"update","pos":"verb","en":"to make something more modern","hu":"korszerűsít, frissít"},{"forms":["fare system"],"lemma":"fare system","pos":"noun","en":"the system of prices and tickets for travelling","hu":"díjszabási rendszer, jegyrendszer"},{"forms":["once again"],"lemma":"once again","pos":"phrase","en":"one more time","hu":"ismét, újra"},{"forms":["state-of-the-art"],"lemma":"state-of-the-art","pos":"adjective","en":"using the newest and most modern technology","hu":"legkorszerűbb, csúcstechnológiás"},{"forms":["smart cards"],"lemma":"smart card","pos":"noun","en":"a plastic card with a computer chip that stores information","hu":"chipkártya, intelligens kártya"},{"forms":["go on sale"],"lemma":"go on sale","pos":"phrase","en":"to become available to buy","hu":"forgalomba kerül, kapható lesz"},{"forms":["magnetic"],"lemma":"magnetic","pos":"adjective","en":"working with a magnet","hu":"mágneses"},{"forms":["eventually"],"lemma":"eventually","pos":"adverb","en":"in the end, after some time","hu":"végül, idővel","tip":"Hamis barát: nem azt jelenti, hogy esetleg (az: possibly)."},{"forms":["issued to"],"lemma":"issue to","pos":"phrase","en":"to officially give something to people","hu":"kiad, kioszt valakinek"},{"forms":["pensioners"],"lemma":"pensioner","pos":"noun","en":"a person who has stopped working because of old age","hu":"nyugdíjas"},{"forms":["entitled to"],"lemma":"be entitled to","pos":"phrase","en":"to have the right to do or have something","hu":"jogosult valamire"},{"forms":["ride free","ride for free"],"lemma":"ride for free","pos":"phrase","en":"to travel without paying","hu":"ingyen utazik"},{"forms":["make it possible to"],"lemma":"make it possible to","pos":"phrase","en":"to allow something to happen","hu":"lehetővé teszi, hogy"},{"forms":["count"],"lemma":"count","pos":"verb","en":"to find the number of people or things","hu":"megszámol"},{"forms":["crack down on"],"lemma":"crack down on","pos":"phrasal verb","en":"to start dealing with a problem in a very strict way","hu":"keményen fellép valami ellen"},{"forms":["abuse"],"lemma":"abuse","pos":"verb","en":"to use something in a wrong or dishonest way","hu":"visszaél valamivel"},{"forms":["flash"],"lemma":"flash","pos":"verb","en":"to show something quickly","hu":"felmutat, (gyorsan) odatart"},{"forms":["within"],"lemma":"within","pos":"preposition","en":"not further than","hu":"belül, ... távolságon belül"},{"forms":["reading device"],"lemma":"reading device","pos":"noun","en":"a machine that reads the information on a card","hu":"leolvasó (készülék)"},{"forms":["located"],"lemma":"be located","pos":"verb","en":"to be in a particular place","hu":"található, elhelyezkedik"},{"forms":["turnstiles"],"lemma":"turnstile","pos":"noun","en":"a gate with turning bars that lets one person through at a time","hu":"forgókapu, beléptetőkapu"},{"forms":["employees"],"lemma":"employee","pos":"noun","en":"a person who works for a company","hu":"alkalmazott, dolgozó"},{"forms":["get them out of"],"lemma":"get something out of","pos":"phrase","en":"to take something out of a place","hu":"kivesz valamiből"},{"forms":["chief"],"lemma":"chief","pos":"noun","en":"the leader or head of a group or place","hu":"vezető, főnök"},{"forms":["place"],"lemma":"place","pos":"verb","en":"to put something somewhere","hu":"tesz, elhelyez"},{"forms":["outside pocket"],"lemma":"outside pocket","pos":"noun","en":"a pocket on the outer side of a