insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2006-okt-emelt-R3$mtr$, $mtr$[{"forms":["tip","tips"],"lemma":"tip","pos":"noun","en":"extra money that you give to a waiter, taxi driver, etc.","hu":"borravaló","tip":"A szövegben az ausztrál tip szeméttelepet is jelent (garbage dump)."},{"forms":["service-related industry"],"lemma":"service-related industry","pos":"noun","en":"the kind of business that serves customers, e.g. restaurants or hotels","hu":"szolgáltató szektor, vendéglátás"},{"forms":["likely to"],"lemma":"be likely to","pos":"phrase","en":"will probably do something","hu":"valószínűleg (meg)tesz"},{"forms":["bonus"],"lemma":"bonus","pos":"noun","en":"something good that you get in addition","hu":"plusz, ráadás, nyereség"},{"forms":["groan inwardly"],"lemma":"groan inwardly","pos":"phrase","en":"to feel unhappy or annoyed without showing it","hu":"magában felsóhajt, belül nyög"},{"forms":["as soon as"],"lemma":"as soon as","pos":"conjunction","en":"immediately when","hu":"amint, mihelyt"},{"forms":["accent"],"lemma":"accent","pos":"noun","en":"the way people from a place say words","hu":"kiejtés, akcentus"},{"forms":["garbage dump"],"lemma":"garbage dump","pos":"noun","en":"a place where rubbish is taken and left","hu":"szeméttelep"},{"forms":["refer to"],"lemma":"refer to","pos":"phrasal verb","en":"to be about or mean something","hu":"utal valamire, jelent valamit"},{"forms":["aids in"],"lemma":"aid in","pos":"phrase","en":"to help in doing something","hu":"segít valamiben"},{"forms":["placing a bet"],"lemma":"place a bet","pos":"phrase","en":"to risk money on the result of a race or game","hu":"fogadást köt"},{"forms":["issue"],"lemma":"issue","pos":"noun","en":"a subject or problem that people discuss","hu":"kérdés, probléma"},{"forms":["both sides"],"lemma":"both sides","pos":"phrase","en":"the two groups of people involved","hu":"mindkét fél"},{"forms":["surprised to learn"],"lemma":"be surprised to learn","pos":"phrase","en":"to be surprised when you find out something","hu":"meglepődve tudja meg"},{"forms":["self-conscious"],"lemma":"self-conscious","pos":"adjective","en":"nervous and uncomfortable because you think others are judging you","hu":"zavarban lévő, feszélyezett"},{"forms":["comfortable"],"lemma":"comfortable","pos":"adjective","en":"relaxed, not worried","hu":"nyugodt, otthonos érzés"},{"forms":["despite"],"lemma":"despite","pos":"preposition","en":"without being changed by something","hu":"valami ellenére","tip":"Utána nincs of: despite the discussion."},{"forms":["low wages"],"lemma":"low wage","pos":"noun","en":"little money paid for work","hu":"alacsony bér, kis fizetés"},{"forms":["couldn't help feeling"],"lemma":"can't help doing something","pos":"phrase","en":"to be unable to stop yourself feeling or doing something","hu":"nem tudtam nem érezni, akaratlanul is úgy éreztem"},{"forms":["a couple of"],"lemma":"a couple of","pos":"phrase","en":"two or a few","hu":"egy-két, pár"},{"forms":["equivalent of"],"lemma":"the equivalent of","pos":"phrase","en":"something that has the same meaning or value","hu":"valaminek a megfelelője, egyenértékű valamivel"},{"forms":["grateful"],"lemma":"grateful","pos":"adjective","en":"wanting to thank someone","hu":"hálás"},{"forms":["pittance"],"lemma":"pittance","pos":"noun","en":"a very small amount of money","hu":"alamizsna, csekély összeg"},{"forms":["prepared to"],"lemma":"be prepared to","pos":"phrase","en":"to be willing to do something","hu":"hajlandó valamire"},{"forms":["throw your way"],"lemma":"throw something someone's way","pos":"phrase","en":"to give something to someone in a careless way","hu":"odavet valakinek"},{"forms":["calculated","calculate","calculating","calculation"],"lemma":"calculate","pos":"verb","en":"to find an amount by using numbers","hu":"kiszámol; calculation = számítás"},{"forms":["casual"],"lemma":"casual","pos":"adjective","en":"done without much thought or care","hu":"hanyag, odavetett, laza"},{"forms":["comes out at"],"lemma":"come out at","pos":"phrasal verb","en":"to be a certain amount after calculating","hu":"kijön (összegre), annyi lesz"},{"forms":["request"],"lemma":"request","pos":"verb","en":"to ask for something politely","hu":"kér"},{"forms":["decimal point"],"lemma":"decimal point","pos":"noun","en":"the dot in a number like 2.70","hu":"tizedespont (a magyarban tizedesvessző)"},{"forms":["round"],"lemma":"round","pos":"adjective","en":"a whole number, without cents","hu":"kerek (összeg)"},{"forms":["adequate"],"lemma":"adequate","pos":"adjective","en":"enough; good enough","hu":"elegendő, megfelelő"},{"forms":["go up and down"],"lemma":"go up and down","pos":"phrase","en":"to become bigger and smaller","hu":"nő és csökken, változik"},{"forms":["reflect"],"lemma":"reflect","pos":"verb","en":"to show what something is like","hu":"tükröz, kifejez"},{"forms":["quality"],"lemma":"quality","pos":"noun","en":"how good something is","hu":"minőség"},{"forms":["stick to"],"lemma":"stick to","pos":"phrasal verb","en":"to continue doing what is usual and not change","hu":"ragaszkodik valamihez, tartja magát valamihez"},{"forms":["mutterings"],"lemma":"muttering","pos":"noun","en":"quiet complaints that people say to themselves","hu":"morgolódás, dörmögés"},{"forms":["deserved"],"lemma":"deserve","pos":"verb","en":"to have earned something because of what you did","hu":"megérdemel"},{"forms":["have yet to see"],"lemma":"have yet to see","pos":"phrase","en":"I have not seen it until now","hu":"még nem láttam"},{"forms":["act upon"],"lemma":"act upon","pos":"phrasal verb","en":"to do something because of an opinion","hu":"eszerint cselekszik, tesz is valamit"},{"forms":["handing"],"lemma":"hand","pos":"verb","en":"to give something to someone with your hand","hu":"kézbe ad, átnyújt"},{"forms":["directly"],"lemma":"directly","pos":"adverb","en":"straight to someone, with nobody or nothing between","hu":"közvetlenül"},{"forms":["walk away from"],"lemma":"wal