insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2007-maj-emelt-R2$mtr$, $mtr$[{"forms":["happy landing"],"lemma":"happy landing","pos":"phrase","en":"a safe and successful arrival of a plane on the ground","hu":"szerencsés (sikeres) leszállás"},{"forms":["virtually"],"lemma":"virtually","pos":"adverb","en":"on a computer, not in real life","hu":"virtuálisan","tip":"Gyakran azt is jelenti: szinte, majdnem."},{"forms":["travel editor"],"lemma":"travel editor","pos":"noun","en":"the journalist in charge of the travel part of a newspaper","hu":"utazási rovat vezetője"},{"forms":["jumbo"],"lemma":"jumbo","pos":"noun","en":"a very big passenger plane (a Boeing 747)","hu":"jumbo jet (óriás utasszállító)"},{"forms":["runway lights"],"lemma":"runway light","pos":"noun","en":"lights on the long road where planes take off and land","hu":"kifutópálya-fények"},{"forms":["runway"],"lemma":"runway","pos":"noun","en":"the long road where planes take off and land","hu":"kifutópálya, leszállópálya"},{"forms":["blinked"],"lemma":"blink","pos":"verb","en":"if a light blinks, it goes on and off","hu":"villog, pislákol"},{"forms":["darkness"],"lemma":"darkness","pos":"noun","en":"when there is no light","hu":"sötétség"},{"forms":["below"],"lemma":"below","pos":"preposition","en":"under, lower than","hu":"alatt, lent"},{"forms":["inky"],"lemma":"inky","pos":"adjective","en":"very dark, like ink","hu":"tintafekete, koromsötét"},{"forms":["harbour"],"lemma":"harbour","pos":"noun","en":"an area of water near the land where ships stay","hu":"kikötő, öböl"},{"forms":["beyond"],"lemma":"beyond","pos":"adverb","en":"further away, on the other side","hu":"azon túl"},{"forms":["skyscrapers"],"lemma":"skyscraper","pos":"noun","en":"a very tall building","hu":"felhőkarcoló"},{"forms":["twinkling"],"lemma":"twinkle","pos":"verb","en":"to shine with a light that changes quickly","hu":"szikrázik, pislákol, ragyog"},{"forms":["intending to"],"lemma":"intend to","pos":"phrase","en":"to plan to do something","hu":"szándékozik, tervez"},{"forms":["alarmingly"],"lemma":"alarmingly","pos":"adverb","en":"in a way that makes you worried","hu":"ijesztő módon"},{"forms":["instead of"],"lemma":"instead of","pos":"preposition","en":"in place of","hu":"helyett"},{"forms":["at this rate"],"lemma":"at this rate","pos":"phrase","en":"if things continue like this","hu":"ha ez így megy tovább, ilyen tempóban"},{"forms":["shoot across"],"lemma":"shoot across","pos":"phrasal verb","en":"to move very fast over something","hu":"átszáguld valamin"},{"forms":["end up in"],"lemma":"end up in","pos":"phrasal verb","en":"to finally be in a place you did not plan","hu":"valahol köt ki"},{"forms":["ease her nose up"],"lemma":"ease the nose up","pos":"phrase","en":"to move the front of the plane up slowly and carefully","hu":"emeld meg óvatosan a gép orrát"},{"forms":["flight engineer"],"lemma":"flight engineer","pos":"noun","en":"the person in the cockpit who checks the engines and systems","hu":"fedélzeti mérnök"},{"forms":["admirably"],"lemma":"admirably","pos":"adverb","en":"in a way that people admire","hu":"bámulatosan, dicséretes módon"},{"forms":["keeping the panic out of his voice"],"lemma":"keep the panic out of one's voice","pos":"phrase","en":"speaking calmly so that nobody hears that you are afraid","hu":"nem hallatszott a hangján a pánik"},{"forms":["pulled"],"lemma":"pull","pos":"verb","en":"to move something towards you","hu":"húz"},{"forms":["control column"],"lemma":"control column","pos":"noun","en":"the handle that a pilot uses to steer a plane","hu":"botkormány, kormányoszlop"},{"forms":["set our course for"],"lemma":"set a course for","pos":"phrase","en":"to start moving in the direction of","hu":"irányt veszünk valami felé"},{"forms":["trickiest"],"lemma":"tricky","pos":"adjective","en":"difficult, needing skill","hu":"trükkös, a legnehezebb"},{"forms":["approaches"],"lemma":"approach","pos":"noun","en":"the way a plane flies towards the r