insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2008-okt-kozep-R1$mtr$, $mtr$[{"forms":["full-scale"],"lemma":"full-scale","pos":"adjective","en":"complete and very serious; as big as possible","hu":"igazi, teljes, komoly"},{"forms":["did seem"],"lemma":"do seem","pos":"phrase","en":"really seemed; 'did' makes the verb stronger","hu":"tényleg úgy tűnt","tip":"A did itt csak nyomatékosít: did seem = tényleg tűnt."},{"forms":["at the time"],"lemma":"at the time","pos":"phrase","en":"then, when it happened (not now)","hu":"akkor, abban az időben"},{"forms":["although"],"lemma":"although","pos":"conjunction","en":"despite the fact that","hu":"bár, habár"},{"forms":["only just"],"lemma":"only just","pos":"phrase","en":"a very short time before","hu":"épp csak, nemrég"},{"forms":["passed"],"lemma":"pass","pos":"verb","en":"to be successful in a test or exam","hu":"letesz (vizsgát), sikeresen levizsgázik","tip":"Hamis barát: pass an exam = sikeres vizsgát tesz, nem csak elmegy vizsgázni."},{"forms":["driving test"],"lemma":"driving test","pos":"noun","en":"the exam you must pass before you can drive a car alone","hu":"járművezetői vizsga, jogsivizsga"},{"forms":["on holiday"],"lemma":"on holiday","pos":"phrase","en":"away from home for a rest or a trip","hu":"nyaralni, szabadságon"},{"forms":["involved"],"lemma":"involved","pos":"adjective","en":"taking part in something; connected with something","hu":"érintett, részt vevő"},{"forms":["blame"],"lemma":"blame","pos":"verb","en":"to say that someone or something caused a bad thing","hu":"hibáztat, okol"},{"forms":["turning off"],"lemma":"turn off","pos":"phrasal verb","en":"to leave a road and go onto another road or path","hu":"lekanyarodik, letér (az útról)","tip":"Itt nem azt jelenti, hogy kikapcsol."},{"forms":["driveway"],"lemma":"driveway","pos":"noun","en":"a short private road from the street to a house","hu":"kocsibejáró, felhajtó"},{"forms":["somehow"],"lemma":"somehow","pos":"adverb","en":"in a way that you do not know or understand","hu":"valahogy, valahogyan"},{"forms":["managed to"],"lemma":"manage to","pos":"phrase","en":"to succeed in doing something (here used with humour about a bad thing)","hu":"sikerül (valamit megtenni)"},{"forms":["catch"],"lemma":"catch","pos":"verb","en":"to hit something by accident so that it touches or gets stuck","hu":"beakad, nekiütődik, hozzáér","tip":"Itt nem azt jelenti, hogy elkap."},{"forms":["my heart sank"],"lemma":"your heart sinks","pos":"idiom","en":"you suddenly feel sad or worried","hu":"elszorult a szívem, inamba szállt a bátorságom"},{"forms":["crunch"],"lemma":"crunch","pos":"noun","en":"the loud noise of something hard being pressed or broken","hu":"reccsenés, csikorgás"},{"forms":["shame"],"lemma":"shame","pos":"noun","en":"the bad feeling you have when you have done something wrong or stupid","hu":"szégyen"},{"forms":["in front of"],"lemma":"in front of","pos":"preposition","en":"where someone can see you","hu":"(valaki) előtt, (valaki) szeme láttára"},{"forms":["stupid"],"lemma":"stupid","pos":"adjective","en":"not sensible; silly","hu":"buta, ostoba"},{"forms":["have a look"],"lemma":"have a look","pos":"phrase","en":"to look at something","hu":"megnéz, szemügyre vesz"},{"forms":["that bad"],"lemma":"not that bad","pos":"phrase","en":"not very bad","hu":"nem olyan vészes, nem is olyan rossz"},{"forms":["scratch"],"lemma":"scratch","pos":"noun","en":"a thin mark or cut on a surface","hu":"karcolás, horzsolás"},{"forms":["dreaded"],"lemma":"dread","pos":"verb","en":"to feel very worried about something that is going to happen","hu":"retteg (valamitől), nagyon fél"},{"forms":["keen on"],"lemma":"be keen on","pos":"phrase","en":"to like something very much","hu":"nagyon szeret, oda van (valamiért)"},{"forms":["particularly"],"lemma":"particularly","pos":"adverb","en":"more than usual; especially","hu":"különösen, főleg"},{"forms":["fond of"],"lemma":"be fond of","pos":"phrase","en":"to like someone or something very much","hu":"nagyon szeret, ragaszkodik (valamihez)"},{"forms":["pretended"],"lemma":"pretend","pos":"verb","en":"to act as if something is true when it is not","hu":"úgy tesz, mintha; színlel"},{"forms":["mind"],"lemma":"mind","pos":"verb","en":"to be annoyed or upset about something","hu":"bánja, zavarja (valami)"},{"forms":["exciting"],"lemma":"exciting","pos":"adjective","en":"making you feel interested and full of energy","hu":"izgalmas"},{"forms":["took it more to heart"],"lemma":"take something to heart","pos":"idiom","en":"to be very upset by something and think about it a lot","hu":"a szívére vesz valamit"},{"forms":["novice"],"lemma":"novice","pos":"adjective","en":"new to an activity and without much experience","hu":"kezdő"},{"forms":["realise"],"lemma":"realise","pos":"verb","en":"to understand or know something","hu":"rájön, felfog, tudatában van"},{"forms":["this sort of"],"lemma":"this sort of","pos":"phrase","en":"this kind of","hu":"ilyen, ez a fajta"},{"forms":["summary"],"lemma":"summary","pos":"noun","en":"a short text that gives the main facts of a longer one","hu":"összefoglaló"},{"forms":["author"],"lemma":"author","pos":"noun","en":"the person who wrote a text","hu":"szerző, író"},{"forms":["serious"],"lemma":"serious","pos":"adjective","en":"bad or dangerous","hu":"súlyos, komoly"},{"forms":["over"],"lemma":"over","pos":"preposition","en":"more than","hu":"több mint, elmúlt (évesen)"},{"forms":["driving licence"],"lemma":"driving licence","pos":"noun","en":"an official document that shows you are allowed to drive","hu":"jogosítvány"},{"forms":["though"],"lemma":"though","pos":"conjunction","en":"although","hu":"bár, habár"},{"forms":["ashamed"],"lemma":"ashamed","pos":"adjective","en":"feeling bad and embarrassed because of something you did","hu":"szégyelli magát"},{"forms":["damaged"],"lemma":"damage","pos":"verb","en":"to harm or break something","hu":"megrongál, megsért, kárt tesz (valamiben)"},{"forms":["miserable"],"lemma":"miserable","pos":"adjective","en":"very unhappy","hu":"nagyon szomorú, nyomorult"},{"forms":["common"],"lemma":"common","pos":"adjective","en":"happening often","hu":"gyakori, mindennapos"}]$mtr$::jsonb, $mtr$[{"forms":["crash"],"lemma":"crash","pos":"noun","en":"an accident in which a car hits something","hu":"baleset, ütközés, karambol"},{"forms":["in my forties"],"lemma":"in your forties","pos":"phrase","en":"between 40 and 49 years old","hu":"negyvenes éveiben (40 és 49 év között)"},{"forms":["traffic"],"lemma":"traffic","pos":"noun","en":"the cars and other vehicles moving on a road","hu":"forgalom"},{"forms":["accident"],"lemma":"accident","pos":"noun","en":"something bad that happens by chance, for example when a car hits something","hu":"baleset"}]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2008-okt-kozep-R2$mtr$, $mtr$[{"forms":["engineers"],"lemma":"engineer","pos":"noun","en":"a person who designs, builds or repairs machines","hu":"mérnök, műszerész"},{"forms":["call time on"],"lemma":"call time on","pos":"idiom","en":"to stop something for a while or for ever","hu":"leállít, véget vet (valaminek)","tip":"Szójáték: a time itt az órára (clock) is utal."},{"forms":["re-tuning","re-tuned"],"lemma":"re-tune","pos":"verb","en":"to make a bell or instrument play the correct notes again","hu":"újrahangol"},{"forms":["stoppage"],"lemma":"stoppage","pos":"noun","en":"a time when something stops working or moving","hu":"leállás, szünet"},{"forms":["thorough"],"lemma":"thorough","pos":"adjective","en":"very careful and complete, looking at every detail","hu":"alapos"},{"forms":["inspection"],"lemma":"inspection","pos":"noun","en":"a careful check of something","hu":"átvizsgálás, ellenőrzés"},{"forms":["quarter bells"],"lemma":"quarter bell","pos":"noun","en":"a bell in a clock tower that rings every fifteen minutes","hu":"negyedütő harang"},{"forms":["hour bell"],"lemma":"hour bell","pos":"noun","en":"the big bell in a clock tower that rings every hour","hu":"óraütő harang"},{"forms":["stowaway"],"lemma":"stowaway","pos":"noun","en":"someone who hides on a ship or plane to travel without paying","hu":"potyautas"},{"forms":["grounded"],"lemma":"ground","pos":"verb","en":"to stop a plane from flying","hu":"a földön tart, nem enged felszállni (repülőgépet)","tip":"Itt ige; főnévként (ground) föld, talaj."},{"forms":["aeroplane"],"lemma":"aeroplane","pos":"noun","en":"a plane","hu":"repülőgép"},{"forms":["passengers"],"lemma":"passenger","pos":"noun","en":"a person who travels in a vehicle but does not drive it","hu":"utas"},{"forms":["aircraft"],"lemma":"aircraft","pos":"noun","en":"a plane","hu":"repülőgép","tip":"Többes száma is aircraft."},{"forms":["take-off"],"lemma":"take-off","pos":"noun","en":"the moment when a plane leaves the ground","hu":"felszállás"},{"forms":["economy class"],"lemma":"economy class","pos":"noun","en":"the cheapest seats on a plane","hu":"turistaosztály"},{"forms":["section"],"lemma":"section","pos":"noun","en":"one part of something","hu":"rész"},{"forms":["captain"],"lemma":"captain","pos":"noun","en":"the pilot in charge of a plane","hu":"kapitány, a gép parancsnoka"},{"forms":["ordered"],"lemma":"order","pos":"verb","en":"to tell someone that they must do something","hu":"utasít, megparancsol"},{"forms":["get off"],"lemma":"get off","pos":"phrasal verb","en":"to leave a plane, bus or train","hu":"leszáll (járműről)"},{"forms":["maintenance staff"],"lemma":"maintenance staff","pos":"noun","en":"the workers who check and repair machines or buildings","hu":"karbantartók, műszaki személyzet"},{"forms":["searched"],"lemma":"search","pos":"verb","en":"to look carefully everywhere in a place to find something","hu":"átkutat, átvizsgál"},{"forms":["most probably"],"lemma":"most probably","pos":"phrase","en":"very likely","hu":"nagy valószínűséggel"},{"forms":["on board"],"lemma":"on board","pos":"phrase","en":"on a plane or ship","hu":"a fedélzeten"},{"forms":["unhealthy"],"lemma":"unhealthy","pos":"adjective","en":"bad for your health; not in a good state","hu":"egészségtelen, beteges"},{"forms":["health service"],"lemma":"health service","pos":"noun","en":"the state system that gives people medical care","hu":"egészségügy, egészségügyi ellátás"},{"forms":["mercury"],"lemma":"mercury","pos":"noun","en":"a silver-coloured liquid metal that can be poisonous","hu":"higany"},{"forms":["content"],"lemma":"content","pos":"noun","en":"the amount of a substance that something contains","hu":"tartalom (anyagé), -tartalom"},{"forms":["vaccines"],"lemma":"vaccine","pos":"noun","en":"a substance put into the body to protect it from a disease","hu":"védőoltás, vakcina"},{"forms":["dental fillings","fillings"],"lemma":"filling","pos":"noun","en":"a small amount of material that a dentist puts into a hole in a tooth","hu":"tömés (fogban)"},{"forms":["dentist"],"lemma":"dentist","pos":"noun","en":"a doctor who looks after people's teeth","hu":"fogorvos"},{"forms":["warned"],"lemma":"warn","pos":"verb","en":"to tell someone about a possible danger or problem","hu":"figyelmeztet"},{"forms":["potentially"],"lemma":"potentially","pos":"adverb","en":"possibly, in the future or in some cases","hu":"lehetségesen, esetleg"},{"forms":["harmful"],"lemma":"harmful","pos":"adjective","en":"causing damage or bad effects","hu":"ártalmas, káros"},{"forms":["go private"],"lemma":"go private","pos":"phrase","en":"to pay for medical care instead of using the free state service","hu":"magánorvoshoz megy, magánellátást vesz igénybe"},{"forms":["ended up"],"lemma":"end up","pos":"phrasal verb","en":"to finally be in a situation or do something","hu":"végül (valahogy alakul), a vége az lett, hogy"},{"forms":["grotesque"],"lemma":"grotesque","pos":"adjective","en":"very wrong and shocking","hu":"felháborító, képtelen"},{"forms":["afford"],"lemma":"afford","pos":"verb","en":"to have enough money to pay for something","hu":"megengedheti magának (anyagilag)"},{"forms":["this sort of"],"lemma":"this sort of","pos":"phrase","en":"this kind of","hu":"ilyen, ennyi"},{"forms":["especially"],"lemma":"especially","pos":"adverb","en":"more than in other cases","hu":"különösen, főleg"},{"forms":["large numbers of"],"lemma":"large numbers of","pos":"phrase","en":"many","hu":"sok, nagy számú"},{"forms":["it's time"],"lemma":"it's time","pos":"phrase","en":"something should happen now","hu":"itt az ideje, hogy","tip":"Utána múlt idő áll: It's time the Government changed ... = Ideje, hogy a kormány változtasson."},{"forms":["stub out"],"lemma":"stub out","pos":"phrasal verb","en":"to stop a cigarette burning by pressing it on something; here: to stop smoking","hu":"elnyom (cigarettát); itt: leszokik"},{"forms":["cigs"],"lemma":"cig","pos":"noun","en":"an informal word for a cigarette","hu":"cigi"},{"forms":["claimed"],"lemma":"claim","pos":"verb","en":"to say that something is true","hu":"állít, kijelent"},{"forms":["dramatic"],"lemma":"dramatic","pos":"adjective","en":"very big and surprising","hu":"látványos, jelentős"},{"forms":["give up","given up","gave up"],"lemma":"give up","pos":"phrasal verb","en":"to stop doing something, for example smoking","hu":"abbahagy, leszokik (valamiről)"},{"forms":["habit"],"lemma":"habit","pos":"noun","en":"something you do often, often without thinking","hu":"szokás"},{"forms":["lighting up"],"lemma":"light up","pos":"phrasal verb","en":"to start smoking a cigarette","hu":"rágyújt"},{"forms":["nicotine replacement therapy"],"lemma":"nicotine replacement therapy","pos":"noun","en":"a treatment that gives smokers nicotine in another way to help them stop smoking","hu":"nikotinpótló kezelés"},{"forms":["chewing gum"],"lemma":"chewing gum","pos":"noun","en":"a sweet that you chew but do not swallow","hu":"rágógumi"},{"forms":["patches"],"lemma":"patch","pos":"noun","en":"a small piece of material that you stick on your skin to give you a medicine","hu":"tapasz"},{"forms":["figures"],"lemma":"figure","pos":"noun","en":"official numbers","hu":"adatok, számok"},{"forms":["spent on"],"lemma":"spend on","pos":"phrase","en":"to use money to pay for something","hu":"(pénzt) költ valamire"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2008-okt-kozep-R3$mtr$, $mtr$[{"forms":["lost world"],"lemma":"lost world","pos":"noun","en":"a place that people did not know about or had forgotten","hu":"elveszett világ"},{"forms":["uncovered"],"lemma":"uncover","pos":"verb","en":"to find something that was hidden or unknown","hu":"feltár, felfedez"},{"forms":["epic"],"lemma":"epic","pos":"adjective","en":"very long, difficult and exciting","hu":"hősies, hatalmas, nagyszabású"},{"forms":["journey"],"lemma":"journey","pos":"noun","en":"a long trip from one place to another","hu":"utazás, út"},{"forms":["unexplored"],"lemma":"unexplored","pos":"adjective","en":"not yet visited or studied by anyone","hu":"felderítetlen, feltáratlan"},{"forms":["explorer"],"lemma":"explorer","pos":"noun","en":"a person who travels to unknown places to learn about them","hu":"felfedező"},{"forms":["led"],"lemma":"lead","pos":"verb","en":"to be in charge of a group and go in front of it","hu":"vezet (csoportot)","tip":"Rendhagyó: lead – led – led."},{"forms":["rapids"],"lemma":"rapids","pos":"noun","en":"a part of a river where the water moves very fast over rocks","hu":"zuhatag, sodrás"},{"forms":["waterfalls"],"lemma":"waterfall","pos":"noun","en":"a place where a river falls down from a high place","hu":"vízesés"},{"forms":["stretch"],"lemma":"stretch","pos":"noun","en":"a long piece of land or water","hu":"szakasz"},{"forms":["specially-designed"],"lemma":"specially-designed","pos":"adjective","en":"made for one particular purpose","hu":"erre a célra tervezett"},{"forms":["inflatable"],"lemma":"inflatable","pos":"adjective","en":"that you fill with air before you use it","hu":"felfújható"},{"forms":["border"],"lemma":"border","pos":"noun","en":"the line between two countries","hu":"határ (országé)"},{"forms":["expedition"],"lemma":"expedition","pos":"noun","en":"a long, organised journey to explore a place","hu":"expedíció"},{"forms":["series"],"lemma":"series","pos":"noun","en":"a number of similar things that come one after another","hu":"sorozat"},{"forms":["commanded"],"lemma":"command","pos":"verb","en":"to be the leader of a group, like an officer in the army","hu":"vezényel, parancsnokol"},{"forms":["former"],"lemma":"former","pos":"adjective","en":"that was something in the past but is not now","hu":"egykori, volt"},{"forms":["soldier"],"lemma":"soldier","pos":"noun","en":"a person in the army","hu":"katona"},{"forms":["aims to"],"lemma":"aim to","pos":"phrase","en":"to plan or try to do something","hu":"célja, hogy; arra törekszik"},{"forms":["prove"],"lemma":"prove","pos":"verb","en":"to show that something is true","hu":"bizonyít"},{"forms":["coast"],"lemma":"coast","pos":"noun","en":"the land next to the sea","hu":"tengerpart"},{"forms":["basin"],"lemma":"basin","pos":"noun","en":"the large area of land from which water flows into a river","hu":"medence (folyóé)"},{"forms":["previous"],"lemma":"previous","pos":"adjective","en":"earlier; happening before","hu":"korábbi, előző"},{"forms":["reeds"],"lemma":"reed","pos":"noun","en":"a tall plant like grass that grows in or near water","hu":"nád"},{"forms":["carvings"],"lemma":"carving","pos":"noun","en":"a picture or shape cut into stone or wood","hu":"faragás, dombormű"},{"forms":["violent"],"lemma":"violent","pos":"adjective","en":"very strong and dangerous","hu":"heves, vad, erőszakos"},{"forms":["force"],"lemma":"force","pos":"noun","en":"strength or power","hu":"erő"},{"forms":["convinced"],"lemma":"convinced","pos":"adjective","en":"completely sure about something","hu":"meggyőződött, biztos (benne)"},{"forms":["survived"],"lemma":"survive","pos":"verb","en":"to continue to exist after something dangerous","hu":"túlél, átvészel"},{"forms":["despite the fact that"],"lemma":"despite the fact that","pos":"phrase","en":"although","hu":"annak ellenére, hogy"},{"forms":["thrown about"],"lemma":"throw about","pos":"phrasal verb","en":"to be moved violently in different directions","hu":"ide-oda dobál, hányódik"},{"forms":["broken bones"],"lemma":"broken bone","pos":"noun","en":"a bone in the body that has cracked","hu":"csonttörés"},{"forms":["known as"],"lemma":"known as","pos":"phrase","en":"called","hu":"úgynevezett, amelyet ... néven ismernek"},{"forms":["gorge"],"lemma":"gorge","pos":"noun","en":"a deep narrow valley with steep sides","hu":"szurdok, szoros"},{"forms":["blocked"],"lemma":"block","pos":"verb","en":"to stop things from moving through a place","hu":"elzár, eltorlaszol"},{"forms":["huge"],"lemma":"huge","pos":"adjective","en":"very big","hu":"óriási, hatalmas"},{"forms":["carried"],"lemma":"carry","pos":"verb","en":"to hold something and take it somewhere","hu":"visz, cipel"},{"forms":["guided"],"lemma":"guide","pos":"verb","en":"to lead or move something carefully in the right direction","hu":"irányít, vezet"},{"forms":["ropes"],"lemma":"rope","pos":"noun","en":"very thick, strong string","hu":"kötél"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2008-okt-kozep-R4$mtr$, $mtr$[{"forms":["up and away"],"lemma":"up and away","pos":"phrase","en":"going up into the air and leaving","hu":"fel és el, irány a magasba"},{"forms":["some"],"lemma":"some","pos":"adverb","en":"about, approximately (before a number)","hu":"mintegy, körülbelül","tip":"Szám előtt a some azt jelenti: kb."},{"forms":["Britons"],"lemma":"Briton","pos":"noun","en":"a British person","hu":"brit (ember)"},{"forms":["migrate"],"lemma":"migrate","pos":"verb","en":"to move to another place, often at a particular time of year, like birds","hu":"vándorol, átköltözik"},{"forms":["purpose-built"],"lemma":"purpose-built","pos":"adjective","en":"built for one special use","hu":"kifejezetten erre a célra épült"},{"forms":["resorts"],"lemma":"resort","pos":"noun","en":"a place where many people go on holiday","hu":"üdülőhely"},{"forms":["slopes"],"lemma":"slope","pos":"noun","en":"the side of a mountain, especially one used for skiing","hu":"lejtő, sípálya"},{"forms":["commercialised"],"lemma":"commercialised","pos":"adjective","en":"changed to make as much money as possible, for example from tourists","hu":"elüzletiesedett, kommercializálódott"},{"forms":["impossible"],"lemma":"impossible","pos":"adjective","en":"that cannot happen or be done","hu":"lehetetlen"},{"forms":["ringing"],"lemma":"ring","pos":"verb","en":"to make a bell make a sound","hu":"csenget, kolompol"},{"forms":["cowbell"],"lemma":"cowbell","pos":"noun","en":"a bell that hangs from a cow's neck; here, a typical tourist souvenir","hu":"kolomp, tehénkolomp"},{"forms":["realise"],"lemma":"realise","pos":"verb","en":"to start to understand something","hu":"rájön, felismer"},{"forms":["besides"],"lemma":"besides","pos":"preposition","en":"in addition to; apart from","hu":"valamin kívül, mellett"},{"forms":["downhill skiing"],"lemma":"downhill skiing","pos":"noun","en":"skiing down a mountain on a prepared slope","hu":"lesiklás, alpesi síelés"},{"forms":["fashionable"],"lemma":"fashionable","pos":"adjective","en":"popular at a particular time","hu":"divatos, felkapott"},{"forms":["heli-skiing"],"lemma":"heli-skiing","pos":"noun","en":"skiing where a helicopter takes you to the top of a mountain","hu":"helikopteres síelés"},{"forms":["para-gliding"],"lemma":"para-gliding","pos":"noun","en":"a sport in which you fly through the air with a kind of parachute","hu":"siklóernyőzés"},{"forms":["floating"],"lemma":"float","pos":"verb","en":"to move slowly through the air or on water","hu":"lebeg, siklik"},{"forms":["parachute-like"],"lemma":"parachute-like","pos":"adjective","en":"similar to a parachute, the cloth that lets you fall slowly from a plane","hu":"ejtőernyőszerű"},{"forms":["structure"],"lemma":"structure","pos":"noun","en":"something built from several parts","hu":"szerkezet"},{"forms":["experienced"],"lemma":"experienced","pos":"adjective","en":"having done something many times, so you are good at it","hu":"tapasztalt, gyakorlott"},{"forms":["mad-brave"],"lemma":"mad-brave","pos":"adjective","en":"so brave that it seems crazy","hu":"őrülten bátor, vakmerő"},{"forms":["gentler"],"lemma":"gentle","pos":"adjective","en":"calm and not too hard or dangerous","hu":"szelídebb, kíméletesebb"},{"forms":["outback"],"lemma":"outback","pos":"noun","en":"a wild area far away from towns","hu":"vadon, a civilizációtól távoli vidék"},{"forms":["heels-free"],"lemma":"heels-free","pos":"adjective","en":"with the back of the boot not fixed to the ski","hu":"szabad sarkú (síelés)"},{"forms":["Nordic skiing"],"lemma":"Nordic skiing","pos":"noun","en":"skiing across flat or hilly countryside, not down steep slopes","hu":"sífutás, északi síelés"},{"forms":["countryside"],"lemma":"countryside","pos":"noun","en":"land outside towns, with fields, forests and hills","hu":"vidék, táj"},{"forms":["method"],"lemma":"method","pos":"noun","en":"a way of doing something","hu":"módszer, mód"},{"forms":["flexible"],"lemma":"flexible","pos":"adjective","en":"able to bend easily","hu":"hajlékony, rugalmas"},{"forms":["lightweight"],"lemma":"lightweight","pos":"adjective","en":"not heavy","hu":"könnyű (súlyú)"},{"forms":["wrapped"],"lemma":"wrap","pos":"verb","en":"to cover something with material","hu":"beborít, becsavar"},{"forms":["skins"],"lemma":"skin","pos":"noun","en":"a strip of material under a ski that stops it sliding backwards","hu":"fóka, csúszásgátló talp (sílécen)"},{"forms":["one-sided"],"lemma":"one-sided","pos":"adjective","en":"working on only one side","hu":"egyoldalú"},{"forms":["Velcro"],"lemma":"Velcro","pos":"noun","en":"a material with tiny hooks that sticks to itself","hu":"tépőzár"},{"forms":["climb"],"lemma":"climb","pos":"verb","en":"to go up something","hu":"felmászik, felkapaszkodik"},{"forms":["mountain huts"],"lemma":"mountain hut","pos":"noun","en":"a simple building in the mountains where walkers or skiers can stay","hu":"menedékház, turistaház"},{"forms":["eco-friendly"],"lemma":"eco-friendly","pos":"adjective","en":"not harmful to the environment","hu":"környezetbarát"},{"forms":["discovery"],"lemma":"discovery","pos":"noun","en":"finding something new","hu":"felfedezés"},{"forms":["lifts"],"lemma":"lift","pos":"noun","en":"a machine that carries skiers up a mountain","hu":"sílift, felvonó"},{"forms":["crowded"],"lemma":"crowded","pos":"adjective","en":"full of people","hu":"zsúfolt"},{"forms":["car parks"],"lemma":"car park","pos":"noun","en":"a place where you can leave your car","hu":"parkoló"},{"forms":["best of all"],"lemma":"best of all","pos":"phrase","en":"the best thing is","hu":"ami a legjobb, a legjobb az egészben"},{"forms":["curse"],"lemma":"curse","pos":"noun","en":"something that causes a lot of trouble","hu":"átok, csapás"},{"forms":["queue"],"lemma":"queue","pos":"noun","en":"a line of people waiting for something","hu":"sor (várakozóké)"},{"forms":["athletic"],"lemma":"athletic","pos":"adjective","en":"fit, strong and good at sport","hu":"sportos, edzett"},{"forms":["rent"],"lemma":"rent","pos":"verb","en":"to pay money to use a house for a time","hu":"bérel"},{"forms":["lie"],"lemma":"lie","pos":"verb","en":"to be in a particular place","hu":"fekszik, elhelyezkedik"},{"forms":["snowline"],"lemma":"snowline","pos":"noun","en":"the height on a mountain above which there is always snow","hu":"hóhatár"},{"forms":["neighbours"],"lemma":"neighbour","pos":"noun","en":"a person who lives near you","hu":"szomszéd"},{"forms":["accepted"],"lemma":"accept","pos":"verb","en":"to let someone become part of a group","hu":"befogad, elfogad"},{"forms":["community"],"lemma":"community","pos":"noun","en":"the people who live in one place","hu":"közösség"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
