insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2009-okt-kozep-R1$mtr$, $mtr$[{"forms":["space rock"],"lemma":"space rock","pos":"noun","en":"a piece of rock that comes from space","hu":"űrből érkező kő"},{"forms":["crash landing"],"lemma":"crash landing","pos":"noun","en":"a sudden, hard landing in which something hits the ground","hu":"kényszerleszállás, becsapódás"},{"forms":["grapefruit-size"],"lemma":"grapefruit-size","pos":"adjective","en":"as big as a grapefruit, a large round yellow fruit","hu":"grapefruit nagyságú"},{"forms":["meteorite","meteorites"],"lemma":"meteorite","pos":"noun","en":"a piece of rock from space that has fallen to the Earth","hu":"meteorit"},{"forms":["crashed through"],"lemma":"crash through","pos":"phrasal verb","en":"to break something and go through it with great force","hu":"átszakít, áttör (valamin)"},{"forms":["ceiling"],"lemma":"ceiling","pos":"noun","en":"the top surface of a room, above your head","hu":"mennyezet, plafon"},{"forms":["slammed into"],"lemma":"slam into","pos":"phrasal verb","en":"to hit something very hard","hu":"nekicsapódik, belecsapódik"},{"forms":["couch"],"lemma":"couch","pos":"noun","en":"a long soft seat for two or more people; a sofa","hu":"kanapé, dívány"},{"forms":["rolled"],"lemma":"roll","pos":"verb","en":"to move along by turning over and over","hu":"gurul"},{"forms":["experts"],"lemma":"expert","pos":"noun","en":"a person who knows a lot about a subject","hu":"szakértő"},{"forms":["extremely"],"lemma":"extremely","pos":"adverb","en":"very, very","hu":"rendkívül, nagyon"},{"forms":["traveling"],"lemma":"travel","pos":"verb","en":"to move (here: to fly through the air or space)","hu":"halad, száguld","tip":"Az amerikai írásmód egy l-lel: traveling (brit: travelling)."},{"forms":["landing"],"lemma":"landing","pos":"noun","en":"the moment when something comes down to the ground","hu":"földet érés, becsapódás"},{"forms":["terrific"],"lemma":"terrific","pos":"adjective","en":"very great or loud","hu":"hatalmas, iszonyú"},{"forms":["explosion"],"lemma":"explosion","pos":"noun","en":"a very loud noise, like when a bomb goes off","hu":"robbanás, durranás"},{"forms":["most likely"],"lemma":"most likely","pos":"phrase","en":"very probably","hu":"nagy valószínűséggel, legvalószínűbb, hogy"},{"forms":["chip"],"lemma":"chip","pos":"noun","en":"a small piece that has broken off something","hu":"szilánk, letört darab"},{"forms":["asteroid"],"lemma":"asteroid","pos":"noun","en":"a large rock that moves around the sun","hu":"kisbolygó, aszteroida"},{"forms":["in fact"],"lemma":"in fact","pos":"phrase","en":"really; used to add a more exact detail","hu":"valójában, ténylegesen"},{"forms":["billion"],"lemma":"billion","pos":"noun","en":"one thousand million (1,000,000,000)","hu":"milliárd","tip":"Hamis barát: a billion nem billió, hanem milliárd."},{"forms":["physical records"],"lemma":"physical record","pos":"noun","en":"a real object that shows us what happened in the past","hu":"tárgyi bizonyíték, kézzelfogható emlék"},{"forms":["solar system"],"lemma":"solar system","pos":"noun","en":"the sun and the planets that move around it","hu":"naprendszer"},{"forms":["according to"],"lemma":"according to","pos":"preposition","en":"as said by someone","hu":"valaki szerint"},{"forms":["reached"],"lemma":"reach","pos":"verb","en":"to arrive at a place","hu":"elér (valahová)"},{"forms":["asteroid belt"],"lemma":"asteroid belt","pos":"noun","en":"the area of space between Mars and Jupiter where there are many asteroids","hu":"kisbolygóöv"},{"forms":["located"],"lemma":"located","pos":"adjective","en":"in a particular place","hu":"elhelyezkedő, található"},{"forms":["some"],"lemma":"some","pos":"adverb","en":"about (before a number)","hu":"mintegy, körülbelül"},{"forms":["luckily"],"lemma":"luckily","pos":"adverb","en":"used to say that something good happened by chance","hu":"szerencsére"},{"forms":["hurt"],"lemma":"hurt","pos":"adjective","en":"injured","hu