insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2009-okt-kozep-R3$mtr$, $mtr$[{"forms":["pet fish"],"lemma":"pet fish","pos":"noun","en":"a fish that you keep at home","hu":"díszhal, kedvenc hal"},{"forms":["learn new tricks"],"lemma":"learn new tricks","pos":"phrase","en":"to learn to do new clever things","hu":"új trükköket tanul","tip":"Utalás a mondásra: You can't teach an old dog new tricks."},{"forms":["goldfish"],"lemma":"goldfish","pos":"noun","en":"a small orange fish often kept at home","hu":"aranyhal","tip":"Többes száma is goldfish."},{"forms":["owner's"],"lemma":"owner","pos":"noun","en":"the person something belongs to","hu":"gazdi, tulajdonos"},{"forms":["hoops"],"lemma":"hoop","pos":"noun","en":"a ring made of metal, wood or plastic","hu":"karika"},{"forms":["tubes"],"lemma":"tube","pos":"noun","en":"a long, empty pipe","hu":"cső"},{"forms":["it all started"],"lemma":"it all started","pos":"phrase","en":"this is how the story began","hu":"az egész úgy kezdődött"},{"forms":["school fair"],"lemma":"school fair","pos":"noun","en":"an event at a school with games and stalls, where you can win prizes","hu":"iskolai vásár, iskolai bál"},{"forms":["noticed"],"lemma":"notice","pos":"verb","en":"to see something and pay attention to it","hu":"észrevesz"},{"forms":["react"],"lemma":"react","pos":"verb","en":"to do something because of what happens","hu":"reagál"},{"forms":["movements"],"lemma":"movement","pos":"noun","en":"a change of position of the body","hu":"mozdulat, mozgás"},{"forms":["wondered"],"lemma":"wonder","pos":"verb","en":"to ask yourself about something","hu":"elgondolkodik, kíváncsi (valamire)"},{"forms":["smarter"],"lemma":"smart","pos":"adjective","en":"clever","hu":"okosabb"},{"forms":["realized"],"lemma":"realize","pos":"verb","en":"to understand or know something","hu":"rájön, felfog","tip":"Amerikai írásmód; a brit: realise."},{"forms":["train"],"lemma":"train","pos":"verb","en":"to teach an animal to do so