insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2009-okt-kozep-R4$mtr$, $mtr$[{"forms":["speed limit"],"lemma":"speed limit","pos":"noun","en":"the fastest speed that you are allowed to drive on a road","hu":"sebességkorlátozás, megengedett legnagyobb sebesség"},{"forms":["necessarily"],"lemma":"necessarily","pos":"adverb","en":"(with not) not always; not in every case","hu":"feltétlenül, szükségszerűen"},{"forms":["safely"],"lemma":"safely","pos":"adverb","en":"in a way that is not dangerous","hu":"biztonságosan"},{"forms":["recently"],"lemma":"recently","pos":"adverb","en":"not long ago","hu":"nemrég, a minap"},{"forms":["residential road"],"lemma":"residential road","pos":"noun","en":"a street where there are mainly houses, not shops or offices","hu":"lakóövezeti utca"},{"forms":["incident"],"lemma":"incident","pos":"noun","en":"something unusual or unpleasant that happens","hu":"eset, incidens"},{"forms":["occurred"],"lemma":"occur","pos":"verb","en":"to happen","hu":"történik, előfordul"},{"forms":["second gear"],"lemma":"second gear","pos":"noun","en":"the second of the speeds that you choose in a car","hu":"második sebességfokozat, kettes"},{"forms":["in the normal course of events"],"lemma":"in the normal course of events","pos":"phrase","en":"usually, if nothing special happens","hu":"normál esetben, rendes körülmények között"},{"forms":["gone up to"],"lemma":"go up to","pos":"phrasal verb","en":"to change to a higher gear or number","hu":"felkapcsol (sebességbe), felmegy (valameddig)"},{"forms":["cruise"],"lemma":"cruise","pos":"verb","en":"to drive at a steady speed","hu":"egyenletes sebességgel halad"},{"forms":["activity"],"lemma":"activity","pos":"noun","en":"a situation in which a lot of things are happening","hu":"nyüzsgés, mozgás"},{"forms":["nearside"],"lemma":"nearside","pos":"adjective","en":"on the side of the road closest to the car (in Britain, the left side)","hu":"közelebbi oldali (Nagy-Britanniában a bal oldal