insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2010-maj-kozep-R3$mtr$, $mtr$[{"forms":["recycling"],"lemma":"recycling","pos":"noun","en":"treating used things like cans and bottles so that they can be used again","hu":"újrahasznosítás"},{"forms":["litter"],"lemma":"litter","pos":"noun","en":"paper, cans, bottles and other rubbish that people leave in public places","hu":"(eldobált) szemét"},{"forms":["funds"],"lemma":"fund","pos":"verb","en":"to pay for something","hu":"finanszíroz, fizeti valaminek a költségét","tip":"Itt ige (funds = fizeti). Főnévként (fund) alap, pénzalap."},{"forms":["honeymoon"],"lemma":"honeymoon","pos":"noun","en":"a holiday that a couple takes after their wedding","hu":"nászút"},{"forms":["for a while"],"lemma":"for a while","pos":"phrase","en":"for some time","hu":"egy ideje, egy ideig"},{"forms":["get married","married"],"lemma":"get married","pos":"phrase","en":"to become husband and wife","hu":"összeházasodik, megházasodik"},{"forms":["cover the cost"],"lemma":"cover the cost","pos":"phrase","en":"to have or give enough money to pay for something","hu":"fedezi a költséget"},{"forms":["dream"],"lemma":"dream","pos":"adjective","en":"the best you can imagine; the one you have always wanted","hu":"álom- (álomnászút)"},{"forms":["doing their shopping"],"lemma":"do your shopping","pos":"phrase","en":"to buy food and other things you need","hu":"bevásárol"},{"forms":["cans"],"lemma":"can","pos":"noun","en":"a metal container for drinks or food","hu":"konzervdoboz, (fém) doboz"},{"forms":["recycling centre"],"lemma":"recycling centre","pos":"noun","en":"a place where you take used things so that they can be used again","hu":"hulladékgyűjtő pont, újrahasznosító központ"},{"forms":["although"],"lemma":"although","pos":"conjunction","en":"despite the fact that","hu":"bár, habár"},{"forms":["cruise"],"lemma":"cruise","pos":"noun","en":"a holiday on a large ship that travels from place to place","hu":"hajóút, tengeri utazás"},{"forms":["couple"],"lemma":"couple","pos":"noun","en":"two people who are married or in a relationship","hu":"pár, házaspár"},{"forms":["collecting rubbish"],"lemma":"collect rubbish","pos":"phrase","en":"to pick up and gather things that people have thrown away","hu":"szemetet gyűjt"},{"forms":["home town"],"lemma":"home town","pos":"noun","en":"the town where you live or where you were born","hu":"szülőváros, lakóhely"},{"forms":["recycled items"],"lemma":"recycled item","pos":"noun","en":"a thing that has been taken away to be used again","hu":"újrahasznosított darab, tárgy"},{"forms":["earned"],"lemma":"earn","pos":"verb","en":"to get something as a result of what you have done","hu":"szerez, keres, kap (valamiért)"},{"forms":["reward point"],"lemma":"reward point","pos":"noun","en":"a point you get for buying or doing something, which you can later change for a prize","hu":"jutalompont, hűségpont"},{"forms":["converted into"],"lemma":"convert into","pos":"phrase","en":"to change something into something else","hu":"átvált, átalakít valamivé"},{"forms":["air miles"],"lemma":"air miles","pos":"noun","en":"points that you collect and can use to pay for flights","hu":"légi mérföld, repülőpont (ingyenes repülésre beváltható)"},{"forms":["almost"],"lemma":"almost","pos":"adverb","en":"nearly; not quite","hu":"majdnem, szinte"},{"forms":["at the very beginning"],"lemma":"at the very beginning","pos":"phrase","en":"right at the start","hu":"a legelején, legelőször"},{"forms":["concerned"],"lemma":"concerned","pos":"adjective","en":"worried","hu":"aggódó, aggódik"},{"forms":["achievable"],"lemma":"achievable","pos":"adjective","en":"possible to do or reach","hu":"elérhető, megvalósítható"},{"forms":["it's not to say"],"lemma":"it's not to say","pos":"phrase","en":"used to say that what you said before does not mean the next thing","hu":"ez nem azt jelenti, hogy; nem mintha"},{"forms":["pavements"],"lemma":"pavement","pos":"noun","en":"the path at the side of