insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2010-okt-emelt-R3$mtr$, $mtr$[{"forms":["autopilot","autopilots"],"lemma":"autopilot","pos":"noun","en":"a system that flies a plane automatically, without the pilot","hu":"robotpilóta"},{"forms":["hijack-proof"],"lemma":"hijack-proof","pos":"adjective","en":"designed so that no one can take control of it by force","hu":"eltérítésbiztos"},{"forms":["airliners","airliner"],"lemma":"airliner","pos":"noun","en":"a large plane that carries passengers","hu":"utasszállító repülőgép"},{"forms":["prevent"],"lemma":"prevent","pos":"verb","en":"to stop something from happening","hu":"megakadályoz, megelőz"},{"forms":["outrages"],"lemma":"outrage","pos":"noun","en":"a very cruel and shocking act","hu":"szörnyű tett, gaztett"},{"forms":["mechanism"],"lemma":"mechanism","pos":"noun","en":"a system of parts that work together in a machine","hu":"szerkezet, mechanizmus"},{"forms":["targets"],"lemma":"target","pos":"noun","en":"a place or object that someone wants to attack","hu":"célpont"},{"forms":["by remote control"],"lemma":"by remote control","pos":"phrase","en":"controlled from a distance, using radio signals","hu":"távirányítással"},{"forms":["in the event of"],"lemma":"in the event of","pos":"phrase","en":"if something happens","hu":"valami esetén"},{"forms":["giant"],"lemma":"giant","pos":"noun","en":"a very large and powerful company","hu":"óriás, óriásvállalat"},{"forms":["state-of-the-art"],"lemma":"state-of-the-art","pos":"adjective","en":"the most modern and advanced","hu":"legkorszerűbb, csúcstechnológiás"},{"forms":["activated"],"lemma":"activate","pos":"verb","en":"to make a machine or system start working","hu":"bekapcsol, működésbe hoz"},{"forms":["flicking a simple switch"],"lemma":"flick a switch","pos":"phrase","en":"to press a switch with a quick movement of your finger","hu":"egy kapcsolót átbillent, megnyom"},{"forms":["pressure sensors"],"lemma":"pressure sensor","pos":"noun","