insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2010-okt-kozep-R4$mtr$, $mtr$[{"forms":["fire safety"],"lemma":"fire safety","pos":"noun","en":"rules and actions to prevent fires and keep people safe from them","hu":"tűzbiztonság, tűzvédelem"},{"forms":["cleverest"],"lemma":"clever","pos":"adjective","en":"intelligent","hu":"okos (cleverest: a legokosabb)"},{"forms":["fire hazard"],"lemma":"fire hazard","pos":"noun","en":"something that can easily cause a fire","hu":"tűzveszély, tűzveszélyes dolog"},{"forms":["highest risk group"],"lemma":"high risk group","pos":"noun","en":"the group of people most likely to have a problem or cause danger","hu":"a legveszélyeztetettebb csoport, a legnagyobb kockázatú csoport"},{"forms":["firefighters"],"lemma":"firefighter","pos":"noun","en":"a person whose job is to put out fires","hu":"tűzoltó"},{"forms":["according to"],"lemma":"according to","pos":"phrase","en":"as said by someone","hu":"szerint, valaki szerint"},{"forms":["community fire officer"],"lemma":"community fire officer","pos":"noun","en":"a fire service worker who teaches people in an area about fire safety","hu":"körzeti tűzvédelmi tiszt"},{"forms":["considered"],"lemma":"consider","pos":"verb","en":"to think of someone or something in a particular way","hu":"tart valaminek, tekint valaminek"},{"forms":["foolish"],"lemma":"foolish","pos":"adjective","en":"stupid; not sensible","hu":"ostoba, buta"},{"forms":["caused by"],"lemma":"cause","pos":"verb","en":"to make something happen","hu":"okoz (caused by: valami okozta)"},{"forms":["tiredness"],"lemma":"tiredness","pos":"noun","en":"the feeling of being tired","hu":"fáradtság"},{"forms":["general stress"],"lemma":"general stress","pos":"noun","en":"the worry and pressure people feel in everyday life","hu":"általános stressz"},{"forms":["practical jokes"],"lemma":"practical joke","pos":"noun","en":"a trick played on someone to make others laugh","hu":"csíny, ugratás"},{"forms":["blamed for"],"lemma":"blame for","pos":"phrase","en":"to say that someone or something caused a problem","hu":"valakit hibáztat valamiért"},{"forms":["emergency calls"],"lemma":"emergency call","pos":"noun","en":"a phone call to the police, fire service or ambulance for urgent help","hu":"segélyhívás"},{"forms":["traffic sign"],"lemma":"traffic sign","pos":"noun","en":"a sign next to a road that gives information to drivers","hu":"közlekedési tábla"},{"forms":["melted"],"lemma":"melt","pos":"verb","en":"to change from solid to liquid because of heat","hu":"megolvad, megolvaszt"},{"forms":["gas hob"],"lemma":"gas hob","pos":"noun","en":"the top part of a cooker that uses gas, where you put pans","hu":"gáztűzhely (főzőlap)"},{"forms":["caught fire"],"lemma":"catch fire","pos":"phrase","en":"to start burning","hu":"lángra kap, meggyullad"},{"forms":["pointed out"],"lemma":"point out","pos":"phrasal verb","en":"to tell someone something they should know","hu":"rámutat, felhívja a figyelmet"},{"forms":["hoax calls"],"lemma":"hoax call","pos":"noun","en":"a false phone call to the emergency services, as a joke","hu":"vaklárma, álhívás"},{"forms":["consequences"],"lemma":"consequence","pos":"noun","en":"a result of something, often a bad one","hu":"következmény"},{"forms":["warned"],"lemma":"warn","pos":"verb","en":"to tell someone about a danger or a possible problem","hu":"figyelmeztet"},{"forms":["depending on"],"lemma":"depending on","pos":"phrase","en":"changing according to","hu":"valamitől függően"},{"forms":["gravity"],"lemma":"gravity","pos":"noun","en":"how serious something is","hu":"súlyosság","tip":"Más jelentése: gravitáció, nehézségi erő."},{"forms":["misbehaviour"],"lemma":"misbehaviour","pos":"noun","en":"bad behaviour","hu":"rossz viselkedés, helytelen viselkedés"},{"forms":["face"],"lemma":"face","pos":"verb","en":"to have to deal with something unpleasant","hu":"szembenéz valamivel, számolnia kell valamivel"},{"forms":["severe punishment"],"lemma":"severe punishment","pos":"noun","en":"a very serious penalty for doing something wrong","hu":"súlyos büntetés"},{"forms":["chiefs"],"lemma":"chief","pos":"noun","en":"a leader of an organization","hu":"vezető"},{"forms":["campaigns"],"lemma":"campaign","pos":"noun","en":"a planned set of activities to achieve something","hu":"kampány"},{"forms":["along with"],"lemma":"along with","pos":"phrase","en":"together with","hu":"valakivel együtt"},{"forms":["fire service"],"lemma":"fire service","pos":"noun","en":"the organization of firefighters","hu":"tűzoltóság"},{"forms":["students' union"],"lemma":"students' union","pos":"noun","en":"an organization that represents and helps the students of a university","hu":"diákszövetség, hallgatói önkormányzat"},{"forms":["spokesman"],"lemma":"spokesman","pos":"noun","en":"a person who speaks officially for an organization","hu":"szóvivő"},{"forms":["very seriously"],"lemma":"take something very seriously","pos":"phrase","en":"take something very seriously: to think that something matters a lot and treat it with great care","hu":"komolyan vesz"},{"forms":["consult"],"lemma":"consult","pos":"verb","en":"to ask someone for advice or information","hu":"konzultál, tanácsot kér"},{"forms":["representatives"],"lemma":"representative","pos":"noun","en":"a person who speaks or acts for a group","hu":"képviselő"},{"forms":["attended"],"lemma":"attend","pos":"verb","en":"here: to go to a place where there is an emergency","hu":"kivonul, kiszáll (helyszínre)"},{"forms":["blazes"],"lemma":"blaze","pos":"noun","en":"a large fire","hu":"tűz, tűzeset"},{"forms":["dropped"],"lemma":"drop","pos":"verb","en":"to become less in number","hu":"csökken"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2011-maj-emelt-R1$mtr$, $mtr$[{"forms":["just yet"],"lemma":"just yet","pos":"phrase","en":"now (used in negative sentences to say that something will happen later, but not now)","hu":"még (egyelőre ne)"},{"forms":["electronic reading devices"],"lemma":"electronic reading device","pos":"noun","en":"a small machine with a screen on which you can read books","hu":"elektronikus olvasóeszköz, e-könyv-olvasó"},{"forms":["reinvent"],"lemma":"reinvent","pos":"verb","en":"to change something so much that it seems completely new","hu":"újra feltalál, teljesen megújít"},{"forms":["have some way to go"],"lemma":"have some way to go","pos":"idiom","en":"to need more time or work before being good enough","hu":"még van mit fejlődnie, még hosszú út áll előtte"},{"forms":["highly evolved"],"lemma":"highly evolved","pos":"phrase","en":"developed over a long time until it is very advanced","hu":"igen fejlett, sokat fejlődött"},{"forms":["portable"],"lemma":"portable","pos":"adjective","en":"light and small enough to carry","hu":"hordozható"},{"forms":["shareable"],"lemma":"shareable","pos":"adjective","en":"easy to give to or use with other people","hu":"megosztható, kölcsönadható"},{"forms":["easily navigable"],"lemma":"navigable","pos":"adjective","en":"easy to find your way around in","hu":"könnyen kezelhető, könnyű benne eligazodni"},{"forms":["relatively"],"lemma":"relatively","pos":"adverb","en":"quite, when compared with other things","hu":"viszonylag"},{"forms":["have no difficulty imagining"],"lemma":"have no difficulty doing","pos":"phrase","en":"to be able to do something easily","hu":"könnyen el tudja képzelni","tip":"A vonzat: have difficulty + -ing alak."},{"forms":["indeed"],"lemma":"indeed","pos":"adverb","en":"used to add more information that supports what you said","hu":"sőt, valóban"},{"forms":["e-readers"],"lemma":"e-reader","pos":"noun","en":"an electronic device for reading books","hu":"e-könyv-olvasó"},{"forms":["ever since"],"lemma":"ever since","pos":"phrase","en":"all the time from a moment in the past until now","hu":"azóta, hogy; amióta csak"},{"forms":["slimmer"],"lemma":"slim","pos":"adjective","en":"thin","hu":"vékony (slimmer: vékonyabb)"},{"forms":["store"],"lemma":"store","pos":"verb","en":"to keep information on a computer or device","hu":"tárol"},{"forms":["out of print"],"lemma":"out of print","pos":"phrase","en":"no longer printed and sold by the publisher","hu":"elfogyott, már nem kapható (könyv)"},{"forms":["flick through"],"lemma":"flick through","pos":"phrasal verb","en":"to turn the pages of a book quickly","hu":"átlapoz, végiglapoz"},{"forms":["effortlessly"],"lemma":"effortlessly","pos":"adverb","en":"very easily, without trying hard","hu":"könnyedén, erőfeszítés nélkül"},{"forms":["passage"],"lemma":"passage","pos":"noun","en":"a short part of a book or text","hu":"szövegrész, részlet"},{"forms":["unfortunately"],"lemma":"unfortunately","pos":"adverb","en":"used to say that something is sad or disappointing","hu":"sajnos"},{"forms":["you are stuck with"],"lemma":"be stuck with","pos":"phrase","en":"to have to accept something you do not want because there is no other choice","hu":"kénytelen beérni valamivel, a nyakán marad valami"},{"forms":["for a start"],"lemma":"for a start","pos":"phrase","en":"used to give the first of several reasons","hu":"először is, kezdjük azzal, hogy"},{"forms":["roughly"],"lemma":"roughly","pos":"adverb","en":"about; not exactly","hu":"körülbelül, nagyjából"},{"forms":["paperback"],"lemma":"paperback","pos":"noun","en":"a book with a soft paper cover","hu":"puhafedeles könyv"},{"forms":["admit"],"lemma":"admit","pos":"verb","en":"to agree, often unwillingly, that something is true","hu":"beismer, elismer"},{"forms":["alone"],"lemma":"alone","pos":"adverb","en":"used after a noun to say that only this one thing is enough","hu":"egymagában, már önmagában"},{"forms":["non-starter"],"lemma":"non-starter","pos":"noun","en":"an idea or plan that has no chance of success","hu":"szóba sem jöhet, eleve kudarcra ítélt dolog"},{"forms":["entirely"],"lemma":"entirely","pos":"adverb","en":"completely","hu":"teljesen"},{"forms":["slimline"],"lemma":"slimline","pos":"adjective","en":"thinner and lighter than usual","hu":"karcsú, vékony kivitelű"},{"forms":["legibility"],"lemma":"legibility","pos":"noun","en":"how easy something is to read","hu":"olvashatóság"},{"forms":["it must be said"],"lemma":"it must be said","pos":"phrase","en":"used to admit that something is true","hu":"meg kell hagyni, el kell ismerni"},{"forms":["generation"],"lemma":"generation","pos":"noun","en":"all the products of a type that were made at about the same time","hu":"generáció, nemzedék (termékeké)"},{"forms":["backlit"],"lemma":"backlit","pos":"adjective","en":"with a light behind the screen","hu":"háttérvilágítású"},{"forms":["laptop"],"lemma":"laptop","pos":"noun","en":"a small computer that you can carry","hu":"laptop, hordozható számítógép"},{"forms":["strain your eyes"],"lemma":"strain your eyes","pos":"phrase","en":"to make your eyes tired by using them too much","hu":"megerőlteti a szemet, fárasztja a szemet"},{"forms":["written-by-geeks"],"lemma":"written-by-geeks","pos":"adjective","en":"written by computer experts, so it is hard for ordinary people to understand","hu":"számítógép-bolondok által írt (érthetetlen)"},{"forms":["facility"],"lemma":"facility","pos":"noun","en":"a function or feature of a machine","hu":"funkció, szolgáltatás"},{"forms":["silent"],"lemma":"silent","pos":"adjective","en":"here: giving no information about something","hu":"hallgat (róla), nem mond semmit"},{"forms":["work out"],"lemma":"work out","pos":"phrasal verb","en":"to find the answer to something by thinking","hu":"kitalál, rájön"},{"forms":["prototype"],"lemma":"prototype","pos":"noun","en":"the first model of a new machine, made to be tested","hu":"prototípus, kísérleti példány"},{"forms":["depends on"],"lemma":"depend on","pos":"phrasal verb","en":"to be decided by something","hu":"függ valamitől"},{"forms":["the signs are not hopeful"],"lemma":"the signs are not hopeful","pos":"phrase","en":"what we can see now suggests that things will not go well","hu":"a jelek nem biztatóak"},{"forms":["realize"],"lemma":"realize","pos":"verb","en":"to achieve something that was possible","hu":"kiaknáz, megvalósít"},{"forms":["theoretically"],"lemma":"theoretically","pos":"adverb","en":"in theory, but perhaps not in reality","hu":"elméletileg"},{"forms":["for this reason alone"],"lemma":"for this reason alone","pos":"phrase","en":"only because of this one reason","hu":"már csak emiatt is"},{"forms":["consider"],"lemma":"consider","pos":"verb","en":"to think about doing something","hu":"fontolgat, megfontol"},{"forms":["though"],"lemma":"though","pos":"adverb","en":"however","hu":"viszont, azonban"},{"forms":["additional"],"lemma":"additional","pos":"adjective","en":"extra; more than the basic","hu":"további, kiegészítő"},{"forms":["facilities"],"lemma":"facility","pos":"noun","en":"a function or feature of a machine","hu":"funkció, szolgáltatás"},{"forms":["average user"],"lemma":"average user","pos":"noun","en":"a normal person who uses something, not an expert","hu":"átlagfelhasználó"},{"forms":["make full use of"],"lemma":"make full use of","pos":"phrase","en":"to use something as much as possible","hu":"teljesen kihasznál"},{"forms":["all in all"],"lemma":"all in all","pos":"phrase","en":"used when you consider everything","hu":"mindent összevetve"},{"forms":["trends"],"lemma":"trend","pos":"noun","en":"the general direction in which things are changing","hu":"tendencia, irányzat"},{"forms":["sceptical"],"lemma":"sceptical","pos":"adjective","en":"having doubts that something is true or will be successful","hu":"kételkedő, szkeptikus"},{"forms":["fine old"],"lemma":"fine old","pos":"phrase","en":"good and respected because it has existed for a long time","hu":"régi, jó öreg, nemes múltú"},{"forms":["claim"],"lemma":"claim","pos":"verb","en":"to say that something is true, without proof","hu":"állít"},{"forms":["improved"],"lemma":"improve","pos":"verb","en":"to make something better","hu":"javít, tökéletesít"},{"forms":["dictionaries"],"lemma":"dictionary","pos":"noun","en":"a book that lists words and explains what they mean","hu":"szótár"},{"forms":["tube"],"lemma":"the Tube","pos":"noun","en":"the underground railway in London","hu":"a londoni metró"},{"forms":["current"],"lemma":"current","pos":"adjective","en":"of the present time","hu":"jelenlegi, mostani"},{"forms":["brilliant"],"lemma":"brilliant","pos":"adjective","en":"extremely good or clever","hu":"kitűnő, zseniális"},{"forms":["sunlight"],"lemma":"sunlight","pos":"noun","en":"the light from the sun","hu":"napfény"},{"forms":["in the dark"],"lemma":"in the dark","pos":"phrase","en":"where there is no light","hu":"a sötétben"},{"forms":["classic"],"lemma":"classic","pos":"adjective","en":"a typical example of something","hu":"tipikus, klasszikus (példa)"},{"forms":["clearly"],"lemma":"clearly","pos":"adverb","en":"without doubt; obviously","hu":"nyilvánvalóan, kétségkívül"},{"forms":["present version"],"lemma":"present version","pos":"noun","en":"the type of a product that is sold now","hu":"a jelenlegi változat"},{"forms":["advantage"],"lemma":"advantage","pos":"noun","en":"something that makes one thing better than others","hu":"előny"}]$mtr$::jsonb, $mtr$[{"forms":["over a decade ago"],"lemma":"decade","pos":"noun","en":"ten years; over ... ago = more than ... before now","hu":"több mint egy évtizede"},{"forms":["monster"],"lemma":"monster","pos":"noun","en":"here: something very big and heavy","hu":"szörnyeteg, óriási monstrum"},{"forms":["weighs in at"],"lemma":"weigh in at","pos":"phrasal verb","en":"to have a particular weight","hu":"valamennyit nyom, a súlya ..."},{"forms":["user’s manual"],"lemma":"user's manual","pos":"noun","en":"a small book that explains how to use a machine","hu":"használati útmutató, kézikönyv"},{"forms":["technical whiz"],"lemma":"technical whiz","pos":"noun","en":"a person who is very good with machines and computers","hu":"műszaki zseni, technikai csodabogár"},{"forms":["have the potential"],"lemma":"have the potential","pos":"phrase","en":"to have the ability to develop or do something in the future","hu":"megvan benne a lehetőség, képes lehet valamire"},{"forms":["ever published"],"lemma":"publish","pos":"verb","en":"to print a book and offer it for sale","hu":"valaha kiadott, valaha megjelent"},{"forms":["weight"],"lemma":"weight","pos":"noun","en":"how heavy something is","hu":"súly"},{"forms":["development"],"lemma":"development","pos":"noun","en":"work to make a product better","hu":"fejlesztés"}]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2011-maj-emelt-R2$mtr$, $mtr$[{"forms":["investigators"],"lemma":"investigator","pos":"noun","en":"someone whose job is to find out the facts about a crime","hu":"nyomozó, vizsgáló"},{"forms":["trade"],"lemma":"trade","pos":"noun","en":"the buying and selling of things","hu":"kereskedelem"},{"forms":["endangered animals"],"lemma":"endangered animal","pos":"noun","en":"an animal that may soon disappear from the world","hu":"veszélyeztetett állat"},{"forms":["endangered"],"lemma":"endangered","pos":"adjective","en":"in danger of disappearing from the world","hu":"veszélyeztetett"},{"forms":["wipe out"],"lemma":"wipe out","pos":"phrasal verb","en":"to destroy something completely","hu":"kiirt, eltöröl a föld színéről"},{"forms":["entire"],"lemma":"entire","pos":"adjective","en":"whole; complete","hu":"egész, teljes"},{"forms":["species"],"lemma":"species","pos":"noun","en":"a group of animals or plants of the same kind","hu":"faj","tip":"Egyes és többes számban is species."},{"forms":["supposedly"],"lemma":"supposedly","pos":"adverb","en":"as people say or believe, although it may not be true","hu":"állítólag, elvileg"},{"forms":["traded"],"lemma":"trade","pos":"verb","en":"to buy and sell","hu":"kereskednek vele, adják-veszik"},{"forms":["openly"],"lemma":"openly","pos":"adverb","en":"without hiding anything","hu":"nyíltan"},{"forms":["exotic pets"],"lemma":"exotic pet","pos":"noun","en":"an unusual animal from a faraway country kept at home","hu":"egzotikus háziállat"},{"forms":["wildlife crime"],"lemma":"wildlife crime","pos":"noun","en":"illegal activities against wild animals and plants, e.g. hunting or selling them","hu":"vadvilág elleni bűnözés"},{"forms":["charity"],"lemma":"charity","pos":"noun","en":"an organization that collects money to help people or animals","hu":"jótékonysági szervezet"},{"forms":["investigation"],"lemma":"investigation","pos":"noun","en":"an official examination of the facts","hu":"vizsgálat, nyomozás"},{"forms":["shocking"],"lemma":"shocking","pos":"adjective","en":"very surprising and upsetting","hu":"megdöbbentő"},{"forms":["hand-reared"],"lemma":"hand-reared","pos":"adjective","en":"fed and looked after by people from when it was very young","hu":"kézzel nevelt, ember által felnevelt"},{"forms":["adolescent"],"lemma":"adolescent","pos":"adjective","en":"young; no longer a baby but not yet adult","hu":"kamasz, fiatal (nem teljesen kifejlett)"},{"forms":["primates"],"lemma":"primate","pos":"noun","en":"a member of the group of animals that includes monkeys, apes and humans","hu":"főemlős"},{"forms":["falcons"],"lemma":"falcon","pos":"noun","en":"a fast bird that kills other birds and animals for food","hu":"sólyom"},{"forms":["seahorses"],"lemma":"seahorse","pos":"noun","en":"a small sea fish with a head shaped like a horse's head","hu":"csikóhal"},{"forms":["shells","turtle-shells"],"lemma":"shell","pos":"noun","en":"the hard outer cover of an animal such as a turtle","hu":"páncél, teknő"},{"forms":["turtles"],"lemma":"turtle","pos":"noun","en":"an animal with a hard shell that lives mostly in water","hu":"teknős"},{"forms":["advertised"],"lemma":"advertise","pos":"verb","en":"to tell the public about something that is for sale","hu":"hirdet"},{"forms":["capture"],"lemma":"capture","pos":"verb","en":"to catch an animal and keep it","hu":"befog, elfog"},{"forms":["to order"],"lemma":"to order","pos":"phrase","en":"specially for a customer who has asked for it","hu":"megrendelésre"},{"forms":["guaranteed"],"lemma":"guaranteed","pos":"adjective","en":"certain to be true","hu":"biztosan, garantáltan"},{"forms":["shawls"],"lemma":"shawl","pos":"noun","en":"a large piece of cloth worn around the shoulders","hu":"sál, kendő"},{"forms":["antelope"],"lemma":"antelope","pos":"noun","en":"a wild animal like a deer that can run fast, with long horns","hu":"antilop"},{"forms":["stuffed"],"lemma":"stuffed","pos":"adjective","en":"a dead animal that has been filled with material so it looks alive","hu":"kitömött, preparált"},{"forms":["suspiciously"],"lemma":"suspiciously","pos":"adverb","en":"in a way that makes you think something is wrong","hu":"gyanúsan"},{"forms":["revolutionised"],"lemma":"revolutionise","pos":"verb","en":"to change something completely","hu":"forradalmasít"},{"forms":["deal in"],"lemma":"deal in","pos":"phrasal verb","en":"to buy and sell a particular type of goods","hu":"kereskedik valamivel"},{"forms":["illegal"],"lemma":"illegal","pos":"adjective","en":"against the law","hu":"illegális, törvénytelen"},{"forms":["wildlife"],"lemma":"wildlife","pos":"noun","en":"wild animals and plants","hu":"vadvilág, vadon élő állatok"},{"forms":["according to"],"lemma":"according to","pos":"phrase","en":"as stated by","hu":"szerint"},{"forms":["rivals"],"lemma":"rival","pos":"verb","en":"to be as big or as good as something else","hu":"vetekszik, felveszi a versenyt valamivel"},{"forms":["in scale"],"lemma":"in scale","pos":"phrase","en":"in size","hu":"méretét tekintve"},{"forms":["devastating"],"lemma":"devastating","pos":"adjective","en":"causing a lot of damage","hu":"pusztító, katasztrofális"},{"forms":["implications"],"lemma":"implication","pos":"noun","en":"a possible effect or result","hu":"következmény, kihatás"},{"forms":["wildlife conservation"],"lemma":"wildlife conservation","pos":"noun","en":"the protection of wild animals and plants","hu":"természetvédelem, vadvédelem"},{"forms":["animal welfare"],"lemma":"animal welfare","pos":"noun","en":"the health and good treatment of animals","hu":"állatjólét, az állatok védelme"},{"forms":["populations"],"lemma":"population","pos":"noun","en":"all the animals of one type that live in an area","hu":"állomány, populáció"},{"forms":["risk"],"lemma":"risk","pos":"verb","en":"to be in danger of something bad happening","hu":"kockáztat, fenyegeti valami"},{"forms":["overexploitation"],"lemma":"overexploitation","pos":"noun","en":"using a natural thing so much that there is little or nothing left","hu":"túlzott kizsákmányolás, túlhasználat"},{"forms":["immensely"],"lemma":"immensely","pos":"adverb","en":"very much","hu":"rendkívül, mérhetetlenül"},{"forms":["in transit"],"lemma":"in transit","pos":"phrase","en":"while being carried from one place to another","hu":"szállítás közben"},{"forms":["captivity"],"lemma":"captivity","pos":"noun","en":"the state of being kept in a cage, not free","hu":"fogság"},{"forms":["results in"],"lemma":"result in","pos":"phrasal verb","en":"to cause something","hu":"eredményez, vezet valamihez"},{"forms":["the wild"],"lemma":"the wild","pos":"noun","en":"natural areas where animals live free","hu":"vadon, természetes élőhely"},{"forms":["anonymous"],"lemma":"anonymous","pos":"adjective","en":"without anyone knowing who you are","hu":"névtelen, anonim"},{"forms":["unscrupulous"],"lemma":"unscrupulous","pos":"adjective","en":"behaving dishonestly and not caring if it is wrong","hu":"gátlástalan, lelkiismeretlen"},{"forms":["criminal gangs"],"lemma":"criminal gang","pos":"noun","en":"a group of people who commit crimes together","hu":"bűnbanda"},{"forms":["taking advantage of"],"lemma":"take advantage of","pos":"phrase","en":"to use a situation for your own good, often unfairly","hu":"kihasznál valamit"},{"forms":["black market"],"lemma":"black market","pos":"noun","en":"illegal buying and selling","hu":"feketepiac"},{"forms":["traded away"],"lemma":"trade away","pos":"phrasal verb","en":"to lose something valuable by selling it","hu":"elkótyavetyél, eladással feláldoz"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2011-maj-emelt-R3$mtr$, $mtr$[{"forms":["glimpse"],"lemma":"glimpse","pos":"noun","en":"a short look at something","hu":"bepillantás, futó pillantás"},{"forms":["underground chamber"],"lemma":"underground chamber","pos":"noun","en":"a large room or space under the ground","hu":"földalatti terem, üreg"},{"forms":["crystals"],"lemma":"crystal","pos":"noun","en":"a hard clear mineral that forms in regular shapes","hu":"kristály"},{"forms":["selenite"],"lemma":"selenite","pos":"noun","en":"a clear type of mineral (a form of gypsum) that forms crystals","hu":"szelenit (kristályos gipsz)"},{"forms":["subterranean"],"lemma":"subterranean","pos":"adjective","en":"under the ground","hu":"földalatti"},{"forms":["spectacle"],"lemma":"spectacle","pos":"noun","en":"something wonderful to look at","hu":"látványosság, látvány"},{"forms":["virtually"],"lemma":"virtually","pos":"adverb","en":"almost","hu":"gyakorlatilag, szinte"},{"forms":["humidity"],"lemma":"humidity","pos":"noun","en":"the amount of water in the air","hu":"páratartalom"},{"forms":["added on top"],"lemma":"add on top","pos":"phrase","en":"to come in addition to something else","hu":"ráadásként, ehhez jön még"},{"forms":["potential killer"],"lemma":"potential killer","pos":"noun","en":"something that could cause death","hu":"potenciálisan halálos dolog"},{"forms":["lungs"],"lemma":"lung","pos":"noun","en":"one of the two organs in your chest that you breathe with","hu":"tüdő"},{"forms":["encounters"],"lemma":"encounter","pos":"verb","en":"to meet or touch something","hu":"találkozik valamivel, érintkezik"},{"forms":["fluid"],"lemma":"fluid","pos":"noun","en":"a liquid","hu":"folyadék"},{"forms":["condense"],"lemma":"condense","pos":"verb","en":"to change from a gas into a liquid when cooling","hu":"lecsapódik, kicsapódik"},{"forms":["miners"],"lemma":"miner","pos":"noun","en":"a person who works under the ground digging for metal or coal","hu":"bányász"},{"forms":["silver mine"],"lemma":"silver mine","pos":"noun","en":"a place under the ground where people dig for silver","hu":"ezüstbánya"},{"forms":["broke through"],"lemma":"break through","pos":"phrasal verb","en":"to make a hole in a wall and get to the other side","hu":"áttör"},{"forms":["cavern"],"lemma":"cavern","pos":"noun","en":"a large cave","hu":"barlang, nagy üreg"},{"forms":["astounded"],"lemma":"astounded","pos":"adjective","en":"very surprised","hu":"megdöbbent, elképedt"},{"forms":["enormous"],"lemma":"enormous","pos":"adjective","en":"very big","hu":"hatalmas, óriási"},{"forms":["overcome by"],"lemma":"be overcome by","pos":"phrase","en":"to become weak or ill because of something","hu":"erőt vesz rajta valami, legyűri valami"},{"forms":["conditions"],"lemma":"condition","pos":"noun","en":"the situation or environment in which something happens","hu":"körülmény, viszonyok"},{"forms":["hairy"],"lemma":"hairy","pos":"adjective","en":"(informal) frightening and dangerous","hu":"(biz.) hajmeresztő, ijesztő","tip":"Alapjelentése: szőrös."},{"forms":["video footage"],"lemma":"video footage","pos":"noun","en":"a piece of film showing an event","hu":"videófelvétel"},{"forms":["on the verge of"],"lemma":"on the verge of","pos":"phrase","en":"very close to doing something","hu":"valaminek a határán, küszöbén"},{"forms":["losing consciousness"],"lemma":"lose consciousness","pos":"phrase","en":"to stop being awake and aware, as if asleep","hu":"elveszti az eszméletét"},{"forms":["breathing system"],"lemma":"breathing system","pos":"noun","en":"equipment that gives you air to breathe","hu":"légzőkészülék"},{"forms":["feeds"],"lemma":"feed","pos":"verb","en":"to send something steadily into something","hu":"juttat, vezet (levegőt)"},{"forms":["do without"],"lemma":"do without","pos":"phrasal verb","en":"to manage without something","hu":"megvan nélküle, nélkülöz"},{"forms":["keeling over"],"lemma":"keel over","pos":"phrasal verb","en":"to fall ov