insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2014-maj-emelt-R1$mtr$, $mtr$[{"forms":["took a wrong turn"],"lemma":"take a wrong turn","pos":"phrase","en":"to go the wrong way at a crossing or corner","hu":"rossz irányba fordul, eltéved"},{"forms":["wrong turn"],"lemma":"wrong turn","pos":"noun","en":"turning the wrong way when driving","hu":"rossz kanyar, eltévedés"},{"forms":["wondered whether"],"lemma":"wonder whether","pos":"phrase","en":"to think about something and ask yourself if it is true","hu":"elgondolkodik, vajon"},{"forms":["GPS tracker"],"lemma":"GPS tracker","pos":"noun","en":"a device in a car that shows you the way using satellites","hu":"GPS, navigációs készülék"},{"forms":["smart"],"lemma":"smart","pos":"adjective","en":"clever","hu":"okos"},{"forms":["sit back"],"lemma":"sit back","pos":"phrasal verb","en":"to relax in your seat","hu":"hátradől"},{"forms":["prepare to"],"lemma":"prepare to","pos":"phrase","en":"to get ready to do something","hu":"készülj fel arra, hogy"},{"forms":["involve"],"lemma":"involve","pos":"verb","en":"to include something as a part","hu":"magában foglal, jár valamivel"},{"forms":["multiple"],"lemma":"multiple","pos":"adjective","en":"many","hu":"több, sokféle"},{"forms":["traffic signs"],"lemma":"traffic sign","pos":"noun","en":"a sign next to a road that gives information to drivers","hu":"közlekedési tábla"},{"forms":["gas bill"],"lemma":"gas bill","pos":"noun","en":"the money you pay for fuel for your car (American English: gas = petrol)","hu":"benzinszámla, üzemanyagköltség","tip":"Itt a gas nem földgáz, hanem az amerikai angolban benzin."},{"forms":["leave you gasping"],"lemma":"leave someone gasping","pos":"idiom","en":"to shock someone so much that they can hardly breathe","hu":"elakad tőle a lélegzeted"},{"forms":["to start out"],"lemma":"to start out","pos":"phrase","en":"at the beginning","hu":"kezdetben, először is"},{"forms":["pick up"],"lemma":"pick up","pos":"phrasal verb",