insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2015-maj-kozep-R1$mtr$, $mtr$[{"forms":["invented"],"lemma":"invent","pos":"verb","en":"to make or design something that did not exist before","hu":"feltalált, kitalált"},{"forms":["loom band"],"lemma":"loom band","pos":"noun","en":"a small coloured rubber ring that children use to make bracelets","hu":"loom gumi, gumikarkötő-gumi"},{"forms":["growing up"],"lemma":"grow up","pos":"phrasal verb","en":"to change from a child into an adult","hu":"felnő; growing up = gyerekkoromban, amikor felnőttem"},{"forms":["creative"],"lemma":"creative","pos":"adjective","en":"good at thinking of new ideas and making new things","hu":"kreatív, ötletes"},{"forms":["kites"],"lemma":"kite","pos":"noun","en":"a light toy that flies in the wind at the end of a long string","hu":"sárkány (papírsárkány)"},{"forms":["sand"],"lemma":"sand","pos":"noun","en":"the very small grains you find on beaches and in deserts","hu":"homok"},{"forms":["rubber-tree"],"lemma":"rubber tree","pos":"noun","en":"a tropical tree that gives the liquid used to make rubber","hu":"kaucsukfa, gumifa"},{"forms":["plantation"],"lemma":"plantation","pos":"noun","en":"a large farm in a hot country where one kind of tree or plant is grown","hu":"ültetvény"},{"forms":["thick"],"lemma":"thick","pos":"adjective","en":"here: not flowing easily, like honey","hu":"sűrű"},{"forms":["produce"],"lemma":"produce","pos":"verb","en":"to make something","hu":"előállít, termel"},{"forms":["natural rubber"],"lemma":"natural rubber","pos":"noun","en":"a soft material that stretches, made from the liquid of a tree","hu":"természetes gumi, kaucsuk"},{"forms":["dreamed of"],"lemma":"dream of","pos":"phrase","en":"to wish for something very much","hu":"arról álmodott, hogy"},{"forms":["engineer"],"lemma":"engineer","pos":"noun","en":"a person who designs machines, roads, bridges or electrical systems","hu":"mérnök"},{"forms":["abroad"],"lemma":"abroad","pos":"ad