insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2015-okt-kozep-R1$mtr$, $mtr$[{"forms":["run"],"lemma":"run","pos":"verb","en":"to manage a business and be in charge of it","hu":"vezet, üzemeltet"},{"forms":["look after"],"lemma":"look after","pos":"phrasal verb","en":"to be responsible for something and take care of it","hu":"felel valamiért, gondoskodik valamiről"},{"forms":["day-to-day"],"lemma":"day-to-day","pos":"adjective","en":"happening every day as a normal part of work","hu":"napi, mindennapos"},{"forms":["operations"],"lemma":"operation","pos":"noun","en":"the work and activities of a company","hu":"működés, ügymenet"},{"forms":["tea bag"],"lemma":"tea bag","pos":"noun","en":"a small paper bag with tea leaves in it","hu":"teafilter"},{"forms":["accounts"],"lemma":"accounts","pos":"noun","en":"the record of money that a company gets and spends","hu":"könyvelés, pénzügyek"},{"forms":["planned"],"lemma":"plan","pos":"verb","en":"to decide in advance what you will do","hu":"tervezett"},{"forms":["career"],"lemma":"career","pos":"noun","en":"the job or series of jobs that you do during your working life","hu":"pálya, karrier"},{"forms":["hospitality"],"lemma":"hospitality","pos":"noun","en":"the business of hotels, restaurants and services for guests","hu":"vendéglátás, vendéglátóipar"},{"forms":["fell into it"],"lemma":"fall into something","pos":"phrase","en":"to start doing a job by chance, without planning it","hu":"véletlenül belecsöppent"},{"forms":["passion"],"lemma":"passion","pos":"noun","en":"a very strong love or interest for something","hu":"szenvedély"},{"forms":["interaction"],"lemma":"interaction","pos":"noun","en":"talking and working together with other people","hu":"kapcsolattartás, érintkezés"},{"forms":["satisfying"],"lemma":"satisfying","pos":"adjective","en":"making you feel happy because you get what you wanted","hu":"kielégítő, örömet adó"},{"forms":["after all"],"lemma":"after all","pos":"phrase","en":"us