insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2016-okt-emelt-R3$mtr$, $mtr$[{"forms":["prison"],"lemma":"prison","pos":"noun","en":"a building where criminals are kept","hu":"börtön"},{"forms":["given it up"],"lemma":"give up","pos":"phrasal verb","en":"to stop doing something","hu":"abbahagyta, felhagyott vele"},{"forms":["lost the stomach for"],"lemma":"lose the stomach for","pos":"idiom","en":"to no longer have the wish or courage to do something","hu":"elment a kedve valamitől, nincs már gyomra hozzá"},{"forms":["damned"],"lemma":"damned","pos":"adjective","en":"a rude word used to show that you are angry or tired of something","hu":"átkozott, nyavalyás"},{"forms":["business"],"lemma":"business","pos":"noun","en":"here: a situation or activity","hu":"dolog, ügy"},{"forms":["excluded"],"lemma":"exclude","pos":"verb","en":"to not allow someone to stay in a class or place","hu":"kizárt, kitett (az óráról)"},{"forms":["no matter how"],"lemma":"no matter how","pos":"phrase","en":"it does not change anything how...","hu":"akármennyire, bármilyen"},{"forms":["confidence"],"lemma":"confidence","pos":"noun","en":"the belief that you can do things well","hu":"önbizalom, magabiztosság"},{"forms":["duvet"],"lemma":"duvet","pos":"noun","en":"a thick soft cover for a bed","hu":"paplan"},{"forms":["hug"],"lemma":"hug","pos":"noun","en":"the act of putting your arms around someone","hu":"ölelés"},{"forms":["retire"],"lemma":"retire","pos":"verb","en":"to stop working, usually because you are old","hu":"nyugdíjba megy"},{"forms":["suppose"],"lemma":"suppose","pos":"verb","en":"to think that something is probably true","hu":"feltételez, azt hiszem"},{"forms":["creeping up on"],"lemma":"creep up on","pos":"phrasal verb","en":"to happen slowly so that you do not notice it at first","hu":"észrevétlenül közelít, lassan eluralkodik valakin"},{"forms":["for a while"],"lemma":"for a while","pos":"phrase","en":"for some time","hu":"egy ideje, egy ideig"},