insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2017-okt-kozep-R1$mtr$, $mtr$[{"forms":["interview"],"lemma":"interview","pos":"noun","en":"a meeting where someone answers questions, for example for a newspaper or a website","hu":"interjú, beszélgetés"},{"forms":["firefighter"],"lemma":"firefighter","pos":"noun","en":"a person whose job is to stop fires and save people","hu":"tűzoltó"},{"forms":["everything from"],"lemma":"everything from ... to","pos":"phrase","en":"all kinds of things, starting with one thing and ending with a very different one","hu":"mindent ...-tól ...-ig"},{"forms":["fighting"],"lemma":"fight","pos":"verb","en":"to try to stop something bad, here a fire","hu":"(tüzet) olt, küzd valami ellen"},{"forms":["grass fires"],"lemma":"grass fire","pos":"noun","en":"a fire in a field where grass is burning","hu":"fűtűz, avartűz"},{"forms":["rubbish fires"],"lemma":"rubbish fire","pos":"noun","en":"a fire where rubbish (things people throw away) is burning","hu":"szemét égése, szeméttűz"},{"forms":["emergency medical technician"],"lemma":"emergency medical technician","pos":"noun","en":"a person trained to give medical help quickly, before a patient gets to hospital","hu":"mentőtiszt, mentős (sürgősségi egészségügyi szakember)"},{"forms":["medical calls"],"lemma":"medical call","pos":"noun","en":"a call for help when someone is ill or hurt","hu":"mentőhívás, orvosi segélyhívás"},{"forms":["any time"],"lemma":"any time","pos":"phrase","en":"at every hour of the day or night","hu":"bármikor, a nap bármely szakában"},{"forms":["high school education"],"lemma":"high school education","pos":"noun","en":"the studies you finish at a secondary school, at about the age of 18","hu":"középiskolai végzettség, érettségi"},{"forms":["clean police record"],"lemma":"clean police record","pos":"phrase","en":"if your police record is clean, you have never broken the law","hu":"büntetlen előélet, tiszta erkölcsi bizonyítvány"},{"forms":["a lot of heart"],"lemma":"a lot of heart","pos":"idiom","en":"a lot of courage, kindness and love for the job","hu":"nagy szív, sok bátorság és elhivatottság"},{"forms":["emergency medical service"],"lemma":"emergency medical service","pos":"noun","en":"the organization that sends ambulances and helps sick or injured people quickly","hu":"mentőszolgálat"},{"forms":["applied"],"lemma":"apply","pos":"verb","en":"to ask officially for a job, usually by writing a letter or filling in a form","hu":"jelentkezik, megpályáz (állást)"},{"forms":["took the test"],"lemma":"take a test","pos":"phrase","en":"to do an exam that shows how good you are","hu":"vizsgát tesz, letesz egy vizsgát"},{"forms":["community"],"lemma":"community","pos":"noun","en":"the people who live in the same area","hu":"közösség, a helyi lakosság"},{"forms":["colleagues"],"lemma":"colleague","pos":"noun","en":"a person you work with","hu":"kolléga, munkatárs"},{"forms":["work schedule"],"lemma":"work schedule","pos":"noun","en":"the plan that shows when you work and when you are free","hu":"munkabeosztás, munkarend"},{"forms":["24 hours on"],"lemma":"24 hours on, 48 off","pos":"phrase","en":"you work for 24 hours, then you are free for 48 hours","hu":"24 óra szolgálat, 48 óra szabad"},{"forms":["shifts"],"lemma":"shift","pos":"noun","en":"a fixed period of time when a group of workers is at work","hu":"műszak, szolgálat"},{"forms":["kids"],"lemma":"kid","pos":"noun","en":"a child (informal)","hu":"gyerek"},{"forms":["being able to"],"lemma":"be able to","pos":"phrase","en":"to have the ability to do something","hu":"képesnek lenni valamire, tudni valamit"},{"forms":["keep control over"],"lemma":"keep control over","pos":"phrase","en":"to stay in charge of something and not let it become too strong","hu":"uralkodik valamin, kordában tart"},{"forms":["emotions"],"lemma":"emotion","pos":"noun","en":"a strong feeling like fear, anger or love","hu":"érzelem"},{"forms":["stressful"],"lemma":"stressful","pos":"adjective","en":"making you feel worried and nervous","hu":"megterhelő, stresszes"},{"forms":["tend to"],"lemma":"tend to","pos":"phrase","en":"to usually do something or be likely to do it","hu":"hajlamos valamire, általában (így tesz)"},{"forms":["get excited"],"lemma":"get excited","pos":"phrase","en":"to become nervous and full of energy so that you cannot think calmly","hu":"felizgatja magát, izgatott lesz"},{"forms":["step back"],"lemma":"step back","pos":"phrasal verb","en":"to stop for a moment and think about a situation calmly","hu":"hátralép, kívülről ránéz a helyzetre"},{"forms":["take a look at"],"lemma":"take a look at","pos":"phrase","en":"to look at something carefully","hu":"megnéz, szemügyre vesz"},{"forms":["act"],"lemma":"act","pos":"verb","en":"to do something in a situation","hu":"cselekszik, közbelép"},{"forms":["hardest"],"lemma":"hard","pos":"adjective","en":"the most difficult","hu":"a legnehezebb"},{"forms":["right now"],"lemma":"right now","pos":"phrase","en":"at the present time","hu":"jelenleg, most"},{"forms":["guy"],"lemma":"guy","pos":"noun","en":"a man (informal)","hu":"fickó, srác, ember"},{"forms":["on the job"],"lemma":"on the job","pos":"phrase","en":"working in a particular job","hu":"a munkában, a szakmában (eltöltött idő)"},{"forms":["vacation"],"lemma":"vacation","pos":"noun","en":"time when you do not have to go to work (American English)","hu":"szabadság, vakáció","tip":"Amerikai angol; a britek a holiday szót használják."},{"forms":["per year"],"lemma":"per year","pos":"phrase","en":"in each year","hu":"évente, egy évben"},{"forms":["in fact"],"lemma":"in fact","pos":"phrase","en":"used to say what is really true, often the opposite of what people think","hu":"valójában, ami azt illeti"},{"forms":["hardly ever"],"lemma":"hardly ever","pos":"phrase","en":"almost never","hu":"szinte soha, alig"},{"forms":["even if"],"lemma":"even if","pos":"conjunction","en":"it does not matter whether something is true or happens","hu":"még ak