insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2017-okt-kozep-R2$mtr$, $mtr$[{"forms":["Bubble Wrap"],"lemma":"bubble wrap","pos":"noun","en":"plastic sheets with small bubbles of air, used to protect things when you send them","hu":"buborékfólia, légpárnás fólia"},{"forms":["original"],"lemma":"original","pos":"adjective","en":"existing at the beginning, before any changes","hu":"eredeti"},{"forms":["purpose"],"lemma":"purpose","pos":"noun","en":"what something is made or used for","hu":"cél, rendeltetés"},{"forms":["nothing like"],"lemma":"nothing like","pos":"phrase","en":"completely different from","hu":"egyáltalán nem olyan, mint"},{"forms":["engineer"],"lemma":"engineer","pos":"noun","en":"a person who designs machines, roads, bridges or other things","hu":"mérnök"},{"forms":["Swiss"],"lemma":"Swiss","pos":"adjective","en":"from Switzerland","hu":"svájci"},{"forms":["inventor"],"lemma":"inventor","pos":"noun","en":"a person who makes something completely new that did not exist before","hu":"feltaláló"},{"forms":["wallpaper"],"lemma":"wallpaper","pos":"noun","en":"thick paper that you stick on the walls of a room to decorate them","hu":"tapéta"},{"forms":["however"],"lemma":"however","pos":"adverb","en":"used to add something that is different from what you said before","hu":"azonban, viszont"},{"forms":["either"],"lemma":"either","pos":"adverb","en":"used after a negative to mean 'also not'","hu":"sem (tagadó mondat végén)","tip":"Tagadó mondatban a too helyett either áll: didn't become popular, either = ez sem lett népszerű."},{"forms":["presented"],"lemma":"present","pos":"verb","en":"to show or explain something to a group of people","hu":"bemutat, előad"},{"forms":["demonstrated"],"lemma":"demonstrate","pos":"verb","en":"to show how something works","hu":"bemutat, szemléltet"},{"forms":["protective"],"lemma":"protective","pos":"adjective","en":"keeping something safe from damage","hu":"védő, védelmet nyújtó"},{"forms":["abilities"],"lemma":"ability","pos":"noun","en":"what someone or something is able to do","hu":"képesség, tulajdonság"},{"forms":["since then"],"lemma":"since then","pos":"phrase","en":"from that time until now","hu":"azóta"},{"forms":["sales"],"lemma":"sales","pos":"noun","en":"the total amount of money a company gets from selling things","hu":"forgalom, árbevétel"},{"forms":["net profit"],"lemma":"net profit","pos":"noun","en":"the money a company earns after all costs are paid","hu":"nettó nyereség, tiszta haszon"},{"forms":["worth"],"lemma":"worth","pos":"noun","en":"an amount of something that has a value of (a sum of money)","hu":"értékű, értékben"},{"forms":["annually"],"lemma":"annually","pos":"adverb","en":"every year","hu":"évente"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2017-okt-kozep-R3$mtr$, $mtr$[{"forms":["Archbishop"],"lemma":"archbishop","pos":"noun","en":"a very important priest who is the leader of the church in a large area","hu":"érsek"},{"forms":["fixed"],"lemma":"fixed","pos":"adjective","en":"not changing; always the same","hu":"rögzített, állandó"},{"forms":["announcement"],"lemma":"announcement","pos":"noun","en":"an official public statement about something","hu":"bejelentés"},{"forms":["Anglican church"],"lemma":"Anglican church","pos":"noun","en":"the official Christian church of England","hu":"anglikán egyház"},{"forms":["currently"],"lemma":"currently","pos":"adverb","en":"at the present time","hu":"jelenleg"},{"forms":["high-ranking"],"lemma":"high-ranking","pos":"adjective","en":"having an important position in an organization","hu":"magas rangú"},{"forms":["members"],"lemma":"member","pos":"noun","en":"a person who belongs to a group or an organization","hu":"tag"},{"forms":["agree on"],"lemma":"agree on","pos":"phrasal verb","en":"to decide something together with other people","hu":"megegyezik valamiben"},{"forms":["act of Parliament"],"lemma":"act of Parliament","pos":"noun","en":"a law that the British parliament has made","hu":"parlamenti törvény"},{"forms":["passed"],"lemma":"pass","pos":"verb","en":"if a parliament passes a law, it officially accepts it","hu":"(törvényt) elfogad, megszavaz"},{"forms":["allowed for"],"lemma":"allow for","pos":"phrasal verb","en":"to make something possible","hu":"lehetővé tesz"},{"forms":["activated"],"lemma":"activate","pos":"verb","en":"to make something start working","hu":"életbe léptet, működésbe hoz"},{"forms":["remained"],"lemma":"remain","pos":"verb","en":"to stay in the same state","hu":"marad"},{"forms":["variable"],"lemma":"variable","pos":"adjective","en":"changing; not always the same","hu":"változó, mozgó"},{"forms":["determined by"],"lemma":"be determined by","pos":"phrase","en":"to be decided or controlled by something","hu":"valami határozza meg"},{"forms":["cycle"],"lemma":"cycle","pos":"noun","en":"a series of events that happen again and again in the same order","hu":"ciklus, körforgás (itt: a hold fázisai)"},{"forms":["issue"],"lemma":"issue","pos":"noun","en":"a subject or problem that people discuss","hu":"kérdés, ügy"},{"forms":["back on the agenda"],"lemma":"be back on the agenda","pos":"phrase","en":"if a subject returns to the list of things to discuss, people start talking about it again","hu":"újra napirenden van, újra téma lett"},{"forms":["festival"],"lemma":"festival","pos":"noun","en":"a special day or period of religious celebration","hu":"ünnep"},{"forms":["celebrates"],"lemma":"celebrate","pos":"verb","en":"to do something special to remember an important event","hu":"ünnepel, megemlékezik valamiről"},{"forms":["resurrection"],"lemma":"resurrection","pos":"noun","en":"coming back to life after death","hu":"feltámadás"},{"forms":["following"],"lemma":"following","pos":"preposition","en":"after","hu":"után, követően"},{"forms":["crucifixion"],"lemma":"crucifixion","pos":"noun","en":"killing someone by fixing them to a wooden cross","hu":"keresztre feszítés"},{"forms":["Good Friday"],"lemma":"Good Friday","pos":"noun","en":"the Friday before Easter, when Christians remember the death of Jesus","hu":"nagypéntek"},{"forms":["in talks with"],"lemma":"be in talks with","pos":"phrase","en":"to be having official discussions with someone","hu":"tárgyalásokat folytat valakivel"},{"forms":["Pope"],"lemma":"pope","pos":"noun","en":"the leader of a church, for example the Roman Catholic Church","hu":"pápa"},{"forms":["Coptic"],"lemma":"Coptic","pos":"adjective","en":"belonging to the Christian church of Egypt","hu":"kopt (egyiptomi keresztény)"},{"forms":["Orthodox church"],"lemma":"Orthodox church","pos":"noun","en":"the Christian church of Eastern Europe and Greece","hu":"ortodox egyház"},{"forms":["Patriarch"],"lemma":"patriarch","pos":"noun","en":"the title of a leader of the Orthodox church","hu":"pátriárka"},{"forms":["retired"],"lemma":"retire","pos":"verb","en":"to stop working because you are old","hu":"nyugdíjba megy, visszavonul"},{"forms":["although"],"lemma":"although","pos":"conjunction","en":"but; despite the fact that","hu":"bár, habár"},{"forms":["warned"],"lemma":"warn","pos":"verb","en":"to tell someone about a possible problem","hu":"figyelmeztet"},{"forms":["source"],"lemma":"source","pos":"noun","en":"a person who gives information to a journalist","hu":"forrás (informátor)"},{"forms":["attempts"],"lemma":"attempt","pos":"noun","en":"an act of trying to do something","hu":"kísérlet, próbálkozás"},{"forms":["common"],"lemma":"common","pos":"adjective","en":"shared by everybody in a group","hu":"közös"},{"forms":["full moon"],"lemma":"full moon","pos":"noun","en":"the moon when you can see all of it as a complete circle","hu":"telihold"},{"forms":["spring equinox"],"lemma":"spring equinox","pos":"noun","en":"the day in March when day and night are equally long","hu":"tavaszi napéjegyenlőség"},{"forms":["falls on"],"lemma":"fall on","pos":"phrasal verb","en":"to happen on a particular day","hu":"(egy napra) esik"},{"forms":["equally"],"lemma":"equally","pos":"adverb","en":"to the same degree; the same","hu":"egyformán, ugyanolyan"},{"forms":["this means that"],"lemma":"this means that","pos":"phrase","en":"used to explain the result of what you have just said","hu":"ez azt jelenti, hogy"},{"forms":["celebrated"],"lemma":"celebrate","pos":"verb","en":"to mark a special day with religious services and special events","hu":"megünnepel, megtart (ünnepet)"},{"forms":["Julian calendar"],"lemma":"Julian calendar","pos":"noun","en":"an old calendar, used before the one most countries use today","hu":"Julianus-naptár"},{"forms":["compared with"],"lemma":"compared with","pos":"phrase","en":"when you look at how something is different from something else","hu":"valamihez képest, vala