$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2018-maj-kozep-R1$mtr$, $mtr$[{"forms":["official"],"lemma":"official","pos":"adjective","en":"approved by the government or by someone in authority","hu":"hivatalos"},{"forms":["sign language"],"lemma":"sign language","pos":"noun","en":"a language that uses hand movements instead of spoken words, used by deaf people","hu":"jelnyelv"},{"forms":["interpreter","interpreters"],"lemma":"interpreter","pos":"noun","en":"a person whose job is to change spoken words from one language into another","hu":"tolmács"},{"forms":["interpreting","interpret"],"lemma":"interpret","pos":"verb","en":"to change what someone says into another language","hu":"tolmácsol"},{"forms":["state and local courts"],"lemma":"state and local courts","pos":"phrase","en":"the courts of a US state and of a town or area","hu":"állami és helyi bíróságok"},{"forms":["officer of the court"],"lemma":"officer of the court","pos":"phrase","en":"a person who has an official job in a court","hu":"bírósági tisztviselő"},{"forms":["perform"],"lemma":"perform","pos":"verb","en":"to do a piece of work or a job","hu":"végez, ellát (feladatot)"},{"forms":["services"],"lemma":"service","pos":"noun","en":"work that someone does for other people","hu":"szolgáltatás"},{"forms":["deaf"],"lemma":"deaf","pos":"adjective","en":"not able to hear","hu":"siket"},{"forms":["hard of hearing"],"lemma":"hard of hearing","pos":"phrase","en":"not able to hear well","hu":"nagyothalló"},{"forms":["legal field"],"lemma":"legal field","pos":"noun","en":"the area of work connected with the law","hu":"jogi terület, jogi pálya"},{"forms":["actually"],"lemma":"actually","pos":"adverb","en":"really; in fact (often used to add something surprising)","hu":"valójában, tulajdonképpen","tip":"Hamis barát: nem azt jelenti, hogy aktuálisan (= currently)."},{"forms":["held this position"],"lemma":"hold a position","pos":"phrase","en":"to have a particular job","hu":"betölt