insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2018-okt-kozep-R1$mtr$, $mtr$[{"forms":["goose"],"lemma":"goose","pos":"noun","en":"a large white or grey bird with a long neck that lives near water","hu":"liba, lúd"},{"forms":["geese"],"lemma":"goose","pos":"noun","en":"more than one goose (a large bird that lives near water)","hu":"libák, ludak","tip":"Rendhagyó többes szám: goose, geese."},{"forms":["unusual"],"lemma":"unusual","pos":"adjective","en":"different from what is normal","hu":"szokatlan"},{"forms":["friendship"],"lemma":"friendship","pos":"noun","en":"a relationship between friends","hu":"barátság"},{"forms":["spotted"],"lemma":"spot","pos":"verb","en":"to see or notice something","hu":"észrevesz, megpillant"},{"forms":["tiny"],"lemma":"tiny","pos":"adjective","en":"very small","hu":"pici, apró"},{"forms":["gosling"],"lemma":"gosling","pos":"noun","en":"a baby goose","hu":"kisliba, libafióka"},{"forms":["drowning"],"lemma":"drown","pos":"verb","en":"to die under water because you cannot breathe","hu":"fuldoklik, vízbe fullad"},{"forms":["at risk of"],"lemma":"at risk of","pos":"phrase","en":"in danger of something bad happening","hu":"ki van téve valaminek, fenyegeti a veszély, hogy"},{"forms":["at any moment"],"lemma":"at any moment","pos":"phrase","en":"very soon; it could happen at any time","hu":"bármelyik pillanatban"},{"forms":["did the right thing"],"lemma":"do the right thing","pos":"phrase","en":"to do what is good or fair in a situation","hu":"helyesen cselekszik"},{"forms":["wrapped up"],"lemma":"wrap up","pos":"phrasal verb","en":"to put cloth or paper all around something","hu":"becsavar, bebugyolál"},{"forms":["towel"],"lemma":"towel","pos":"noun","en":"a piece of cloth you use to dry yourself","hu":"törölköző"},{"forms":["yards"],"lemma":"yard","pos":"noun","en":"a unit for measuring length, about 91 centimetres","hu":"yard (kb. 91 cm)"},{"forms":["sadly"],"lemma":"sadly","pos":"adverb","en":"unfortunately",