insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2018-okt-kozep-R2$mtr$, $mtr$[{"forms":["almost any kind"],"lemma":"almost any kind","pos":"phrase","en":"nearly all types","hu":"szinte bármilyen fajta"},{"forms":["puzzle"],"lemma":"puzzle","pos":"noun","en":"a game or question that you have to think hard about to solve","hu":"rejtvény, fejtörő"},{"forms":["genius"],"lemma":"genius","pos":"noun","en":"a person who is extremely clever or talented","hu":"zseni, lángelme"},{"forms":["childhood hero"],"lemma":"childhood hero","pos":"noun","en":"a person you admired very much when you were a child","hu":"gyerekkori példakép"},{"forms":["collections"],"lemma":"collection","pos":"noun","en":"a book with many pieces of the same kind in it","hu":"gyűjtemény"},{"forms":["course"],"lemma":"course","pos":"noun","en":"a series of lessons or a study programme","hu":"képzés, szak, tanfolyam"},{"forms":["accepted"],"lemma":"accept","pos":"verb","en":"if a school takes you, it lets you study there","hu":"felvesz (iskolába); elfogad"},{"forms":["of your choice"],"lemma":"of your choice","pos":"phrase","en":"that you choose yourself","hu":"saját választású, amit te választasz"},{"forms":["participants"],"lemma":"participant","pos":"noun","en":"a person who takes part in something","hu":"résztvevő"},{"forms":["crossword"],"lemma":"crossword","pos":"noun","en":"a word game where you write words into squares from clues","hu":"keresztrejtvény"},{"forms":["crosswords"],"lemma":"crossword","pos":"noun","en":"word games where you write words into squares from clues","hu":"keresztrejtvények"},{"forms":["tend to"],"lemma":"tend to","pos":"phrase","en":"to usually be or do something","hu":"általában, hajlamosak valamire"},{"forms":["smart"],"lemma":"smart","pos":"adjective","en":"clever","hu":"okos, intelligens"},{"forms":["my kind of people"],"lemma":"my kind of people","pos":"phrase","en":"people that I like and that are similar to me","hu":"hozzám hasonló emberek, az én fajtám"},{"forms":["speller"],"lemma":"speller","pos":"noun","en":"a person who writes words with the correct letters (or not)","hu":"aki jól (vagy rosszul) helyesír"},{"forms":["of course"],"lemma":"of course","pos":"phrase","en":"used to say that something is obvious","hu":"természetesen, persze"},{"forms":["wide vocabulary"],"lemma":"wide vocabulary","pos":"noun","en":"a knowledge of a lot of words","hu":"gazdag szókincs"},{"forms":["from classical to modern"],"lemma":"from classical to modern","pos":"phrase","en":"from old, traditional things to new things","hu":"a klasszikustól a modernig"},{"forms":["ran"],"lemma":"run","pos":"verb","en":"to print something in a newspaper or magazine","hu":"lehoz, közöl (újságban)","tip":"A run ige itt nem fut: újságban, folyóiratban közöl valamit."},{"forms":["standards"],"lemma":"standard","pos":"noun","en":"the level of quality that people expect","hu":"színvonal, mérce, követelmény"},{"forms":["risen"],"lemma":"rise","pos":"verb","en":"to go up; to become higher","hu":"emelkedik","tip":"Rendhagyó ige: rise, rose, risen."},{"forms":["themes"],"lemma":"theme","pos":"noun","en":"the main subject or idea of something","hu":"téma"},{"forms":["fill"],"lemma":"fill","pos":"noun","en":"in crosswords: the words you write into the squares","hu":"a kitöltő szavak (keresztrejtvényben)"},{"forms":["involves"],"lemma":"involve","pos":"verb","en":"to include something as a part","hu":"magában foglal, -ból áll"},{"forms":["copper"],"lemma":"copper","pos":"noun","en":"a reddish-brown metal","hu":"réz"},{"forms":["baking pit"],"lemma":"baking pit","pos":"noun","en":"a hole in the ground where food is cooked with hot stones","hu":"sütőgödör, földbe ásott sütő"},{"forms":["wax"],"lemma":"wax","pos":"noun","en":"a soft material used for making candles","hu":"viasz"},{"forms":["do fine"],"lemma":"do fine","pos":"phrase","en":"to be successful; to be all right","hu":"jól megállja a helyét, boldogul"},{"forms":["electronic age"],"lemma":