insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2018-okt-kozep-R3$mtr$, $mtr$[{"forms":["Twixmas"],"lemma":"Twixmas","pos":"noun","en":"the days between Christmas and New Year (from 'betwixt', an old word for 'between')","hu":"a két ünnep közötti napok"},{"forms":["for the first time ever"],"lemma":"for the first time ever","pos":"phrase","en":"it has never happened before","hu":"először a történetben, most először"},{"forms":["majestic"],"lemma":"majestic","pos":"adjective","en":"very beautiful, large and impressive","hu":"fenséges, impozáns"},{"forms":["illuminated"],"lemma":"illuminate","pos":"verb","en":"to give light to a place","hu":"kivilágít, megvilágít"},{"forms":["torches"],"lemma":"torch","pos":"noun","en":"a stick with fire at the end, used to give light","hu":"fáklya","tip":"Brit angolban a torch zseblámpát is jelent, itt a tűz miatt fáklya."},{"forms":["candles"],"lemma":"candle","pos":"noun","en":"a stick of wax that you burn to give light","hu":"gyertya"},{"forms":["magical"],"lemma":"magical","pos":"adjective","en":"special and exciting, as if made by magic","hu":"varázslatos"},{"forms":["after-dark trail"],"lemma":"after-dark trail","pos":"noun","en":"a path you can walk along in the evening when it is dark","hu":"esti (sötétedés utáni) sétaútvonal"},{"forms":["seasonal"],"lemma":"seasonal","pos":"adjective","en":"connected with a particular time of the year, here Christmas","hu":"ünnepi, az évszakhoz illő"},{"forms":["themes"],"lemma":"theme","pos":"noun","en":"the main idea used for decorating a place","hu":"téma, motívum"},{"forms":["section"],"lemma":"section","pos":"noun","en":"one of the parts that something is divided into","hu":"rész, szakasz"},{"forms":["playground"],"lemma":"playground","pos":"noun","en":"an outdoor area where children can play","hu":"játszótér"},{"forms":["of its kind"],"lemma":"of its kind","pos":"phrase","en":"of this type","hu":"a maga nemében, ilyen jellegű"},{"forms":["all year round",