insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2019-maj-emelt-R1$mtr$, $mtr$[{"forms":["Black Rod"],"lemma":"Black Rod","pos":"noun","en":"the title of an official in the British parliament who carries a black stick in ceremonies","hu":"Black Rod (a Lordok Háza ceremóniamestere, szó szerint: fekete pálca)"},{"forms":["appointed"],"lemma":"appoint","pos":"verb","en":"to choose someone officially for a job","hu":"kinevez"},{"forms":["former"],"lemma":"former","pos":"adjective","en":"having a job or position in the past, but not now","hu":"korábbi, egykori, volt"},{"forms":["championships"],"lemma":"championship","pos":"noun","en":"a competition to find the best player or team","hu":"bajnokság"},{"forms":["largely"],"lemma":"largely","pos":"adverb","en":"mostly; mainly","hu":"nagyrészt, főként"},{"forms":["ceremonial"],"lemma":"ceremonial","pos":"adjective","en":"used in or connected with formal public events","hu":"ünnepélyes, szertartási, ceremoniális"},{"forms":["parliamentary"],"lemma":"parliamentary","pos":"adjective","en":"connected with parliament","hu":"parlamenti"},{"forms":["post"],"lemma":"post","pos":"noun","en":"an important job, especially in an organization or government","hu":"tisztség, poszt, állás"},{"forms":["formally"],"lemma":"formally","pos":"adverb","en":"officially","hu":"hivatalosan"},{"forms":["Usher"],"lemma":"usher","pos":"noun","en":"an official who leads people to their places at a formal event","hu":"teremőr, ceremóniamester"},{"forms":["take over"],"lemma":"take over","pos":"phrasal verb","en":"to start doing a job that someone else did before","hu":"átveszi (a tisztséget)"},{"forms":["originating from"],"lemma":"originate from","pos":"phrasal verb","en":"to come from; to start as","hu":"valamiből ered, származik"},{"forms":["role"],"lemma":"role","pos":"noun","en":"the job or position that someone has","hu":"szerep, tisztség"},{"forms":["guard"],"lemma":"guard","pos":"verb","en":"to watch a place to protect it","hu":"őriz, őrködik"},{"forms":["advisory council"],"lemma":"advisory council","pos":"noun","en":"a group of people who give advice to a ruler","hu":"tanácsadó testület"},{"forms":["Order of the Garter"],"lemma":"Order of the Garter","pos":"noun","en":"the oldest and most important group of knights in England","hu":"Térdszalagrend"},{"forms":["senior official"],"lemma":"senior official","pos":"noun","en":"a person with a high and important position in an organization","hu":"magas rangú tisztviselő"},{"forms":["House of Lords","House of Lord’s"],"lemma":"House of Lords","pos":"noun","en":"the upper part of the British parliament, whose members are not elected","hu":"Lordok Háza (a brit parlament felsőháza)"},{"forms":["visible"],"lemma":"visible","pos":"adjective","en":"easy to see or notice","hu":"látható, szembetűnő"},{"forms":["state opening of parliament"],"lemma":"state opening of parliament","pos":"noun","en":"the ceremony when the monarch officially opens the new year of parliament","hu":"a parlamenti ülésszak ünnepélyes megnyitása"},{"forms":["the Commons","Commons"],"lemma":"the Commons","pos":"noun","en":"the House of Commons, the elected part of the British parliament","hu":"az alsóház (a brit parlament)"},{"forms":["MPs"],"lemma":"MP","pos":"noun","en":"Member of Parliament, a person elected to the House of Commons","hu":"parlamenti képviselő"},{"forms":["ceremony"],"lemma":"ceremony","pos":"noun","en":"a formal public event with traditional actions","hu":"szertartás, ceremónia"},{"forms":["involves"],"lemma":"involve","pos":"verb","en":"to include something as a necessary part","hu":"magában foglal, része"},{"forms":["slammed"],"lemma":"slam","pos":"verb","en":"to shut a door loudly and with force","hu":"becsap (ajtót)"},{"forms":["symbolize"],"lemma":"symbolize","pos":"verb","en":"to be a sign that represents an idea","hu":"jelképez"},{"forms":["independence"],"lemma":"independence","pos":"noun","en":"freedom from control by someone else","hu":"függetlenség"},{"forms":["Sovereign"],"lemma":"sovereign","pos":"noun","en":"a king or queen","hu":"uralkodó"},{"forms":["staff"],"lemma":"staff","pos":"noun","en":"a long stick that someone carries as a sign of their position","hu":"pálca, bot","tip":"Itt nem személyzet: hivatali jelvényként hordott bot."},{"forms":["ebony"],"lemma":"ebony","pos":"noun","en":"a very hard, dark black wood","hu":"ébenfa"},{"forms":["golden"],"lemma":"golden","pos":"adjective","en":"made of gold or of the colour of gold","hu":"arany, aranyszínű"},{"forms":["knock"],"lemma":"knock","pos":"verb","en":"to hit a door with your hand so people inside know you are there","hu":"kopog"},{"forms":["gain admittance"],"lemma":"gain admittance","pos":"phrase","en":"to be allowed to enter a place","hu":"bebocsátást nyer"},{"forms":["is responsible for"],"lemma":"be responsible for","pos":"phrase","en":"to have the job of taking care of something","hu":"felelős valamiért"},{"forms":["access"],"lemma":"access","pos":"noun","en":"the right or chance to enter a place","hu":"belépés, bejutás"},{"forms":["maintaining order"],"lemma":"maintain order","pos":"phrase","en":"to make sure people behave well and follow the rules","hu":"rendet tart"},{"forms":["chamber"],"lemma":"chamber","pos":"noun","en":"the large room where a parliament meets","hu":"ülésterem"},{"forms":["apart from"],"lemma":"apart from","pos":"phrase","en":"as well as; in addition to","hu":"valamin kívül"},{"forms":["doorkeepers"],"lemma":"doorkeeper","pos":"noun","en":"a person who guards the door of a building or room","hu":"ajtónálló, kapuőr"},{"forms":["department"],"lemma":"department","pos":"noun","en":"one part of a large organization","hu":"osztály, részleg"},{"forms":["deputy"],"lemma":"deputy","pos":"noun","en":"the person who is second in rank and does the job when the leader is not there","hu":"helyettes"},{"forms":["organising","organises"],"lemma":"organise","pos":"verb","en":"to plan and arrange an event","hu":"szervez"},{"fo