insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2021-maj-emelt-R2$mtr$, $mtr$[{"forms":["anxiety"],"lemma":"anxiety","pos":"noun","en":"a strong feeling of worry and nervousness","hu":"szorongás"},{"forms":["well-prepared"],"lemma":"well-prepared","pos":"adjective","en":"completely ready for something","hu":"jól felkészült"},{"forms":["blank out"],"lemma":"blank out","pos":"phrasal verb","en":"to suddenly be unable to remember anything","hu":"leblokkol, kiürül a fej"},{"forms":["freeze up"],"lemma":"freeze up","pos":"phrasal verb","en":"to suddenly be unable to move or act because you are afraid","hu":"lefagy, megdermed"},{"forms":["zone out"],"lemma":"zone out","pos":"phrasal verb","en":"to stop paying attention and not notice what is happening","hu":"elkalandoznak a gondolatai, kikapcsol"},{"forms":["respond to"],"lemma":"respond to","pos":"phrase","en":"to answer","hu":"válaszol valamire"},{"forms":["a case of"],"lemma":"a case of","pos":"phrase","en":"an example of an illness or problem","hu":"valaminek az esete"},{"forms":["about to"],"lemma":"be about to","pos":"phrase","en":"going to do something very soon","hu":"épp készül valamire, mindjárt ..."},{"forms":["anticipation"],"lemma":"anticipation","pos":"noun","en":"a feeling of waiting for something that is going to happen","hu":"várakozás, izgalom (valami előtt)"},{"forms":["intense"],"lemma":"intense","pos":"adjective","en":"very strong","hu":"erős, heves"},{"forms":["performance anxiety"],"lemma":"performance anxiety","pos":"noun","en":"being very nervous before you have to do something in front of others","hu":"teljesítményszorongás"},{"forms":["performance"],"lemma":"performance","pos":"noun","en":"how well you do something","hu":"teljesítmény"},{"forms":["counts"],"lemma":"count","pos":"verb","en":"to be important","hu":"számít, fontos"},{"forms":["solo"],"lemma":"solo","pos":"noun","en":"a piece of music that one person performs alone","hu":"szóló (ének)"},{"forms":["stage"],"lemma":"stage","pos":"noun","en":"the area in a theatre where people perform","hu":"színpad"},{"forms":["running race"],"lemma":"running race","pos":"noun","en":"a competition to see who can run fastest","hu":"futóverseny"},{"forms":["final exam"],"lemma":"final exam","pos":"noun","en":"an important test at the end of a course","hu":"záróvizsga"},{"forms":["shaky"],"lemma":"shaky","pos":"adjective","en":"shaking slightly because you are nervous or ill","hu":"remegő, reszkető"},{"forms":["sweaty"],"lemma":"sweaty","pos":"adjective","en":"wet with sweat (water from your skin)","hu":"izzadt"},{"forms":["beating"],"lemma":"beat","pos":"verb","en":"if your heart beats, it makes regular movements","hu":"ver, dobog (szív)"},{"forms":["given out"],"lemma":"give out","pos":"phrasal verb","en":"to give something to each person in a group","hu":"kioszt"},{"forms":["pass out"],"lemma":"pass out","pos":"phrasal verb","en":"to become unconscious for a short time","hu":"elájul"},{"forms":["throw up"],"lemma":"throw up","pos":"phrasal verb","en":"to bring food back up from your stomach through your mouth","hu":"hány, elhányja magát"},{"forms":["reaction","reactions"],"lemma":"reaction","pos":"noun","en":"what your body or mind does because of something","hu":"reakció, válasz"},{"forms":["stressful"],"lemma":"stressful","pos":"adjective","en":"making you feel worried and tense","hu":"stresszes, megterhelő"},{"forms":["affects"],"lemma":"affect","pos":"verb","en":"to change or influence something","hu":"hatással van, érint"},{"forms":["both"],"lemma":"both ... and","pos":"conjunction","en":"the first thing and also the second","hu":"mind ..., mind ..."},{"forms":["physical"],"lemma":"physical","pos":"adjective","en":"connected with the body","hu":"testi, fizikai"},{"forms":["symptoms"],"lemma":"symptom","pos":"noun","en":"a sign of an illness or problem","hu":"tünet"},{"forms":["sweating"],"lemma":"sweat","pos":"verb","en":"to have water coming out of your skin because you are hot or nervous","hu":"izzad, izzadás"},{"forms":["pounding"],"lemma":"pounding","pos":"adjective","en":"beating very hard and fast","hu":"hevesen dobogó, kalapáló"},{"forms":["rapid"],"lemma":"rapid","pos":"adjective","en":"very fast","hu":"gyors, szapora"},{"forms":["breathing"],"lemma":"breathing","pos":"noun","en":"taking air in and out of your body","hu":"légzés"},{"forms":["focusing on"],"lemma":"focus on","pos":"phrasal verb","en":"to give all your attention to something","hu":"összpontosít valamire"},{"forms":["fuel"],"lemma":"fuel","pos":"verb","en":"to make a feeling stronger","hu":"táplál, erősít, szít"},{"forms":["doing poorly"],"lemma":"do poorly","pos":"phrase","en":"to get a bad result","hu":"rosszul teljesít"},{"forms":["what if"],"lemma":"what if","pos":"phrase","en":"used to ask what will happen in a possible situation","hu":"mi van, ha ..."},{"forms":["perfectionists"],"lemma":"perfectionist","pos":"noun","en":"a person who wants everything to be perfect","hu":"maximalista, perfekcionista"},{"forms":["more likely to"],"lemma":"be likely to","pos":"phrase","en":"more likely to = there is a greater chance that they will","hu":"nagyobb eséllyel, hajlamosabbak"},{"forms":["have trouble with"],"lemma":"have trouble with","pos":"phrase","en":"to have problems with something","hu":"gondja van valamivel"},{"forms":["in this way"],"lemma":"in this way","pos":"phrase","en":"by doing this","hu":"így, ezáltal"},{"forms":["without meaning to"],"lemma":"without meaning to","pos":"phrase","en":"not on purpose","hu":"akaratlanul, szándékuk ellenére"},{"forms":["pressure themselves"],"lemma":"pressure yourself","pos":"phrase","en":"to make yourself feel that you must do something very well","hu":"nyomás alá helyezi magát, hajtja magát"},{"forms":["suddenly"],"lemma":"suddenly","pos":"adverb","en":"quickly and when you do not expect it","hu":"hirtelen"},{"forms":["nervous"],"lemma":"nervous","pos":"adjective","en":"worried and a little afraid","hu":"ideges, izgult"},