insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2021-maj-kozep-R1$mtr$, $mtr$[{"forms":["coping with"],"lemma":"cope with","pos":"phrasal verb","en":"to deal with a difficult situation successfully","hu":"megbirkózik valamivel"},{"forms":["colds","cold"],"lemma":"cold","pos":"noun","en":"a common illness that makes your nose run and your throat hurt","hu":"megfázás, nátha","tip":"catch a cold = megfázik."},{"forms":["despite"],"lemma":"despite","pos":"preposition","en":"without being stopped or changed by something","hu":"valami ellenére, bár","tip":"Utána nincs of, és gyakran -ing alak áll: despite being = bár ... (az)."},{"forms":["minor"],"lemma":"minor","pos":"adjective","en":"small and not very serious","hu":"kisebb, nem súlyos, enyhe"},{"forms":["illness"],"lemma":"illness","pos":"noun","en":"the state of being sick; a disease","hu":"betegség"},{"forms":["miserable"],"lemma":"miserable","pos":"adjective","en":"very unhappy and uncomfortable","hu":"nyomorult(ul érzi magát), pocsék(ul)"},{"forms":["in fact"],"lemma":"in fact","pos":"phrase","en":"used to say what is really true","hu":"valójában, tulajdonképpen"},{"forms":["infection"],"lemma":"infection","pos":"noun","en":"an illness caused by bacteria or a virus","hu":"fertőzés"},{"forms":["affect"],"lemma":"affect","pos":"verb","en":"here: to make a part of the body ill","hu":"érint, megtámad (testrészt)"},{"forms":["throat"],"lemma":"throat","pos":"noun","en":"the inside of your neck, where food and air go down","hu":"torok"},{"forms":["sinuses"],"lemma":"sinus","pos":"noun","en":"one of the empty spaces inside the bones of your face, behind your nose","hu":"orrmelléküreg, arcüreg"},{"forms":["virus","viruses"],"lemma":"virus","pos":"noun","en":"a very small living thing that causes illness","hu":"vírus"},{"forms":["gets through"],"lemma":"get through","pos":"phrasal verb","en":"to pass through something and get inside","hu":"átjut, bejut"},{"forms":["immune system"],"lemma":"im