insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2021-okt-emelt-R1$mtr$, $mtr$[{"forms":["struggle"],"lemma":"struggle","pos":"verb","en":"to try very hard to do something that is difficult","hu":"küszködik, nehezen boldogul","tip":"A szövegben főnévként is: a struggle = küzdelem, nehézség."},{"forms":["hire"],"lemma":"hire","pos":"verb","en":"to give someone a job","hu":"alkalmaz, felvesz (munkára)"},{"forms":["overseas"],"lemma":"overseas","pos":"adjective","en":"from another country, especially one across the sea","hu":"külföldi, tengerentúli"},{"forms":["harvest"],"lemma":"harvest","pos":"noun","en":"the time when crops are picked; the crops that are picked","hu":"betakarítás, termés","tip":"Igeként (harvest) is szerepel: betakarít, leszed."},{"forms":["recruit"],"lemma":"recruit","pos":"verb","en":"to find new people to work for you","hu":"toboroz, munkaerőt keres"},{"forms":["roughly"],"lemma":"roughly","pos":"adverb","en":"about; not exactly","hu":"nagyjából, körülbelül"},{"forms":["seasonal workers"],"lemma":"seasonal worker","pos":"noun","en":"a person who works only during one part of the year, e.g. at harvest time","hu":"idénymunkás"},{"forms":["lettuce"],"lemma":"lettuce","pos":"noun","en":"a green vegetable with large leaves, eaten in salads","hu":"fejes saláta"},{"forms":["radishes"],"lemma":"radish","pos":"noun","en":"a small red root vegetable with a hot taste","hu":"retek"},{"forms":["extensive"],"lemma":"extensive","pos":"adjective","en":"very large in area","hu":"kiterjedt, nagy területű"},{"forms":["previous"],"lemma":"previous","pos":"adjective","en":"happening before now","hu":"korábbi, előző"},{"forms":["turn up"],"lemma":"turn up","pos":"phrasal verb","en":"to arrive or come to an event","hu":"megjelenik, eljön"},{"forms":["human resources director"],"lemma":"human resources director","pos":"noun","en":"the manager responsible for hiring and looking after workers","hu":"HR-igazgató, humánerőforrás-igazgató"},{"fo