insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2023-okt-kozep-R2$mtr$, $mtr$[{"forms":["dealing with"],"lemma":"deal with","pos":"phrasal verb","en":"to do something to solve a problem or control a difficult situation","hu":"megbirkózik valamivel, kezel"},{"forms":["stress"],"lemma":"stress","pos":"noun","en":"a feeling of worry caused by difficult situations","hu":"stressz, feszültség"},{"forms":["have fun"],"lemma":"have fun","pos":"phrase","en":"to enjoy yourself","hu":"jól szórakozik"},{"forms":["while"],"lemma":"while","pos":"conjunction","en":"during the time that","hu":"miközben"},{"forms":["staying fit"],"lemma":"stay fit","pos":"phrase","en":"to stay healthy and strong by doing exercise","hu":"fitt marad, formában marad"},{"forms":["working as a team"],"lemma":"work as a team","pos":"phrase","en":"to work together with other people","hu":"csapatban dolgozik, együttműködik"},{"forms":["overcoming"],"lemma":"overcome","pos":"verb","en":"to succeed in dealing with a problem","hu":"legyőz, leküzd"},{"forms":["challenges","challenge"],"lemma":"challenge","pos":"noun","en":"something difficult that tests your strength or skill","hu":"kihívás, nehéz feladat"},{"forms":["keep it together"],"lemma":"keep it together","pos":"idiom","en":"to stay calm and in control in a difficult situation","hu":"megőrzi a nyugalmát, nem esik szét"},{"forms":["winning is everything"],"lemma":"winning is everything","pos":"phrase","en":"the only important thing is to win","hu":"csak a győzelem számít"},{"forms":["perform your best"],"lemma":"perform your best","pos":"phrase","en":"to do something as well as you possibly can","hu":"a legjobb formáját hozza, a tőle telhető legjobban teljesít"},{"forms":["competing"],"lemma":"compete","pos":"verb","en":"to try to win against other people","hu":"versenyez"},{"forms":["leads to"],"lemma":"lead to","pos":"phrasal verb","en":"to cause something; to have something as a result","hu":"vezet valamihez, okoz"},{"fo