insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2024-maj-emelt-R4$mtr$, $mtr$[{"forms":["word of the year"],"lemma":"word of the year","pos":"noun","en":"a word chosen as the most important or typical one of a year","hu":"az év szava"},{"forms":["hallucinate","hallucinates","hallucinating"],"lemma":"hallucinate","pos":"verb","en":"to seem to see or hear things that are not really there; for AI: to produce false information","hu":"hallucinál, képzelődik"},{"forms":["original"],"lemma":"original","pos":"adjective","en":"first, earliest","hu":"eredeti"},{"forms":["definition"],"lemma":"definition","pos":"noun","en":"an explanation of what a word means","hu":"meghatározás, jelentés (szótárban)"},{"forms":["chosen"],"lemma":"choose","pos":"verb","en":"to pick one thing from several","hu":"kiválaszt"},{"forms":["exist"],"lemma":"exist","pos":"verb","en":"to be real","hu":"létezik"},{"forms":["health condition"],"lemma":"health condition","pos":"noun","en":"an illness or a health problem","hu":"egészségi állapot, betegség"},{"forms":["additional"],"lemma":"additional","pos":"adjective","en":"extra, more","hu":"további, újabb"},{"forms":["relating to"],"lemma":"relate to","pos":"phrasal verb","en":"to be connected with something","hu":"vonatkozik valamire, kapcsolódik valamihez"},{"forms":["artificial intelligence"],"lemma":"artificial intelligence","pos":"noun","en":"computer systems that can do things that need human intelligence","hu":"mesterséges intelligencia"},{"forms":["systems"],"lemma":"system","pos":"noun","en":"a group of computer programs that work together","hu":"rendszer"},{"forms":["such as"],"lemma":"such as","pos":"phrase","en":"for example","hu":"például, mint például"},{"forms":["generates"],"lemma":"generate","pos":"verb","en":"to produce or create something","hu":"létrehoz, előállít"},{"forms":["mimics"],"lemma":"mimic","pos":"verb","en":"to copy the way someone does something","hu":"utánoz"},{"forms":["gets to the heart o