insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2024-maj-kozep-R1$mtr$, $mtr$[{"forms":["faqs"],"lemma":"FAQ","pos":"noun","en":"frequently asked questions: questions that many people ask, with their answers","hu":"gyakran ismételt kérdések (GYIK)"},{"forms":["illusions"],"lemma":"illusion","pos":"noun","en":"something that tricks your eyes, so you see something that is not really there","hu":"(optikai) illúzió, érzékcsalódás"},{"forms":["visitor attraction"],"lemma":"visitor attraction","pos":"noun","en":"a place that people visit for interest or fun","hu":"látványosság, turistalátványosság"},{"forms":["attractions","attraction"],"lemma":"attraction","pos":"noun","en":"a place that people visit for interest or fun","hu":"látványosság"},{"forms":["delighting"],"lemma":"delight","pos":"verb","en":"to make someone very happy","hu":"elkápráztat, örömet szerez"},{"forms":["get around"],"lemma":"get around","pos":"phrasal verb","en":"to go to all parts of a place","hu":"végigjár, bejár"},{"forms":["as long as you like"],"lemma":"as long as you like","pos":"phrase","en":"for as much time as you want","hu":"ameddig csak szeretnéd"},{"forms":["spaces"],"lemma":"space","pos":"noun","en":"here: free places, tickets that nobody has bought yet","hu":"szabad hely"},{"forms":["available"],"lemma":"available","pos":"adjective","en":"that you can get or use","hu":"elérhető, szabad"},{"forms":["purchase"],"lemma":"purchase","pos":"verb","en":"to buy something","hu":"megvásárol, vesz"},{"forms":["on the day"],"lemma":"on the day","pos":"phrase","en":"on the same day when you visit, not earlier","hu":"aznap, a látogatás napján"},{"forms":["front desk"],"lemma":"front desk","pos":"noun","en":"the desk near the entrance where you can buy tickets and ask questions","hu":"recepció, pénztár"},{"forms":["however"],"lemma":"however","pos":"adverb","en":"but; used when you add something different","hu":"azonban, viszont"},{"forms":["recommend"],"lemma":"recommend","pos":"verb","en":"to say that something is a good idea","hu":"ajánl, javasol"},{"forms":["booking"],"lemma":"book","pos":"verb","en":"to arrange to have a ticket at a later time","hu":"lefoglal, előre megvesz"},{"forms":["in advance"],"lemma":"in advance","pos":"phrase","en":"before the time when something happens","hu":"előre, időben"},{"forms":["to avoid disappointment"],"lemma":"avoid disappointment","pos":"phrase","en":"so that you are not sad because something you wanted is not possible","hu":"hogy ne érjen csalódás"},{"forms":["grandparents"],"lemma":"grandparent","pos":"noun","en":"the mother or father of your mother or father","hu":"nagyszülő"},{"forms":["hard-to-impress"],"lemma":"hard-to-impress","pos":"adjective","en":"not easily excited or interested by things","hu":"akit nehéz lenyűgözni"},{"forms":["storage area"],"lemma":"storage area","pos":"noun","en":"a place where things can be kept for a time","hu":"tároló, csomagmegőrző"},{"forms":["items"],"lemma":"item","pos":"noun","en":"a thing, one of several things","hu":"tárgy, holmi"},{"forms":["suitcases"],"lemma":"suitcase","pos":"noun","en":"a large bag or box with a handle for carrying clothes when you travel","hu":"bőrönd"},{"forms":["backpacks"],"lemma":"backpack","pos":"noun","en":"a bag that you carry on your back","hu":"hátizsák"},{"forms":["please note"],"lemma":"please note","pos":"phrase","en":"please remember this important information","hu":"kérjük, vegye figyelembe"},{"forms":["stored"],"lemma":"store","pos":"verb","en":"to put something somewhere and keep it there","hu":"tárol, megőriz"},{"forms":["for the duration of"],"lemma":"for the duration of","pos":"phrase","en":"during the whole time of","hu":"... ideje alatt, ... idejére"},{"forms":["17th-century"],"lemma":"17th-century","pos":"adjective","en":"from the years 1600–1699","hu":"17. századi"},{"forms":["listed"],"lemma":"listed","pos":"adjective","en":"officially protected because it is old or important (about a building)","hu":"műemlékvédelem alatt álló"},{"forms":["for the time being"],"lemma":"for the time being","pos":"phrase","en":"now, but maybe not in the future","hu":"egyelőre, jelenleg"},{"forms":["stairs-only"],"lemma":"stairs-only","pos":"adjective","en":"that you can only go up or down by stairs, there is no lift","hu":"csak lépcsőn járható (nincs lift)"},{"forms":["on-site"],"lemma":"on-site","pos":"adjective","en":"in the same place or building","hu":"helyszíni, a helyszínen működő"},{"forms":["money off"],"lemma":"money off","pos":"phrase","en":"a lower price","hu":"kedvezmény, árengedmény"},{"forms":["several"],"lemma":"several","pos":"adjective","en":"more than two, but not many","hu":"több, néhány"},{"forms":["nearby"],"lemma":"nearby","pos":"adjective","en":"not far away","hu":"közeli, közelben lévő"},{"forms":["pride ourselves on"],"lemma":"pride yourself on","pos":"phrase","en":"to be proud of something you do well","hu":"büszkék vagyunk arra, hogy"},{"forms":["pet-friendly"],"lemma":"pet-friendly","pos":"adjective","en":"where pets are welcome","hu":"kisállatbarát, ahová háziállat is bevihető"},{"forms":["furry"],"lemma":"furry","pos":"adjective","en":"covered with soft hair","hu":"szőrös, bundás"},{"forms":["treat"],"lemma":"treat","pos":"noun","en":"something nice that you give someone, often food","hu":"finomság, jutalomfalat"},{"forms":["biscuit"],"lemma":"biscuit","pos":"noun","en":"a small, flat, dry cake; here: a hard snack for dogs","hu":"keksz (itt: kutyakeksz)"},{"forms":["on arrival","on your arrival"],"lemma":"arrival","pos":"noun","en":"the moment when you arrive","hu":"érkezéskor"},{"forms":["connect"],"lemma":"connect","pos":"verb","en":"here: to join the internet (Wi-Fi)","hu":"csatlakozik (a wifihez)"},{"forms":["access code"],"lemma":"access code","pos":"noun","en":"a secret number or word that lets you use something","hu":"belépési kód, jelszó"},{"forms":["admissions desk"],"lemma":"admissions desk","pos":"noun","en":"the place where you buy tickets and go in","hu":"pénztár, beléptetés"},{"forms":["photography"],"lemma":"photography","pos":"noun","en":"taking photos","hu":"fényképezés"},{"forms":["allowed"],"lemma":"allow","pos":"verb","en":"to let someone do something","hu":"megenged, szabad"},{"forms":["except"],"lemma":"except","pos":"preposition","en":"but not; apart from","hu":"kivéve"},{"forms":["chamber"],"lemma":"chamber","pos":"noun","en":"a room used for a special purpose","hu":"terem, kamra"},{"forms":["tagging"],"lemma":"tag","pos":"verb","en":"to add someone's name to a photo or post on social media","hu":"megjelöl (közösségi médiában)"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2024-maj-kozep-R2$mtr$, $mtr$[{"forms":["take down"],"lemma":"take down","pos":"phrasal verb","en":"to remove something from a wall or a high place","hu":"leszed, levesz"},{"forms":["decorations"],"lemma":"decoration","pos":"noun","en":"a pretty thing that you put on something to make it look nice","hu":"díszítés, (karácsonyi) dísz"},{"forms":["trickiest"],"lemma":"tricky","pos":"adjective","en":"the most difficult to answer or deal with","hu":"legkényesebb, legnehezebb"},{"forms":["remove"],"lemma":"remove","pos":"verb","en":"to take something away","hu":"eltávolít, leszed"},{"forms":["put their decorations up"],"lemma":"put up","pos":"phrasal verb","en":"to put something in a place where people can see it","hu":"feltesz, kitesz (díszt)"},{"forms":["come January"],"lemma":"come","pos":"preposition","en":"when a certain time arrives","hu":"amikor eljön január, januárra"},{"forms":["even more"],"lemma":"even more","pos":"phrase","en":"a larger number than before","hu":"még többen"},{"forms":["wondering"],"lemma":"wonder","pos":"verb","en":"to think about something and want to know the answer","hu":"töpreng, azon gondolkodik"},{"forms":["point out"],"lemma":"point out","pos":"phrasal verb","en":"to tell someone about a fact","hu":"rámutat, megjegyez"},{"forms":["though"],"lemma":"though","pos":"adverb","en":"however; used to add a different idea","hu":"azonban, ugyanakkor"},{"forms":["definite"],"lemma":"definite","pos":"adjective","en":"clear and certain","hu":"határozott, egyértelmű, pontos"},{"forms":["rules"],"lemma":"rule","pos":"noun","en":"what you must or must not do","hu":"szabály"},{"forms":["right after"],"lemma":"right after","pos":"phrase","en":"immediately after","hu":"közvetlenül ... után"},{"forms":["argue"],"lemma":"argue","pos":"verb","en":"to say that something is true and give reasons","hu":"érvel, állítja"},{"forms":["comes along"],"lemma":"come along","pos":"phrasal ve