insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2024-maj-kozep-R3$mtr$, $mtr$[{"forms":["definitely"],"lemma":"definitely","pos":"adverb","en":"certainly; without any doubt","hu":"biztosan, egészen biztos, hogy"},{"forms":["guide"],"lemma":"guide","pos":"noun","en":"a text that gives you useful information and advice about something","hu":"útmutató, ismertető"},{"forms":["sections"],"lemma":"section","pos":"noun","en":"one of the parts that something is divided into","hu":"rész, szakasz"},{"forms":["option"],"lemma":"option","pos":"noun","en":"a choice that you can make","hu":"lehetőség, választási lehetőség"},{"forms":["draws","draw"],"lemma":"draw","pos":"noun","en":"something that makes people want to go to a place","hu":"vonzerő, fő látványosság","tip":"Itt főnév. Igeként (draw) azt jelenti: rajzol, illetve vonz."},{"forms":["rhinos"],"lemma":"rhino","pos":"noun","en":"a large heavy animal with thick skin and one or two horns on its nose (short for rhinoceros)","hu":"orrszarvú"},{"forms":["aquarium"],"lemma":"aquarium","pos":"noun","en":"a building where people can look at fish and other water animals","hu":"akvárium (az épület)"},{"forms":["indoor"],"lemma":"indoor","pos":"adjective","en":"inside a building","hu":"fedett, beltéri"},{"forms":["play area"],"lemma":"play area","pos":"noun","en":"a place where children can play","hu":"játszótér, játszósarok"},{"forms":["rainier"],"lemma":"rainy","pos":"adjective","en":"rainier = more rainy; with more rain","hu":"esősebb"},{"forms":["safari parks"],"lemma":"safari park","pos":"noun","en":"a large park where wild animals live freely and visitors can drive through it to see them","hu":"szafaripark"},{"forms":["wildlife reserve"],"lemma":"wildlife reserve","pos":"noun","en":"an area of land where wild animals are protected","hu":"vadrezervátum, természetvédelmi terület"},{"forms":["stay overnight"],"lemma":"stay overnight","pos":"phrase","en":"to stay somewhere for the night and sleep there","hu":"ott éjszakázik, ott alszik"},{"forms":["themed"],"lemma":"themed","pos":"adjective","en":"designed and decorated around one idea or subject","hu":"tematikus, egy téma köré épülő"},{"forms":["yurts"],"lemma":"yurt","pos":"noun","en":"a round tent with a wooden frame, first used in Central Asia","hu":"jurta"},{"forms":["cabins"],"lemma":"cabin","pos":"noun","en":"a small wooden house, often in the countryside","hu":"faház, kabin"},{"forms":["overlooking"],"lemma":"overlook","pos":"verb","en":"if a building overlooks something, you can see it from there, usually from above","hu":"valamire néz, kilátás nyílik belőle valamire"},{"forms":["private"],"lemma":"private","pos":"adjective","en":"owned and run by a person or a company, not by the state","hu":"magán- (nem állami)"},{"forms":["entrance fees"],"lemma":"entrance fee","pos":"noun","en":"the money that you pay to go into a place","hu":"belépődíj"},{"forms":["purchases"],"lemma":"purchase","pos":"noun","en":"something that you buy; the act of buying something","hu":"vásárlás, a megvett dolgok"},{"forms":["go towards"],"lemma":"go towards","pos":"phrasal verb","en":"if money goes towards something, it is used to help pay for it","hu":"valamire fordítják, valamire megy (pénz)"},{"forms":["upkeep"],"lemma":"upkeep","pos":"noun","en":"the work and money needed to keep something in good condition","hu":"fenntartás, fenntartási költség"},{"forms":["charity"],"lemma":"charity","pos":"noun","en":"an organization that collects money to help people or animals in need","hu":"jótékonysági szervezet, alapítvány"},{"forms":["opportunities"],"lemma":"opportunity","pos":"noun","en":"a chance to do something","hu":"lehetőség, alkalom"},{"forms":["hand feed"],"lemma":"hand feed","pos":"verb","en":"to give food to an animal from your hand","hu":"kézből etet"},{"forms":["goats"],"lemma":"goat","pos":"noun","en":"a farm animal with horns, a little bigger than a sheep","hu":"kecske"},{"forms":["rainbow lorikeets"],"lemma":"rainbo