insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2025-maj-kozep-R4$mtr$, $mtr$[{"forms":["sets record"],"lemma":"set a record","pos":"phrase","en":"to do something that nobody has done before, or better than anyone before","hu":"rekordot állít fel, csúcsot dönt"},{"forms":["pair"],"lemma":"pair","pos":"noun","en":"two people who are together","hu":"pár"},{"forms":["get married","got married"],"lemma":"get married","pos":"phrase","en":"to become husband and wife","hu":"összeházasodik, megházasodik"},{"forms":["in their 90s"],"lemma":"in your 90s","pos":"phrase","en":"between 90 and 99 years old","hu":"kilencvenes éveiben"},{"forms":["full lives"],"lemma":"full life","pos":"noun","en":"a life with a lot of activity and experiences","hu":"tartalmas, gazdag élet"},{"forms":["neither of them"],"lemma":"neither of","pos":"phrase","en":"not one and not the other of two people","hu":"egyikük sem"},{"forms":["they’d"],"lemma":"they'd","pos":"phrase","en":"a short form of they would or they had","hu":"they would / they had rövidítése","tip":"Itt kétféle: they’d fall in love = would (hogy beleszeretnek), they’d both attended = had (mindketten jártak)."},{"forms":["fall in love","fell in love"],"lemma":"fall in love","pos":"phrase","en":"to start to love someone","hu":"beleszeret valakibe"},{"forms":["end up"],"lemma":"end up","pos":"phrasal verb","en":"to be in a situation at the end, often without planning it","hu":"végül valahogy alakul, végül ... lesz"},{"forms":["married couple"],"lemma":"married couple","pos":"noun","en":"a husband and wife","hu":"házaspár"},{"forms":["combined age"],"lemma":"combined age","pos":"noun","en":"the ages of two or more people added together","hu":"együttes életkor"},{"forms":["engineer"],"lemma":"engineer","pos":"noun","en":"a person who designs machines, roads, bridges etc.","hu":"mérnök"},{"forms":["marriages"],"lemma":"marriage","pos":"noun","en":"the relationship between a husband and wife","hu":"házasság"},{