:["exploring"],"lemma":"explore","pos":"verb","en":"to travel through a place to learn about it","hu":"felfedez, kutat"},{"forms":["amazed"],"lemma":"amazed","pos":"adjective","en":"very surprised","hu":"elképedt, megdöbbent"},{"forms":["anything like"],"lemma":"anything like","pos":"phrase","en":"(in negatives) anywhere near; nearly","hu":"megközelítőleg sem"},{"forms":["suspect"],"lemma":"suspect","pos":"verb","en":"to think something is probably true","hu":"gyanít, sejt"},{"forms":["bed of the sea"],"lemma":"bed of the sea","pos":"noun","en":"the ground at the bottom of the sea","hu":"tengerfenék"},{"forms":["particularly"],"lemma":"particularly","pos":"adverb","en":"especially","hu":"különösen"},{"forms":["crucial"],"lemma":"crucial","pos":"adjective","en":"extremely important","hu":"döntő, kulcsfontosságú"},{"forms":["implications"],"lemma":"implication","pos":"noun","en":"a possible effect or result","hu":"következmény, kihatás"},{"forms":["erupt"],"lemma":"erupt","pos":"verb","en":"(of a volcano) to send out smoke, fire and melted rock","hu":"kitör"},{"forms":["further"],"lemma":"further","pos":"adverb","en":"more; to a greater degree","hu":"tovább, még jobban"},{"forms":["destabilise"],"lemma":"destabilise","pos":"verb","en":"to make something less firm or steady","hu":"meggyengít, instabillá tesz"},{"forms":["affected by","affecting"],"lemma":"affect","pos":"verb","en":"to have an effect on something, often a bad one","hu":"hat valamire, érint"},{"forms":["global warming"],"lemma":"global warming","pos":"noun","en":"the rise in the Earth's temperature caused by pollution","hu":"globális felmelegedés"},{"forms":["meltwater"],"lemma":"meltwater","pos":"noun","en":"water that comes from melting ice or snow","hu":"olvadékvíz"},{"forms":["provoke"],"lemma":"provoke","pos":"verb","en":"to cause something to happen","hu":"kivált, előidéz"},{"forms":["sea level rises"],"lemma":"sea level rise","pos":"noun","en":"an increase in the height of the sea","hu":"tengerszint-emelkedés"},{"forms":["intensifying"],"lemma":"intensify","pos":"verb","en":"to make something stronger or more extreme","hu":"felerősít, fokoz"}]$mtr$::jsonb, $mtr$[]$mtr$::jsonb)
insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2025-okt-emelt-R3$mtr$, $mtr$[{"forms":["fake"],"lemma":"fake","pos":"adjective","en":"not real; false","hu":"hamis, ál-"},{"forms":["quotes","quote"],"lemma":"quote","pos":"noun","en":"words that someone said or wrote, repeated by another person","hu":"idézet"},{"forms":["thought-provoking"],"lemma":"thought-provoking","pos":"adjective","en":"making you think seriously about something","hu":"elgondolkodtató"},{"forms":["sentiment"],"lemma":"sentiment","pos":"noun","en":"a thought, opinion or feeling expressed in words","hu":"gondolat, érzés"},{"forms":["tempted"],"lemma":"be tempted","pos":"phrase","en":"to want to do something","hu":"kísértést érez, szívesen megtenné"},{"forms":["impulse"],"lemma":"impulse","pos":"noun","en":"a sudden strong wish to do something","hu":"késztetés, ösztönzés"},{"forms":["struck"],"lemma":"strike","pos":"verb","en":"(of an idea or feeling) to come suddenly to someone","hu":"megkap, elfog (érzés, ötlet)","tip":"Rendhagyó ige: strike – struck – struck."},{"forms":["postal service"],"lemma":"postal service","pos":"noun","en":"the organization that delivers letters and parcels","hu":"posta, postaszolgálat"},{"forms":["put it out"],"lemma":"put out","pos":"phrasal verb","en":"to produce and publish something","hu":"kiad, megjelentet"},{"forms":["stamp"],"lemma":"stamp","pos":"noun","en":"a small piece of paper you stick on a letter to pay for posting it","hu":"bélyeg"},{"forms":["bearing"],"lemma":"bear","pos":"verb","en":"to have or show something","hu":"visel, ábrázol (rajta van)"},{"forms":["former"],"lemma":"former","pos":"adjective","en":"having been something in the past","hu":"egykori, korábbi"},{"forms":["professor"],"lemma":"professor","pos":"noun","en":"a university teacher of the highest level","hu":"egyetemi tanár, professzor"},{"forms":["calypso"],"lemma":"calypso","pos":"noun","en":"a type of Caribbean music","hu":"calypso (karibi zenei stílus)"},