insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2026-maj-emelt-R4$mtr$, $mtr$[{"forms":["affects"],"lemma":"affect","pos":"verb","en":"to have an influence on something","hu":"hat valamire, befolyásol"},{"forms":["phenomenon"],"lemma":"phenomenon","pos":"noun","en":"something that happens or exists","hu":"jelenség","tip":"Többes száma: phenomena."},{"forms":["now that"],"lemma":"now that","pos":"conjunction","en":"because this is the situation at present","hu":"most, hogy; mivel már"},{"forms":["heating"],"lemma":"heating","pos":"noun","en":"a system that keeps a building warm","hu":"fűtés"},{"forms":["locking doors"],"lemma":"locking door","pos":"noun","en":"a door that you can close with a key","hu":"zárható ajtó"},{"forms":["no longer"],"lemma":"no longer","pos":"phrase","en":"not any more","hu":"már nem"},{"forms":["relief"],"lemma":"relief","pos":"noun","en":"a feeling that pain or worry has become less","hu":"megkönnyebbülés, enyhülés"},{"forms":["nightmares"],"lemma":"nightmare","pos":"noun","en":"a very bad, frightening dream","hu":"rémálom"},{"forms":["post-traumatic stress disorder"],"lemma":"post-traumatic stress disorder","pos":"noun","en":"a mental illness after a very shocking experience (PTSD)","hu":"poszttraumás stressz-szindróma"},{"forms":["provide"],"lemma":"provide","pos":"verb","en":"to give something that people need","hu":"nyújt"},{"forms":["comfort"],"lemma":"comfort","pos":"noun","en":"a feeling of being less worried or sad","hu":"vigasz, megnyugvás"},{"forms":["reduce"],"lemma":"reduce","pos":"verb","en":"to make something smaller or less","hu":"csökkent"},{"forms":["anxiety"],"lemma":"anxiety","pos":"noun","en":"a feeling of being very worried","hu":"szorongás"},{"forms":["loneliness"],"lemma":"loneliness","pos":"noun","en":"being unhappy because you are alone","hu":"magány"},{"forms":["ease"],"lemma":"ease","pos":"verb","en":"to make pain or a problem less bad","hu":"enyhít"},{"forms":["symptoms"],"lemma":"s