insert into public.task_glossary (task_id, entries, after_submit) values ($mtr$2026-maj-kozep-R1$mtr$, $mtr$[{"forms":["animal welfare"],"lemma":"animal welfare","pos":"noun","en":"the health and happiness of animals, and protecting them","hu":"állatjólét, állatvédelem"},{"forms":["trust"],"lemma":"trust","pos":"noun","en":"an organization that looks after money or property to help others","hu":"alapítvány","tip":"Itt nem bizalmat jelent, hanem szervezetet (alapítványt)."},{"forms":["FAQs"],"lemma":"FAQ","pos":"noun","en":"frequently asked questions: questions that people often ask","hu":"GYIK (gyakran ismételt kérdések)"},{"forms":["commonly"],"lemma":"commonly","pos":"adverb","en":"often; by many people","hu":"gyakran, általában"},{"forms":["adopting"],"lemma":"adopt","pos":"verb","en":"to take an animal or child into your home and look after it as your own","hu":"örökbe fogad"},{"forms":["volunteering"],"lemma":"volunteer","pos":"verb","en":"to work without pay to help others","hu":"önkéntes munkát végez; volunteering = önkéntesség"},{"forms":["in return for"],"lemma":"in return for","pos":"phrase","en":"as payment or exchange for something","hu":"cserébe valamiért"},{"forms":["receive"],"lemma":"receive","pos":"verb","en":"to get something that is given to you","hu":"kap, megkap"},{"forms":["vet-checked"],"lemma":"vet-checked","pos":"adjective","en":"looked at by an animal doctor","hu":"állatorvos által megvizsgált"},{"forms":["vaccinated"],"lemma":"vaccinate","pos":"verb","en":"to give a person or animal an injection to protect them from a disease","hu":"beolt; vaccinated = beoltott"},{"forms":["microchipped"],"lemma":"microchip","pos":"verb","en":"to put a very small electronic chip under an animal's skin so it can be identified","hu":"csipet ültet be; microchipped = chipezett"},{"forms":["homefinder form"],"lemma":"homefinder form","pos":"noun","en":"a form you fill in if you want to give an animal a home","hu":"örökbefogadási jelentkezési lap"},{"forms":["available"],"lemma":"available","pos":"adjective","en":"free to be taken or used","hu":"elérhető, még gazdára vár"},{"forms":["get in contact with"],"lemma":"get in contact with","pos":"phrase","en":"to phone or write to someone","hu":"felveszi a kapcsolatot valakivel"},{"forms":["absolutely"],"lemma":"absolutely","pos":"adverb","en":"yes, certainly","hu":"feltétlenül, természetesen"},{"forms":["caring"],"lemma":"care","pos":"verb","en":"to look after someone and be interested in them","hu":"törődik, gondoskodik"},{"forms":["whatever"],"lemma":"whatever","pos":"pronoun","en":"any thing at all","hu":"bármilyen, akármilyen"},{"forms":["certainly"],"lemma":"certainly","pos":"adverb","en":"yes, of course","hu":"természetesen, persze"},{"forms":["arrange"],"lemma":"arrange","pos":"verb","en":"to plan and organize","hu":"megszervez, megbeszél"},{"forms":["in-shelter"],"lemma":"in-shelter","pos":"adjective","en":"happening inside the animal shelter (a place for homeless animals)","hu":"menhelyi, a menhelyen tartott"},{"forms":["pet-introduction session"],"lemma":"pet-introduction session","pos":"noun","en":"a meeting where two animals see each other for the first time","hu":"állatok bemutatása egymásnak, ismerkedés"},{"forms":["get on"],"lemma":"get on","pos":"phrasal verb","en":"to have a friendly relationship","hu":"kijönnek egymással, megférnek"},{"forms":["a selection of"],"lemma":"a selection of","pos":"phrase","en":"a number of things chosen from a larger group","hu":"néhány, egy sor (válogatott)"},{"forms":["please note"],"lemma":"please note","pos":"phrase","en":"used to ask someone to pay attention to an important fact","hu":"kérjük, vegye figyelembe; felhívjuk a figyelmet"},{"forms":["waiting lists"],"lemma":"waiting list","pos":"noun","en":"a list of people who must wait for something","hu":"várólista"},{"forms":["accept"],"lemma":"accept","pos":"verb","en":"to take something that is offered","hu":"elfogad, befogad"},{"forms":["immediately"],"lemma":"immediately",